enum PNLE_PartsDisplay {
	PNLE_PartsDisplay_NoChange	= 0
	                              ,PNLE_PartsDisplay_Show
	,PNLE_PartsDisplay_Hide
};
#define	PNLD_PartsDisplayChange( parts, kind )		\
{													\
	if ( PNLE_PartsDisplay_Show == kind ) {			\
		parts.showEnable( True );					\
	}												\
	else if ( PNLE_PartsDisplay_Hide == kind ) {	\
		parts.showEnable( False );					\
	}												\
}

