		case EP_CharSet_Big5:		e_CharSet = TYPE_CharSetBIG5;		break;	//【中韓台文字コード指定追加】.
		case EP_CharSet_ISO8859_5:	e_CharSet = TYPE_CharSetISO8859_5;	break;	// ISO8859-5(Cyrillic)
		case EP_CharSet_ISO8859_7:	e_CharSet = TYPE_CharSetISO8859_7;	break;	// ISO8859-7(Greek)
// comment 2018/12/14 Sky毛穴 [EagleHigh][RQ-258] タイ語とベトナム語の対応.
		case EP_CharSet_WindowsCP874:	e_CharSet = TYPE_CharSetWindowsCP_874;	break;	// タイ語.
		case EP_CharSet_Viscii	:		e_CharSet = TYPE_CharSetViscii;	break;	// ベトナム語.
// comment 2022/11/9 Sky奥田 [RQ-938] バルト三国対応.
// comment 2023/01/10 Sky門 [RQ-938] バルト三国対応.
		case EP_CharSet_ISO8859_4:		e_CharSet = TYPE_CharSetISO8859_4;		break;	// ISO8859-4(Latin-4).
		case EP_CharSet_WindowsCP1257:	e_CharSet = TYPE_CharSetWindowsCP_1257;	break;	// バルト言語.
// comment 2023/4/17 Sky村田 [IT6_2.3][RQ-970]Welsh as standard language for IT.
		case EP_CharSet_ISO8859_14:		e_CharSet = TYPE_CharSetISO8859_14;		break;
