		case EP_CharSet_ISO8859_7:	e_TYPE_CharSet = TYPE_CharSetISO8859_7;	break;	// ISO8859-7(Greek).
		case EP_CharSet_ISO8859_9:	e_TYPE_CharSet = TYPE_CharSetISO8859_9;	break;	// ISO8859-9.
		case EP_CharSet_WindowsCP1256:	e_TYPE_CharSet = TYPE_CharSetWindowsCP_1256;	break;	// WindowsCodePage1256.
// comment 2015/06/10 OPS1-Sky森川(篤) [ZeusS_ZX0][RQ-405] パネルUIのヘブライ語対応.
		case EP_CharSet_WindowsCP1255:	e_TYPE_CharSet = TYPE_CharSetWindowsCP_1255;	break;	// WindowsCodePage1255.
