void getWarningPaperSizeKind(
    APIC_Job* pc_Job,					// 対象ジョブのポインタ
    TYPC_PaperSize* pc_PaperSize,		// 用紙サイズ
    TEXT_ID* puc_PaperKindParts,		// 用紙種類の文字列パーツ
    TEXT_ID* puc_SpecialPaperKindParts,	// 特殊用紙種類の文字列パーツ
    Bool* pb_is2ndSidedPaper,				// 両面２面目か？ True:両面２面目
    TYPE_CustomPaperType* pe_CustomPaperType )	// カスタム用紙属性.
{
	register TYPE_PaperType _ep_PaperKind;
	*pb_is2ndSidedPaper = False;			// 両面２面目取得用 k.inui 02/03/29
	_getWarningFeedTray( pc_Job, pc_PaperSize, &_ep_PaperKind, pb_is2ndSidedPaper, pe_CustomPaperType );			// 両面２面目を取得できるように修正 k.inui 02/03/29
	// 警告時に表示する用紙種類の文字列を取得する
	getWarningPaperKindParts( _ep_PaperKind, puc_PaperKindParts, puc_SpecialPaperKindParts );
}
/*============================================================================================
//概要    ：共通関数 : 警告時に表示する用紙種類の文字列を取得する
============================================================================================*/
void getWarningPaperKindParts(
    TYPE_PaperType e_PaperType,			// 用紙種類
    TEXT_ID* puc_PaperKindParts,		// 用紙種類の文字列パーツ
    TEXT_ID* puc_SpecialPaperKindParts )// 特殊用紙種類の文字列パーツ
{
	*puc_PaperKindParts = NULL;							// 用紙種類の表示をしないで初期化
	*puc_SpecialPaperKindParts = NULL;
	if( e_PaperType != TYPE_PaperTypeDontcare ) {		// 用紙種類指定無しの時 02/03/27 k.inui Fiery用紙種類対応
		for( register ushort i = 0; i < sizeof( sp_PaperKindTbl )/sizeof( SP_PaperKindTbl ); i++ ) {
			if( e_PaperType == sp_PaperKindTbl[i].ec_PaperKind ) {
				// 用紙種類が一致するとき
				if( ( TYPE_CategoryState_ENABLE == PnlComGetEnablerSetting()->getFEK_CotegoryState( TYPE_FEKType19 ) )
				    && ( s_KEYAdminUserPaper6 == sp_PaperKindTbl[i].parts ) ) {
					*puc_PaperKindParts = s_KEYAdminLaminate;		// 「ユーザー紙6」→「ラミネート」.
				} else {
					*puc_PaperKindParts = sp_PaperKindTbl[i].parts;
				}
				*puc_SpecialPaperKindParts = sp_PaperKindTbl[i].partsSpecial;
				break;
			}
		}
	}
}
/*============================================================================================
//概要    ：共通関数 : 警告時にエラー給紙口を得る
//備考    ：警告クラスのから移動
============================================================================================*/
static void _getWarningFeedTray( APIC_Job* cp_ErrorJob, TYPC_PaperSize* cp_PaperSize, TYPE_PaperType* ec_PaperKind, Bool* bl_2ndSidedPaper, TYPE_CustomPaperType* e_CustomPaperType )
{
	Bool b_ApsJob = NULL;
	TYPE_FeedTray e_FeedTray = cp_ErrorJob->isWarningFeedTray( b_ApsJob );		// フィードトレイ情報
	TYPC_PaperSize c_PaperSize = cp_ErrorJob->isWarningPaperSize();				// 用紙サイズ情報
	TYPC_PaperType c_PaperType = cp_ErrorJob->isWarningPaperType();				// 用紙種類情報
	if( c_PaperSize.e_SizeCode == TYPE_SizeCodeUnknown ) {	// エラーサイズが入っていない時
		// 警告発生の給紙トレイから情報を得る
		*cp_PaperSize = ppc_FeedTray->getPaperSize( e_FeedTray );								// 用紙サイズ
		*ec_PaperKind = ppc_FeedTray->getPaperType( e_FeedTray ).getPaperType();				// 用紙種類
		*bl_2ndSidedPaper  = ppc_FeedTray->getPaperType( e_FeedTray ).getFeed2ndSidedPaper();	// 両面２面目の状態
		if( NULL != e_CustomPaperType ) {
			*e_CustomPaperType = ppc_FeedTray->getPaperType( e_FeedTray ).getCustomPaperType();		// カスタム用紙属性.
		}
	} else {			// エラーサイズが入っている時
		// エラー給紙トレイから情報を得る
		*cp_PaperSize = c_PaperSize;												// 用紙サイズ
		*ec_PaperKind = c_PaperType.getPaperType();									// 用紙種類
		*bl_2ndSidedPaper = c_PaperType.getFeed2ndSidedPaper();						// 両面２面目の状態
		if( NULL != e_CustomPaperType ) {
			*e_CustomPaperType = c_PaperType.getCustomPaperType();						// カスタム用紙属性.
		}
	}
// comment 2020/01/17 Sky東島 [EagleBK][OP_BTS-12665].
	correctNonStandardPaperSize( cp_PaperSize , e_FeedTray );
	_checkPrintSize( cp_PaperSize );		// プリント用の用紙サイズかどうかを確認する（原稿用の定型サイズは非定型にする）
}
/*============================================================================================
//概要    ：共通関数 : プリント用の用紙サイズかどうかを確認する（原稿用の定型サイズは非定型にする）
//備考    ：警告クラスから移動
============================================================================================*/
static void _checkPrintSize( TYPC_PaperSize* _cp_PaperSize )
{
	switch( _cp_PaperSize->e_SizeCode ) {
		case   TYPE_SizeCodePhotoESef :			// 写真サイズ MSJ Eサイズ
		case   TYPE_SizeCodePhotoELef :			// 写真サイズ MSJ Eサイズ
		case   TYPE_SizeCodePhotoLSef :			// 写真サイズ MSJ Lサイズ
		case   TYPE_SizeCodePhotoLLef :			// 写真サイズ MSJ Lサイズ
		case   TYPE_SizeCode9x13Sef   :			// 写真サイズ ME 9x13
		case   TYPE_SizeCode9x13Lef   :			// 写真サイズ ME 9x13
		case   TYPE_SizeCode10x15Sef  :			// 写真サイズ ME 10x15
		case   TYPE_SizeCode10x15Lef  :			// 写真サイズ ME 10x15
		case   TYPE_SizeCode13x18Sef  :			// 写真サイズ ME 13x18
		case   TYPE_SizeCode13x18Lef  :			// 写真サイズ ME 13x18
		case   TYPE_SizeCodeIN3x5Sef  :			// 写真サイズ MC 3x5
		case   TYPE_SizeCodeIN3x5Lef  :			// 写真サイズ MC 3x5
		case   TYPE_SizeCodeIN225x325Sef  :		// 写真サイズ MC 2 1/4x3 1/4
		case   TYPE_SizeCodeIN225x325Lef  : _cp_PaperSize->e_SizeCode =  TYPE_SizeCodeNonStandard; break;	// 非定型サイズとする
		default:   break;
	}
}
// ===============================================================================================
//	概要    ：数値入力系切り替え時に最大値/最小値が異なるとき値を丸めて返す
//	戻り値  ：float : 丸める必要があるときは丸めた値、そうでなければそのまま
//	備考    ：例：インチMAX2inch、ミリMAX50mmのとき、2inch設定後単位系をミリに変えると、
//	          50.8ミリから始まる。本関数は50ミリに丸める
// ===============================================================================================
float reviseMersurementUnit(
    float sf_nowValue,		// 現在値
    float sf_mmMax,			// ミリ最大値
    float sf_inchMax,		// インチ分数最大値
    float sf_inchnumMax,	// インチ小数最大値
    float sf_mmMin,			// ミリ最小値
    float sf_inchMin,		// インチ分数最小値
    float sf_inchnumMin )	// インチ小数最小値
{
	// 消去しないの時は、丸め込みを行わない
	if( sf_nowValue == 0.0f ) {
		return sf_nowValue;
	}
	// まず現在単位系設定を取得
	TYPE_UnitSystem e_UnitSystem = PnlComGetUnitSystem();
	// 単位系に応じて現在の値が最大値より大のとき、最大値に丸める
	// または最小値より小のとき、最小値に丸める
	switch( e_UnitSystem ) {
		case TYPE_UnitSystemMM_Number:				// メトリック（テンキー）.
			if( sf_nowValue >= sf_mmMax ) {
				sf_nowValue = sf_mmMax;
			} else if( sf_nowValue <= sf_mmMin ) {
				sf_nowValue = sf_mmMin;
			}
			break;
		case TYPE_UnitSystemInch_Fraction:			// インチ（分数）.
			if( sf_nowValue >= sf_inchMax ) {
				sf_nowValue = sf_inchMax;
			} else if( sf_nowValue <= sf_inchMin ) {
				sf_nowValue = sf_inchMin;
			}
			break;
		case TYPE_UnitSystemInch_Number:			// インチ（テンキー）.
			if( sf_nowValue >= sf_inchnumMax ) {
				sf_nowValue = sf_inchnumMax;
			} else if( sf_nowValue <= sf_inchnumMin ) {
				sf_nowValue = sf_inchnumMin;
			}
			break;
	}
	return sf_nowValue;
}
// ===============================================================================================
//	概要    ：宛先と排他になる通信情報を解除する(Fax宛先と排他機能一括解除用)
// ===============================================================================================
void cancelProgSendInfo(
    APIC_Job* pc_Job )	// APIC_Jobのポインタ
{
	char sc_LocalSepAddr[20+1];			// SEP初期化用 「20」はPNLD_MaxFaxTxSepAddrと同値を設定する
	TYPC_JobSpec* pc_JobSpec = pc_Job->getJobSpec();
	memset( sc_LocalSepAddr, '\0', sizeof( sc_LocalSepAddr ) );
	// クイックメモリ送信排他確認
	if( pc_JobSpec->pc_Fax->c_FaxAct.getTxQuickModeOn() == True ) {
		// クイックメモリ送信が設定されている場合、排他が存在しないか確認する
		if( combinationCheck( CNK_FaxTxQuickMemory, pc_Job ) == False ) {
			// 排他が存在する場合、クイックメモリ送信を解除する(メモリ送信を設定する)
			if( combinationCheck( CNK_FaxTxMemory, comPanelJob ) == True ) {
				pc_JobSpec->pc_Fax->c_FaxAct.setTxQuickModeOn( False );
			}
		}
	}
	// ポーリング送信排他確認(掲示板を含む)
	if( ( pc_JobSpec->pc_Fax->c_FaxCommon.getRegistPolledTxDocOn() == True )
	    || ( pc_JobSpec->pc_Fax->c_FaxCommon.getRegistBulletinTxOn() == True ) ) {
		// ポーリング送信又は掲示板登録が設定されている場合、排他が存在しないか確認する
		if( combinationCheck( CNK_FaxTxPolling, pc_Job ) == False ) {
			// 排他が存在した場合、ポーリング送信及び掲示板登録を解除する
			pc_JobSpec->pc_Fax->c_FaxCommon.setRegistPolledTxDocOn( False );		// ポーリング送信(通常)解除
			pc_JobSpec->pc_Fax->c_FaxCommon.setRegistBulletinTxOn( False );			// ポーリング送信(掲示板)解除
			pc_JobSpec->pc_Fax->c_FaxAct.setTxSepAddr( sc_LocalSepAddr );				// SEP初期化
			// ダイレクトBOX宛先に設定されているSEPも解除する
			TYPS_BoxAddress s_BoxAddress;
			s_BoxAddress.sl_BoxNo = -1;
			pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )->setBoxAddress( s_BoxAddress );
			pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )->setOn( False );
		}
	}
	// ポーリング受信排他確認
	if( ( pc_JobSpec->pc_Fax->c_FaxAct.getTxMode() == TYPE_TxModePollRx ) 				// ポーリング受信(通常)
	    || ( pc_JobSpec->pc_Fax->c_FaxAct.getTxMode() == TYPE_TxModeBulPollRx ) ) {		// ポーリング受信(Fコード)
		// ポーリング受信が設定されている場合、排他が存在しないか確認する
		if( combinationCheck( CNK_FaxRxPolling, pc_Job ) == False ) {
			// 排他が存在した場合、ポーリング受信を解除する
			pc_JobSpec->pc_Fax->c_FaxAct.setTxMode( TYPE_TxModeNormal );
			// SEPアドレス設定（JobSpecクリア）
			pc_JobSpec->pc_Fax->c_FaxAct.setTxSepAddr( sc_LocalSepAddr );
		}
	}
	// タイマー送信排他確認
	if( pc_JobSpec->pc_Fax->c_FaxCommon.getTimerOn() == True ) {
		// タイマー送信が設定されている場合、排他が存在しないか確認する
		if( combinationCheck( CNK_FaxTxTimer, pc_Job ) == False ) {
			// 排他が存在する場合名タイマー送信を解除する
			pc_JobSpec->pc_Fax->c_FaxCommon.setTimerOn( False );
			// タイマー時刻クリア （時、分）
			pc_JobSpec->pc_Fax->c_FaxCommon.setHourMinute( TYPC_HourMinute( TYPD_NotSetting,TYPD_NotSetting ) );
		}
	}
	// 設定されない項目なので、排他制御で表示する警告メッセージを表示しない対応を行う
	onlyPanel.isPanelWarning( EP_PanelWarningResetType_KeyOn, True );
}
// ===============================================================================================
//	概要    ：宛先と排他になる読込み情報を解除する(Fax宛先と排他機能一括解除用)
// ===============================================================================================
void cancelProgMsInfo(
    APIC_Job* pc_Job )	// APIC_Jobのポインタ
{
	if( pc_Job == NULL ) {
		return;
	}
	TYPC_Scan* pc_Scan = pc_Job->getJobSpec()->pc_Scan;
	TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;
	// カラー排他確認
	TYPE_PNL_COLOR e_Color = PnlComGetPnlColor( pc_Common, pc_Scan );
	EP_Combination e_Combination = CNK_Size;				// 機能種類
	switch( e_Color ) {
		case TYPE_PNL_COLOR_AUTO:		e_Combination = CNK_ACS;				break;	// 自動
		case TYPE_PNL_COLOR_FULLCOLOR:	e_Combination = CNK_FullColor;			break;	// フルカラー
		case TYPE_PNL_COLOR_GRAY:		e_Combination = CNK_Black_GrayScale;	break;	// グレイスケール
		case TYPE_PNL_COLOR_BIN:														// 白黒2値
		default:						e_Combination = CNK_Size;				break;
	}
	// カラー設定が白黒2値以外のとき
	if( e_Combination != CNK_Size ) {
		// カラー設定が設定されている場合、排他が存在しないか確認する
		if( combinationCheck( e_Combination, pc_Job ) == False ) {
			// 排他が存在する場合、カラーを解除する(モノクロを設定する)
			if( combinationCheck( CNK_Black_1bit, comPanelJob ) == True ) {
				// 「モノクロ」を設定する
				PnlComSetPnlColor( pc_Common, pc_Scan, TYPE_PNL_COLOR_BIN );
			}
		}
	}
	// PDF排他確認
	if( pc_Job->getJobSpec()->pc_Send->c_ComSend.getFileFormat() == TYPE_FileFormatPdf ) {
		// ファイル形式PDFが設定されている場合、排他が存在しないか確認する
		if( combinationCheck( CNK_FileFormat_Pdf, pc_Job ) == False ) {
			// 排他が存在する場合、PDFを解除する（TIFF設定）
			if( combinationCheck( CNK_FileFormat_Tiff, comPanelJob ) == True ) {
				// ファイル形式「TIFF」を設定する
				pc_Job->getJobSpec()->pc_Send->c_ComSend.setFileFormat( TYPE_FileFormatTiff );
			}
		}
	}
	// 設定されない項目なので、排他制御で表示する警告メッセージを表示しない対応を行う
	onlyPanel.isPanelWarning( EP_PanelWarningResetType_KeyOn, True );
}
