/*================================================================================================
//概要    ：ワンタッチキーを表示する
//備考    ：事前にボタンデータを setButtonData で設定しておく必要がある
================================================================================================*/
void PLBC_OneTouchKeyDisp::showOneTouch()
{
	// クラスの初期化処理を行う
	initClass();
	// 表示タイプが前回と違う場合は、表示パーツの初期化を行う
	static OneTouchTypeStatus typeBackup = PLBD_OTTS_Initial;
	if( typeBackup != oneTouchType ) {
		// 表示パーツの初期化を行う
		initParts();
	}
	typeBackup = oneTouchType;
	// 全ワンタッチキーパーツを一度非表示にする
	deleteAllParts_CLCD();
	// ページ上のボタンをすべて表示する
	for( uchar ucCnt = 0; ucCnt <= uc_maxIndex; ucCnt++ ) {
		// ワンタッチキーのボタン１つを表示する
		showButton( ucCnt );
	}
	showOneTouchPage_CLCD();
}
