/*================================================================================================
//概要    ：カラーUI用コンストラクト処理
================================================================================================*/
void PLBC_OneTouchKeyDisp::PLBC_OneTouchKeyDisp_CLCD(
    OneTouchTypeStatus oneTouchType,		// ワンタッチキーの種類
    COLOR _bkColor )						// 背景色
{
	PLBC_OneTouchKeyDisp::oneTouchType = oneTouchType;
	// 指定可能なボタン位置の最大値(１ページのボタン数 - 1)を設定
	switch( PLBC_OneTouchKeyDisp::oneTouchType ) {
		case PLBC_OTTS_A_CLCD:				// 5*3 = 15個のボタンを表示
			uc_maxIndex = 14;
			b_isELOneTouchKey = False;
			b_isWideOneTouchKey = False;
			b_isPrgOneTouchKey = False;
			b_isShortening13OneTouchKey = False ;
			break;
		case PLBC_OTTS_PA_CLCD:				// 3*4 = 12個のボタン(プログラム表示用)を表示
			uc_maxIndex = 11;
			b_isELOneTouchKey = False;
			b_isWideOneTouchKey = False;
			b_isPrgOneTouchKey = True;
			b_isShortening13OneTouchKey = False ;
			break;
		case PLBC_OTTS_WA_CLCD:				// 4*3 = 12個のボタンを表示
		case PLBC_OTTS_WB_CLCD:				// 4*3 = 12個のボタンを表示
		case PLBC_OTTS_WC_CLCD:				// 4*3 = 12個のボタンを表示(下地タイトルあり画面用)
			uc_maxIndex = 11;
			b_isELOneTouchKey = False;
			b_isWideOneTouchKey = False;
			b_isPrgOneTouchKey = False;
			b_isShortening13OneTouchKey = True ;
			break;
		case PLBC_OTTS_RA_CLCD:			// 5*3 = 15個のボタンを表示(UD対応)
		case PLBC_OTTS_RB_CLCD:			// 5*3 = 15個のボタンを表示 & 一文字検索キー表示(UD対応)
		case PLBC_OTTS_RC_CLCD:			// 5*3 = 15個のボタンを表示 + 位置移動 + 1文字検索ボタン (UD対応用)
		case PLBC_OTTS_RD_CLCD:			// 5*3 = 15個のボタンを表示 + 位置移動 (UD対応用)
			uc_maxIndex = 14;
			b_isELOneTouchKey = False;
			b_isWideOneTouchKey = False;
			b_isPrgOneTouchKey = False;
			b_isShortening13OneTouchKey = False ;
			break;
		default:
			PLBC_OneTouchKeyDisp::oneTouchType = PLBC_OTTS_A_CLCD;
			uc_maxIndex = 14;
			b_isELOneTouchKey = False;
			b_isWideOneTouchKey = False;
			b_isPrgOneTouchKey = False;
			b_isShortening13OneTouchKey = False ;
			break;
	}
	// 現在のページ数と総ページ数の初期化
	uc_nowPage = 1;
	uc_maxPage = 1;
	// 背景色
	PLBC_OneTouchKeyDisp::bkColor = _bkColor;
	// 初期化未実行
	b_isInitialized = False;
}
/*================================================================================================
//概要    ：クラスの初期化処理を行う(カラーUI用)
================================================================================================*/
void PLBC_OneTouchKeyDisp::initClass_CLCD()
{
	// 初期化済みでない場合は初期化処理を行う
	if( b_isInitialized == False ) {
		// ボタン表示用データの初期化
		initOneTouchButton();
		// 拡大表示対応のためのパーツポインタ
		if( isELOneTouchKey() == True ) {
			// 拡大表示の場合
			pKey_OneTouch = Key_OneTouch;
			pGra_OneTouchAddr = Gra_OneTouchType;
			pNum_OneTouchGroup = Num_OneTouchGroup;
			pTxt_OneTouchType = Txt_OneTouchType;
			pTfd_OneTouchText = Tfd_OneTouchText;
		} else {
			// 通常表示の場合
			pKey_OneTouch = Key_OneTouch;
			pGra_OneTouchAddr = Gra_OneTouchType;
			pNum_OneTouchGroup = Num_OneTouchGroup;
			pTxt_OneTouchType = Txt_OneTouchType;
			pTfd_OneTouchText = Tfd_OneTouchText;
		}
		b_isInitialized = True;
	}
}
/*================================================================================================
//概要    ：全ワンタッチキーパーツの非表示処理を行う(カラーUI用)
================================================================================================*/
void PLBC_OneTouchKeyDisp::deleteAllParts_CLCD()
{
	uchar uc_Cnt;
	// ワンタッチキー
	for( uc_Cnt = 0; uc_Cnt < PLBD_ButtonNumMax; uc_Cnt++ ) {
		posInfo[uc_Cnt].tx = -1;
		posInfo[uc_Cnt].gy = -1;
		// ボタンを非表示
		Key_OneTouch[uc_Cnt].showEnable( False );
	}
	for( uc_Cnt = 0; uc_Cnt < PLBD_OneTouchSearchKeyNum; uc_Cnt++ ) {
		posInfoSearch[uc_Cnt].tx = -1;
		posInfoSearch[uc_Cnt].gy = -1;
	}
	inputButtonPoint();		// 各ボタンの表示位置を設定する
	// 検索キー
	for( uc_Cnt = 0; uc_Cnt < PLBD_OneTouchSearchKeyNum; uc_Cnt++ ) {
		if( ( posInfoSearch[uc_Cnt].tx == -1 ) || ( posInfoSearch[uc_Cnt].gy ) == -1 ) {
			// ボタンを非表示
			Key_OneTouchSearch[uc_Cnt].showEnable( False );
		}
	}
}
/*================================================================================================
//概要    ：表示パーツを初期化する（カラーUI用）
================================================================================================*/
void PLBC_OneTouchKeyDisp::initParts_CLCD()
{
	// X座標
	short ss_xPos[] = {
		8,					// 宛先種別アイコン
		24,					// 宛先種別テキスト
		24,					// 登録No.
		8					// 登録名
	};
	// Y座標
	short ss_yPos[] = {
		8,					// 宛先種別アイコン
		8,					// 宛先種別テキスト
		8,					// 登録No.
		24					// 登録名
	};
	// 拡大表示用ワンタッチキー位置補正
	// 【注意】ワンタッチキーのAddパーツの定義順と一致している必要あり
	short ss_xPosEnl[] = {
		0,					// 宛先種別アイコン
		0,					// 宛先種別テキスト
		0,					// 登録No.
		0					// 登録名
	};
	// Y座標
	short ss_yPosEnl[] = {
		0,					// 宛先種別アイコン
		0,					// 宛先種別テキスト
		0,					// 登録No.
		0					// 登録名
	};
	// 通常表示用プログラムワンタッチキー位置補正
	// 【注意】ワンタッチキーのAddパーツの定義順と一致している必要あり
	// X座標
	short ss_xPrgPos[] = {
		8,					// 宛先種別アイコン
		24,					// 宛先種別テキスト
		24,					// 登録No.
		8					// 登録名
	};
	// Y座標
	short ss_yPrgPos[] = {
		8,					// 宛先種別アイコン
		8,					// 宛先種別テキスト
		8,					// 登録No.
		8					// 登録名
	};
	// 拡大表示用プログラムワンタッチキー位置補正
	// 【注意】ワンタッチキーのAddパーツの定義順と一致している必要あり
	short ss_xPrgPosEnl[] = {
		0,					// 宛先種別アイコン
		0,					// 宛先種別テキスト
		0,					// 登録No.
		0					// 登録名
	};
	// Y座標
	short ss_yPrgPosEnl[] = {
		0,					// 宛先種別アイコン
		0,					// 宛先種別テキスト
		0,					// 登録No.
		0					// 登録名
	};
	// 通常表示用ページ表示位置補正
	// 【注意】ページ表示のAddパーツの定義順と一致している必要あり
	// X座標
	short ss_xPagePos[] = {
		8,					// 現在ページ
		32,					// スラッシュ
		40					// 総ページ
	};
	// Y座標
	short ss_yPagePos[] = {
		8,					// 現在ページ
		8,					// スラッシュ
		8					// 総ページ
	};
	// ボタンの表示位置変更
	// 使わないパーツを表示禁止にする
	register uchar uc_Cnt;	// カウンタ
	uchar uc_buf = NULL;		// バッファ
	for( uc_Cnt = 0; uc_Cnt < PLBD_ButtonNumMax; uc_Cnt++ ) {
		if( isELOneTouchKey() == True ) {
			// 拡大表示の場合、通常表示のボタンを非表示
			Key_OneTouch[uc_Cnt].showEnable( False );
		} else {
		}
		// 設定した表示位置情報に従い表示する
		if( ( posInfo[uc_Cnt].tx != -1 ) && ( posInfo[uc_Cnt].gy ) != -1 ) {
			// 文字表示用TextFieldに空文字をセット
			POnOffButtonAdd_changeASCIIText( pKey_OneTouch, pTfd_OneTouchText, uc_Cnt, ( uchar* )&uc_buf, 0 );
			// グループ表示用PNumberFieldに0をセット
			POnOffButtonAdd_set( pKey_OneTouch, pNum_OneTouchGroup, uc_Cnt, 0 );
			// [拡大表示]
			if( isELOneTouchKey() == True ) {
				if( isPrgOneTouchKey() ) {
					POnOffButtonAdd_changePosition( pKey_OneTouch, uc_Cnt, posInfo[uc_Cnt].tx, posInfo[uc_Cnt].gy, ss_xPrgPosEnl, ss_yPrgPosEnl );
				} else {
					POnOffButtonAdd_changePosition( pKey_OneTouch, uc_Cnt, posInfo[uc_Cnt].tx, posInfo[uc_Cnt].gy, ss_xPosEnl, ss_yPosEnl );
				}
			} else {
				if( isPrgOneTouchKey() ) {
					POnOffButtonAdd_changePosition( pKey_OneTouch, uc_Cnt, posInfo[uc_Cnt].tx, posInfo[uc_Cnt].gy, ss_xPrgPos, ss_yPrgPos );
				} else {
					POnOffButtonAdd_changePosition( pKey_OneTouch, uc_Cnt, posInfo[uc_Cnt].tx, posInfo[uc_Cnt].gy, ss_xPos, ss_yPos );
				}
			}
		}
		// ボタンを非表示
		if( c_OneTouchButton[uc_Cnt].buttonType == PLBD_BTS_Disablel ) {
			POnOffButtonAdd_showEnable( pKey_OneTouch, uc_Cnt, False );
		}
	}
	// [拡大表示]
	if( isELOneTouchKey() == True ) {
	} else {
		// 通常表示の場合
		// ページ数のアクティブグループ
		Btx_OneTouchPageArea.changePosition( posInfo[PLBD_ButtonNumMax].tx, posInfo[PLBD_ButtonNumMax].gy, ss_xPagePos, ss_yPagePos );
		Key_OneTouchBefore.changePosition( posInfo[PLBD_ButtonNumMax + 1].tx, posInfo[PLBD_ButtonNumMax + 1].gy );
		Key_OneTouchNext.changePosition( posInfo[PLBD_ButtonNumMax + 2].tx, posInfo[PLBD_ButtonNumMax + 2].gy );
		Key_OneTouchBefore.PSinglePartsGraphic::changeGraphic( PK_AV1_01Line_05Char );
		Key_OneTouchNext.PSinglePartsGraphic::changeGraphic( PK_AV1_51Line_05Char );
		// １文字検索ボタンの背景パーツ変更
		Key_OneTouchSearch[11].PSinglePartsGraphic::changeGraphic( PK_EM1_01Line_10Char );		// 切替
	}
	// １文字検索ボタンの表示位置変更
	// 使わないパーツを表示禁止にする
	for( uc_Cnt = 0; uc_Cnt < PLBD_OneTouchSearchKeyNum; uc_Cnt++ ) {
		if( ( posInfoSearch[uc_Cnt].tx == -1 ) || ( posInfoSearch[uc_Cnt].gy ) == -1 ) {
			// ボタンを非表示
			Key_OneTouchSearch[uc_Cnt].showEnable( False );
		} else {
			// ボタンを表示
			Key_OneTouchSearch[uc_Cnt].showEnable( True );
			// ボタンの表示位置を変更
			Key_OneTouchSearch[uc_Cnt].changePosition( posInfoSearch[uc_Cnt].tx, posInfoSearch[uc_Cnt].gy, 0, 0 );
		}
	}
}
/*================================================================================================
//概要    ：ワンタッチキーのボタン１つを表示する(カラーUI用)
================================================================================================*/
static const ushort uc_addrKind[] = {	s_Space1,										// 0
                                        s_KEYAdminSelectEMail,							// 1
                                        s_KEYAdminSelectFTP,							// 2
                                        s_KEYAdminSelectSMB,							// 3
                                        s_KEYAdminSelectBox,							// 4
                                        s_KEYAdminSelectFax,							// 5
                                        s_KEYAdminSelectGroup,							// 6
                                        s_KEYAdminSelectIFAX,							// 7	IFAX Mosel update
                                        s_KEYDirectNoIpFax4,							// 8	IPAddressFax
                                        s_KEYAdminSelectWebDAV,							// 9	WebDAV送信.
                                    };
void PLBC_OneTouchKeyDisp::showButton_CLCD(
    uchar uc_index )	// ボタンの位置
{
	const uchar* parts;
	uchar uc_text = 0;
	ushort us_DispNo = 0;
	TYPC_ShorteningAddress* pc_ShorteningAddress;
	// index の範囲チェック
	if( uc_maxIndex < uc_index ) {
		return;
	}
	// 表示するボタンの種類が「表示しない」の場合ボタンを非表示にする
	if( c_OneTouchButton[uc_index].buttonType == PLBD_BTS_Disablel ) {
		POnOffButtonAdd_showEnable( pKey_OneTouch, uc_index, False );
		return;
	}
	// 再描画させたいため、一旦、すべてを非表示にする
	POnOffButtonAdd_showEnable( pKey_OneTouch, uc_index, False );		// ワンタッチキー非表示
	POnOffButtonAdd_select( pKey_OneTouch, uc_index, False );			// ワンタッチキー非選択
	POnOffButtonAdd_showEnableAddGra( pKey_OneTouch, pGra_OneTouchAddr, uc_index, False );	// 宛先種別アイコン
	POnOffButtonAdd_showEnableAddNum( pKey_OneTouch, pNum_OneTouchGroup, uc_index, False );	// 登録No.非表示
	POnOffButtonAdd_showEnableAddTxt( pKey_OneTouch, pTxt_OneTouchType, uc_index, False );	// 宛先種別
	// [拡大表示]
	// ボタンの種類により背景画像を設定する
	if( isELOneTouchKey() == True ) {
		parts = PK_OT1_T01B02Line_10Char;
	} else if( isShortening13OneTouchKey() == True ) {
		// 幅広(13文字)表示の場合
		switch( c_OneTouchButton[uc_index].buttonType ) {
			case PLBD_BTS_Normal:	// 通常
			default: parts = PK_OT1_T01B02Line_13Char; break;
		}
	} else if( isPrgOneTouchKey() == True ) {
		// プログラム(14文字)表示の場合
		switch( c_OneTouchButton[uc_index].buttonType ) {
			case PLBD_BTS_Normal:	// 通常
			default: parts = PK_NM1_02Line_14Char; break;
		}
	} else {
		// 通常表示の場合
		switch( c_OneTouchButton[uc_index].buttonType ) {
			case PLBD_BTS_Normal:	// 通常
			default: parts = PK_OT1_T01B02Line_10Char; break;
		}
	}
	POnOffButtonAdd_changeOrignalGraphic( pKey_OneTouch, uc_index, parts );
	// ボタンに表示する文字列を設定する
	POnOffButtonAdd_showEnable( pKey_OneTouch, uc_index, True );
	POnOffButtonAdd_changeExternalText( pKey_OneTouch, pTfd_OneTouchText, uc_index,
	                                    ( uchar* )c_OneTouchButton[uc_index].sc_buttonText,
	                                    0, c_OneTouchButton[uc_index].ep_charSet, False );
	// [拡大表示]
	// 宛先種類を設定する
	if( isELOneTouchKey() == True ) {
		parts = NULL;
	} else {
		// 通常表示の場合
		switch( c_OneTouchButton[uc_index].addressType ) {
			case PLBD_ATS_Mail: {		// メール配信
				// 証明書付きかどうかの判断.
				pc_ShorteningAddress = c_AddressSearchIGC.getShorteningAddressDataPointer( (short)( uc_index + 1 ) );
				TYPS_MailAddress s_MailAddress;
				if( NULL != pc_ShorteningAddress ) {
					s_MailAddress = pc_ShorteningAddress->getMailAddress();
					// ScanToMe対応.
					us_DispNo = ( ushort )pc_ShorteningAddress->getDisplayNo();
				}
				if( us_DispNo == PCGD_ScanToMeIndex ) {
					parts = PG_DirectScantoMe_X16Y16;
				} else {
					if( s_MailAddress.b_isSmimeExist == True )
					{
						// かぎ付きE-Mailアイコン.
						parts = PG_SMIME_MailEncode_String_X016Y016;
					} else {
						parts = PG_DirectEmail_X16Y16;
					}
				}

			}
			uc_text = 1;	// "E-Mail"
			break;
			case PLBD_ATS_IFax:		// I-FAX
				parts = PG_DirectIFAX_X16Y16;
				uc_text = 7;	// "I-FAX"
				break;
			case PLBD_ATS_FTP:		// FTP配信
				parts = PG_DirectFTP_X16Y16;
				uc_text = 2;	// "FTP"
				break;
			case PLBD_ATS_SMB:		// SMB配信
				// ScanToMe対応.
				pc_ShorteningAddress = c_AddressSearchIGC.getShorteningAddressDataPointer( (short)( uc_index + 1 ) );
				if( NULL != pc_ShorteningAddress ) {
					us_DispNo = ( ushort )pc_ShorteningAddress->getDisplayNo();
				}
				if( us_DispNo == PCGD_ScanToHomeIndex ) {
					parts = PG_DirectScantoHome_X016Y016;
				} else {
					parts = PG_DirectSMB_X16Y16;
				}
				uc_text = 3;	// "SMB"
				break;
			case PLBD_ATS_Box:		// BOX
				parts = PG_DirectBOX_X16Y16;
				uc_text = 4;	// "BOX"
				break;
			case PLBD_ATS_Addr:		// ファクス
				parts = PG_DirectFAX_X16Y16;
				uc_text = 5;	// "ファクス"
				break;
			case PLBD_ATS_Grp:		// グループ
				parts = PG_DirectGroup_X16Y16;
				uc_text = 6;	// "グループ"
				break;
			case PLBD_ATS_IPFax:	// IPFax
				parts = PG_DirectIPAddressFax_X16Y16;
				uc_text = 8;
				break;
			case PLBD_ATS_WebDAV:	// WebDAV送信.
				parts = PG_DirectWebDAV_X016Y016;
				uc_text = 9;
				break;
			case PLBD_ATS_None:		// なし
			default: parts = NULL; break;
		}
	}
	// プログラムキーの場合は表示しない
	if( ( parts != NULL ) && ( isPrgOneTouchKey() != True ) ) {
		POnOffButtonAdd_changeGraphic( pKey_OneTouch, pGra_OneTouchAddr, uc_index, parts );
		POnOffButtonAdd_showEnableAddGra( pKey_OneTouch, pGra_OneTouchAddr, uc_index, True );
		POnOffButtonAdd_changeText( pKey_OneTouch, pTxt_OneTouchType, uc_index, uc_addrKind[uc_text] );
		POnOffButtonAdd_showEnableAddTxt( pKey_OneTouch, pTxt_OneTouchType, uc_index, True );
	}
	// 選択状態を設定する
	POnOffButtonAdd_select( pKey_OneTouch, uc_index, c_OneTouchButton[uc_index].b_isSelected );
	// 参照可能不可を設定する
	POnOffButtonAdd_activate( pKey_OneTouch, uc_index, c_OneTouchButton[uc_index].b_isActivated );
}
