/*============================================================================================
//概要    ：ワンタッチキーページエリアを表示する（カラーUI用）
============================================================================================*/
void PLBC_OneTouchKeyDisp::showOneTouchPage_CLCD()
{
	// ページ数の表示
	Btx_OneTouchPageArea.showEnable( False );		// 表示更新のため一旦消す
	if( isELOneTouchKey() == True ) {
		// 拡大表示の場合
	} else {
		// 通常表示の場合
		Btx_OneTouchPageArea.set( &Num_OneTouchPageReal, 0, True );
		Btx_OneTouchPageArea.set( &Num_OneTouchPageTotal, 0, True );
		Btx_OneTouchPageArea.set( &Num_OneTouchPageReal, ( float )uc_nowPage, True );
		Btx_OneTouchPageArea.set( &Num_OneTouchPageTotal, ( float )uc_maxPage, True );
		Btx_OneTouchPageArea.showEnable( True );
	}
	// ページ切替キーの表示
	if( uc_maxPage == 1 ) {						// 1ページしかない場合
		Key_OneTouchBefore.showEnable( False );
		Key_OneTouchNext.showEnable( False );
	} else {
		Key_OneTouchBefore.showEnable( True );
		Key_OneTouchNext.showEnable( True );
	}
}
/*============================================================================================
//概要    ：indexで指定した位置のボタンにデータを割り当てる（カラーUI用）
============================================================================================*/
void PLBC_OneTouchKeyDisp::setButtonData_CLCD(
    PLBC_OneTouchButton c_OneTouchButton,	// ボタンに割り当てるデータ
    uchar uc_index )						// ボタンの位置
{
	// データのセット
	register short ss_ret = 0;				// 戻り値
	register short ss_lines = 2;			// 表示する行数
	register short ss_length = 10;			// 1行の文字数
	if( isELOneTouchKey() == True ) {
	} else if( isShortening13OneTouchKey() == True ) {
		// 13文字幅表示の場合
		ss_lines = 2;			// 表示する行数
		ss_length = 13;			// 1行の文字数
	} else if( isPrgOneTouchKey() == True ) {
		// プログラム表示の場合
		ss_lines = 2;			// 表示する行数
		ss_length = 14;			// 1行の文字数
	} else {
		// 通常表示の場合
		ss_lines = 2;			// 表示する行数
		ss_length = 10;			// 1行の文字数
	}
	// 表示する文字の加工
	ss_ret = setupInputString(
	             ss_lines,														// 表示する行数
	             ss_length,														// 1行の文字数
	             c_OneTouchButton.sc_buttonText,									// 元の文字列
	             PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].sc_buttonText,	// 文字数変更後の文字列
	             0,																// 取り出す文字列の開始点
	             c_OneTouchButton.ep_charSet );									// フォントセット
	// フォントセット
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].ep_charSet = c_OneTouchButton.ep_charSet;
	// No.
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].ss_AddressNo = c_OneTouchButton.ss_AddressNo;
	// ボタンタイプ
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].buttonType = c_OneTouchButton.buttonType;
	// アドレスタイプ
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].addressType = c_OneTouchButton.addressType;
	// 選択状態
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].b_isSelected = c_OneTouchButton.b_isSelected;
	// 参照可能不可.
	PLBC_OneTouchKeyDisp::c_OneTouchButton[uc_index].b_isActivated
	    = c_OneTouchButton.b_isActivated;
}
