/*================================================================================================
//概要    ：表示対象となるデータ数を取得する
================================================================================================*/
short PLBC_OneTouchKey::getEnableDataNum()
{
	// クラスの初期化処理を行う
	initClass();
	short ss_addrDataNum;					// アドレス帳のデータ数
	ss_addrDataNum = getDataNum();
	short ss_dataCnt = 0;					// アドレス帳データのカウンタ
	short ss_enableCnt = 0;					// アドレス帳で表示対象となるデータのカウンタ
	PLBC_OneTouchButton onetouchButton;		// １ボタンのデータ
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78631 [UNINIT.STACK.MUST] initialized b_isSingle.
//	Bool b_isSingle;
	Bool b_isSingle = False;
	for( ; ss_dataCnt < ss_addrDataNum; ss_dataCnt++ ) {
		// データ取得
		getData( ss_dataCnt, onetouchButton, b_isSingle, False );
		// 表示対象となるデータかを判断
		if( ( onetouchButton.b_isDataValid == False ) && ( !b_isNullDataDisp ) ) {
			// 表示しないデータ
			;
		} else {
			// 表示するデータ
			ss_enableCnt++;
		}
	}
	return ss_enableCnt;
}
/*================================================================================================
//概要    ：現在ページのデータを取得し、表示用ボタンデータにセットする
================================================================================================*/
void PLBC_OneTouchKey::setPageData()
{
	// クラスの初期化処理を行う
	initClass();
	// ボタン表示用データを初期化する
	initOneTouchButton();
	// 現在ページのデータを取得し、ボタン表示用データにセットする
	short ss_dataCnt = 0;			// アドレス帳データのカウンタ
	short ss_enableCnt = 0;			// 表示対象データのカウンタ
	uchar uc_getDataPage = 0;		// 取得したデータが表示されるページ
	uchar uc_buttonIndex = 0;		// 取得したデータが表示されるボタンのインデックス
	PLBC_OneTouchButton c_Data;		// ワンタッチキー１ボタンのデータ
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78632 [UNINIT.STACK.MUST] initialized b_isSingle.
//	Bool b_isSingle;
	Bool b_isSingle = False;
	for( ss_enableCnt = 0; ss_enableCnt < ss_enableDataNum; ) {
		// データ取得
		getData( ss_dataCnt, c_Data, b_isSingle );
		// 表示対象となるデータかを判断
		if( ( c_Data.b_isDataValid == False ) && ( !b_isNullDataDisp ) ) {
			// 表示しないデータ
			;
		} else {
			// 取得したデータが表示されるページを算出
			uc_getDataPage = ( uchar )( ( ss_enableCnt + 1 ) / ( uc_maxIndex + 1 ) );
			if( ( ss_enableCnt + 1 ) % ( uc_maxIndex + 1 ) ) {
				uc_getDataPage++;
			}
			// 指定されたページか？
			if( uc_getDataPage == uc_nowPage ) {
				// ボタン表示用データにセット
				PLBC_OneTouchKeyDisp::setButtonData( c_Data, uc_buttonIndex );
				uc_buttonIndex++;
			}
			ss_enableCnt++;
			// 現在表示中のページの処理を完了したらループを抜ける
			if( uc_nowPage < uc_getDataPage ) {
				break;
			}
		}
		ss_dataCnt++;
	}
}
/*================================================================================================
//概要    ：指定位置のデータの選択状態を更新する
//戻り値  ：True:成功 False:失敗
//備考    ：ページに 0 が指定された場合は、表示対象となる全データの選択状態を更新する
//          単一選択のチェックを行いデータをセットする
================================================================================================*/
Bool PLBC_OneTouchKey::updateData(
    Bool b_isSelected,	// 選択状態
    uchar uc_Page,		// ページ
    uchar uc_Index )	// インデックス
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	Bool b_isHitDataSingleSelect = False;		// 指定位置のデータが単一選択か？
	short ss_hitDataIndex = -1;					// 指定位置のデータのインデックス
	Bool b_isSingleSelected = False;			// 既存の選択状態の単一選択データが出現したか？
	short ss_singleSelectDataIndex = 0;			// 既存の選択状態の単一選択データのインデックス
	short sc_singleSelectDataButtonIndex = -1;	// 同一ページ内で選択状態の
	// 単一選択データのボタンインデックス
	// ページの範囲チェック
	if( uc_maxPage < uc_Page ) {
		return False;
	}
	// インデックスの範囲チェック
	if( uc_maxIndex < uc_Index ) {
		return False;
	}
	// 現在ページのデータを取得する
	short ss_dataCnt = 0;			// アドレス帳データのカウンタ
	short ss_enableCnt = 0;			// 表示対象データのカウンタ
	uchar uc_getDataPage = 0;		// 取得したデータが表示されるページ
	uchar uc_buttonIndex = 0;		// 取得したデータが表示されるボタンのインデックス
	PLBC_OneTouchButton c_Data;		// ワンタッチキー１ボタンのデータ
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78633 [UNINIT.STACK.MUST] initialized b_isSingle.
//	Bool b_isSingle;				// ワンタッチキー１ボタンの単一選択種別
	Bool b_isSingle = False;
	ss_enableDataNum = getEnableDataNum();
	for( ss_enableCnt = 0; ss_enableCnt < ss_enableDataNum; ) {
		// データ取得
		getData( ss_dataCnt, c_Data, b_isSingle, False );
		// 表示対象となるデータかを判断
		if( ( c_Data.b_isDataValid == False ) && ( !b_isNullDataDisp ) ) {
			// 表示しないデータ
			;
		} else {
			// 取得したデータが表示されるページを算出
			uc_getDataPage = ( uchar )( ( ss_enableCnt + 1 ) / ( uc_maxIndex + 1 ) );
			if( ( ss_enableCnt + 1 ) % ( uc_maxIndex + 1 ) ) {
				uc_getDataPage++;
			}
			// 全データ指定の場合
			if( uc_Page == 0 ) {
				// すでに選択状態の単一選択データが出現しており
				// 選択状態への変更で、変更するデータが単一選択データの場合
				if( ( b_isSingleSelected ) && ( b_isSelected ) && ( b_isSingle ) ) {
					// 全選択不能としてエラーリターン
					return False;
				}
				// データセット
				c_Data.b_isSelected = b_isSelected;
				b_ret = setData( ss_dataCnt, c_Data );
				if( !b_ret ) {
					return False;
				}
			}
			// 指定されたページか？
			else if( uc_getDataPage == uc_Page ) {
				if( uc_buttonIndex == uc_Index ) {
					// 指定位置のデータのインデックスを保存
					ss_hitDataIndex = ss_dataCnt;
					// 指定位置のデータが単一選択データの場合、フラグを立てる
					if( b_isSingle ) {
						b_isHitDataSingleSelect = True;
					}
				} else {
					// 同一ページ内の取得したデータが単一選択で選択状態の場合、
					// ボタンインデックスを保存する
					if( ( b_isSingle ) && ( c_Data.b_isSelected ) ) {
						sc_singleSelectDataButtonIndex = uc_buttonIndex;
					}
				}
				uc_buttonIndex++;
			}
			// 変更するデータが単一選択データで、選択状態の場合、
			// インデックスを保存する
			if( ( b_isSingle ) && ( c_Data.b_isSelected ) && ( ss_dataCnt != ss_hitDataIndex ) ) {
				b_isSingleSelected = True;
				ss_singleSelectDataIndex = ss_dataCnt;
			}
			ss_enableCnt++;
		}
		ss_dataCnt++;
	}
	// 指定位置のデータが単一選択で選択状態に変更
	if( b_isHitDataSingleSelect && b_isSelected ) {
		// 選択状態の単一選択データがすでに存在
		if( b_isSingleSelected ) {
			// 既存の単一選択データを未選択にする
			getData( ss_singleSelectDataIndex, c_Data, b_isSingle, False );
			c_Data.b_isSelected = False;
			b_ret = setData( ss_singleSelectDataIndex, c_Data );
			if( !b_ret ) {
				return False;
			}
		}
		// 既存の単一選択データが指定位置のデータのページ内にあった場合は、
		// ボタン表示を未選択にする
		if( 0 <= sc_singleSelectDataButtonIndex ) {
			PLBC_OneTouchKeyDisp::changeSelectStatus( False, ( uchar )sc_singleSelectDataButtonIndex );
		}
	}
	// 指定位置のデータ設定の場合
	if( uc_Page != 0 ) {
		// 指定位置のデータの選択状態を設定する
		getData( ss_hitDataIndex, c_Data, b_isSingle, False );
		c_Data.b_isSelected = b_isSelected;
		b_ret = setData( ss_hitDataIndex, c_Data );
		if( !b_ret ) {
			return False;
		}
	}
	return True;
}
/*============================================================================================
//概要    ：Eメール使用不可能の場合、短縮宛先がEメールデータかを判断する
//戻り値  ：True:Eメールデータ False:Eメールデータ以外,Eメール使用可能.
//備考    ：Eメール使用可能の場合は、宛先種別にかかわらず False を返す
============================================================================================*/
Bool PLBC_OneTouchKey::isEmailDataShorteningAddress(
    short ss_ShorteningAddress )	// 短縮宛先番号
{
	// クラスの初期化処理を行う
	initClass();
	// Eメール使用可能か？
	Bool b_isEmailSend = isEmailSendSettingStatus();
	// Eメール使用不可
	if( !b_isEmailSend ) {
		// インスタンス取得
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//		APIC_ShorteningAddress* pc_AddrA = APIC_ShorteningAddress::newInstance( ss_ShorteningAddress );
		APIC_ShorteningAddress* pc_AddrA = APIC_ShorteningAddress::newInstance( ss_ShorteningAddress , PNLC_NetworkLan::getInstance()->getLine() );
		if( NULL == pc_AddrA ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;				// 静的解析 2012/09/04 第一OPS 酒井(健).
		}
		// 取得したデータが有効か？
		if( pc_AddrA->getRegistration() == False ) {
			return False;
		}
		// 宛先種別を取得
		TYPE_SendMode e_SendMode;
		e_SendMode = pc_AddrA->getSendMode();
		// Eメールかを判断
		if( e_SendMode == TYPE_SendModeEmail ) {
			return True;
		} else {
			return False;
		}
	}
	return False;
}
/*================================================================================================
//概要    ：ワンタッチキーを表示する
================================================================================================*/
void PLBC_OneTouchKey::showOneTouch()
{
	// クラスの初期化処理を行う
	initClass();
	// 表示対象となるデータ数を取得する
	ss_enableDataNum = getEnableDataNum();
	// 総ページを設定
	uc_maxPage = ( uchar )( ss_enableDataNum / ( uc_maxIndex + 1 ) );
	if( ss_enableDataNum % ( uc_maxIndex + 1 ) ) {
		uc_maxPage++;
	}
	if( uc_maxPage == 0 ) {
		uc_maxPage = 1;
	}
	// 現在の表示ページを設定
	if( uc_maxPage < uc_nowPage ) {
		uc_nowPage = uc_maxPage;
	} else if( uc_nowPage < 1 ) {
		uc_nowPage = 1;
	}
	// 現在ページのデータを取得し、表示用ボタンデータにをセットする
	setPageData();
	// ワンタッチキーを表示する
	PLBC_OneTouchKeyDisp::showOneTouch();
}
/*================================================================================================
//概要    ：index で指定した位置のボタンの選択状態を変更する
//戻り値  ：True:正常 False:異常
//備考    ：ボタンが n 個の場合は、uc_index には 0 ～ (n-1) が指定可能.
================================================================================================*/
Bool PLBC_OneTouchKey::changeSelectStatus(
    Bool b_isSelected,		// ボタンの選択状態   True:選択    False:未選択
    uchar uc_index )		// ボタンの位置
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	// index の範囲チェック
	if( uc_maxIndex < uc_index ) {
		return False;
	}
	// 表示するボタンの種類が「表示しない」の場合 index無効
	if( c_OneTouchButton[uc_index].buttonType == PLBD_BTS_Disablel ) {
		return False;
	}
	// 現在の状態と同じ場合は何もしない
	if( c_OneTouchButton[uc_index].b_isSelected == b_isSelected ) {
		return True;
	}
	// 選択 or 解除状態として更新をかける.
	if( c_OneTouchButton[uc_index].b_isSelected ) {
		// 選択されている場合、データを未選択で更新する
		b_ret = updateData( False, 1, uc_index );
	} else {
		// 未選択の場合、データを選択で更新する
		b_ret = updateData( True, 1, uc_index );
	}
	// 親クラスの処理を呼びボタンの表示状態を変更する
	if( b_ret ) {
		b_ret = PLBC_OneTouchKeyDisp::changeSelectStatus( b_isSelected, uc_index );
	}
	return b_ret;
}
/*================================================================================================
//概要    ：データを全選択/全解除する
//戻り値  ：True:正常 False:異常
================================================================================================*/
Bool PLBC_OneTouchKey::setSelectALL(
    Bool b_isSelectALL		// True:全選択する False:全解除する
    ,Bool option			 	// True:関数呼び分け特別 False:関数呼び分けデフォルト
)
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	// データを全選択/全解除にする
	b_ret = updateData( b_isSelectALL );
	if( !b_ret ) {
		return False;
	}

	// 親クラスの処理を呼びボタンの表示状態を変更する
	b_ret = PLBC_OneTouchKeyDisp::setSelectALL( b_isSelectALL,option );

	return b_ret;
}
