/*================================================================================================
//概要    ：指定位置のデータをセットする
//戻り値  ：True:成功 False:失敗
================================================================================================*/
Bool PLBC_OneTouchKeyGroupAddress::setData(
    short ss_dataCnt,				// セットするデータのインデックス
    PLBC_OneTouchButton c_Data )	// ワンタッチキーのボタンデータ
{
	// クラスの初期化処理を行う
	initClass();
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return False;
	}
	Bool b_ret = False;
	short ss_CntA;		// 短縮宛先のカウンタ
	APIC_ShorteningAddress* pc_AddrA;	// 短縮宛先のポインタ
	APIC_GroupAddress* pc_AddrG;		// グループ宛先のポインタ
	short ss_NumOfShorteningAddress;	// グループの短縮宛先登録数
	// グループ宛先のインスタンス取得
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//	pc_AddrG = APIC_GroupAddress::newInstance( ss_dataCnt + 1 );
	pc_AddrG = APIC_GroupAddress::newInstance( ss_dataCnt + 1 , PNLC_NetworkLan::getInstance()->getLine() );
	if( NULL == pc_AddrG ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;			// 静的解析 2012/09/04 第一OPS 酒井(健).
	}
	// 取得したデータが有効か？
	if( pc_AddrG->getRegistration() == False ) {
		return False;
	}
	// グループ宛先では、ボタンの表示状態を変更しないため、
	// セットする選択状態の判断に(c_Data.b_isSelected)を使えない
	// 現在のグループ宛先のON/OFF状態を取得し、
	//   ON の場合→OFFにする
	//   OFFの場合→ON にする
	Bool b_set = pc_ComSend->getGroupAddress( (short)( ss_dataCnt + 1 ) );
	b_set = !b_set;
	// 短縮宛先を全選択させる場合
	if( b_isAllSelect ) {
		// ONする場合、最大個数を超えないかをチェック
		if( b_set ) {
			// 短縮宛先選択個数の取得
			short ss_SelecShorteningAddressCount = pc_ComSend->getSelecShorteningAddressCount();
			// グループに登録されている短縮宛先数の取得
			short ss_NumOfShorteningAddress = pc_AddrG->getNumOfShorteningAddress();
			// 最大個数を超えないかをチェック
			if( ( TYPD_MaxShorteningAddressInGroupAddress < ( ss_SelecShorteningAddressCount + ss_NumOfShorteningAddress ) )
			    ||( onlyPanel.checkBroadcastOver( ss_NumOfShorteningAddress ) == True ) ) {
				// 同報件数オーバーのフラグをONする
				onlyPanel.setPanelWarning( PNL_ERROR_BroadcastOver );
				return False;
			}
		}
		// 短縮宛先の最大数を取得する
		pc_AddrA = APIC_ShorteningAddress::newInstance( 1 );
		ss_NumOfShorteningAddress = pc_AddrA->getMaxShorteningAddress();
		// 登録されている短縮宛先の選択状態を変更する
		for( ss_CntA = 1; ss_CntA <= ss_NumOfShorteningAddress; ss_CntA++ ) {
			// Eメール使用不可能の場合、短縮宛先がEメールデータかを判断する
			Bool b_isEnailData = isEmailDataShorteningAddress( ss_CntA );
			if( !b_isEnailData ) {
				// 登録されている短縮宛先を取得
				b_ret = pc_AddrG->getShorteningAddress( ss_CntA );
				if( b_ret ) {
					// 現在のON/OFF情報を取得
					Bool b_now = pc_ComSend->getShorteningAddress( ss_CntA );
					if( b_now != b_set ) {
						b_ret = setShorteningAddressOneTouchKey( ss_CntA, b_set, pc_ComSend, pc_Job, b_isFAX );
					}
				}
			}
		}
	}
	return b_ret;
}
/*================================================================================================
//概要    ：index で指定した位置のボタンの選択状態を変更する
//戻り値  ：True:正常 False:異常
//備考    ：ボタンが n 個の場合は、uc_index には 0 ～ (n-1) が指定可能.
================================================================================================*/
Bool PLBC_OneTouchKeyGroupAddress::changeSelectStatus(
    Bool b_isSelected,		// ボタンの選択状態   True:選択    False:未選択
    uchar uc_index )		// ボタンの位置
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	// index の範囲チェック
	if( uc_maxIndex < uc_index ) {
		return False;
	}
	// 表示するボタンの種類が「表示しない」の場合 index無効
	if( c_OneTouchButton[uc_index].buttonType == PLBD_BTS_Disablel ) {
		return False;
	}
	// 現在の状態と同じ場合は何もしない
	if( c_OneTouchButton[uc_index].b_isSelected == b_isSelected ) {
		return True;
	}
	// 現在の選択状態による判断
	if( c_OneTouchButton[uc_index].b_isSelected ) {
		// 選択されている場合、データを未選択で更新する
		b_ret = updateData( False, (uchar)uc_nowPage, uc_index );
	} else {
		// 未選択の場合、データを選択で更新する
		b_ret = updateData( True, (uchar)uc_nowPage, uc_index );
	}
	// グループ宛先では、ボタンの表示状態を変更しない
	return b_ret;
}
/*================================================================================================
//概要    ：データを全選択/全解除する
//戻り値  ：True:正常 False:異常
================================================================================================*/
Bool PLBC_OneTouchKeyGroupAddress::setSelectALL(
    Bool b_isSelectALL		// True:全選択する False:全解除する
    ,Bool option			 	// True:関数呼び分け特別 False:関数呼び分けデフォルト
)
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	// データを全選択/全解除にする
	b_ret = updateData( b_isSelectALL );
	if( !b_ret ) {
		return False;
	}
	return b_ret;
}

/*================================================================================================
//概要    ：指定位置のデータを取得する
================================================================================================*/
void PLBC_OneTouchKeyGroupAddress::getData_CLCD(
    short ss_dataCnt,				// 取得するデータのインデックス
    PLBC_OneTouchButton& rc_Data,	// ワンタッチキーのボタンデータ
    Bool& rb_isSingle )				// 単一選択種別
{
	// ボタンデータを初期化
	rc_Data.b_isSelected = False;
	rc_Data.sc_buttonText[0] = NULL;
	rc_Data.buttonType = PLBD_BTS_Normal;
	rc_Data.b_isDataValid = False;
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// グループ宛先の番号.
	rc_Data.ss_AddressNo = (short)( ss_dataCnt + 1 );
	// インスタンス取得.
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//	APIC_GroupAddress* pc_AddrG = APIC_GroupAddress::newInstance( rc_Data.ss_AddressNo );
	APIC_GroupAddress* pc_AddrG = APIC_GroupAddress::newInstance( rc_Data.ss_AddressNo , PNLC_NetworkLan::getInstance()->getLine() );
	if( NULL == pc_AddrG ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// 取得したデータが有効か？.
	if( False == pc_AddrG->getRegistration() ) {
		return;
	}
	rc_Data.b_isDataValid = True;
	// ボタンに表示する文字列取得
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		pc_AddrG->getAddressNameUTF8( rc_Data.sc_buttonText, TYPE_CharSetUTF8 );
	} else {
		pc_AddrG->getAddressNameUTF8( rc_Data.sc_buttonText, getCharSetForCAPI() );
	} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
	// ボタンに表示する文字列のフォントセット
	rc_Data.ep_charSet = ::getCharSetForPanel();
	rc_Data.buttonType = PLBD_BTS_Normal;
	// 左上に表示する宛先種類(グループ宛先の場合は固定)
	rc_Data.addressType = PLBD_ATS_Grp;
	// 単一選択種別(短縮宛先の場合は固定)
	rb_isSingle = False;
}
