/*================================================================================================
//概要    ：グループのワンタッチキーを表示する
//戻り値  ：なし
//備考    ：一時配信(1ページ目)のページ数を0ページから始める
//作成者  ：菅野
//レビュー：未実施
================================================================================================*/
void PLBC_OneTouchKeyGroupMemberAddress::showOneTouch()
{
	// クラスの初期化処理を行う
	initClass();
	// 短縮リストポインタのチェック
	if( plst_ShortAddress == NULL ) {
		return;
	}
	// ボタン表示用データを初期化する
	initOneTouchButton();
	// 検索リストを参照し、短縮宛先データを取得する.
	TYPC_ShorteningAddress* pc_AddrA;		// 短縮宛先.
	PLBC_OneTouchButton c_Data;				// ワンタッチキーのボタンデータ
	uchar uc_index = 0;						// ワンタッチキーのボタン位置(0-)
	plst_ShortAddress->Lock();
	pc_AddrA = plst_ShortAddress->findFirst();
	while( pc_AddrA != NULL ) {
		// index の範囲チェック グループ詳細の場合、1pageに15宛先表示
		if( uc_maxIndex < uc_index ) {
			break;
		}
		// 送信可否判定 ここではじかれるとページ数が合わなくなる。ないとは思うが【課題13川崎】
		if( False == isEnableSetAddress( pc_ComSend, pc_AddrA->getSendMode(), False,False, False, True, short( -1 ),NULL,b_isFAX ) ) {
			// 送信不可な為、次短縮を設定
			pc_AddrA = plst_ShortAddress->findNext();
			continue;
		}
		// アドレス有効. 不要かも。
		c_Data.b_isDataValid = True;
		// ボタンに表示する文字列取得
		if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
			pc_AddrA->getAddressNameUTF8( c_Data.sc_buttonText, TYPE_CharSetUTF8 );
		} else {
			pc_AddrA->getAddressNameUTF8( c_Data.sc_buttonText, getCharSetForCAPI() );
		} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
		// ボタンに表示する文字列のフォントセット
		c_Data.ep_charSet = ::getCharSetForPanel();
		// 表示するボタンの種類(グループメンバーの場合は固定)
		c_Data.buttonType = PLBD_BTS_Normal;
		// 左上に表示する宛先種類
		TYPE_SendMode s_mode;
		s_mode = pc_AddrA->getSendMode();
		AddressTypeStatus addressType;
		switch( s_mode ) {
			case TYPE_SendModeEmail: addressType = PLBD_ATS_Mail; break;			//E-mail
			case TYPE_SendModeIfax: addressType = PLBD_ATS_IFax; break;			//I-Fax
			case TYPE_SendModeFtp: addressType = PLBD_ATS_FTP; break;			//FTP
			case TYPE_SendModeSmb: addressType = PLBD_ATS_SMB; break;			//SMB
			case TYPE_SendModeBox: addressType = PLBD_ATS_Box; break;			//BOX
			case TYPE_SendModeFax: addressType = PLBD_ATS_Addr; break;			//Fax
				
			case TYPE_SendModeIPAddressFax: addressType = PLBD_ATS_IPFax; break;			//IP-Fax
			case TYPE_SendModeWebDav: addressType = PLBD_ATS_WebDAV; break;		// WebDAV.
			default : addressType = PLBD_ATS_None; break;
		}
		c_Data.addressType = addressType;

		// データが参照可能か？ True:参照可能 False:参照不可.
		c_Data.b_isActivated = PnlComIsReferenceBoxInfoInShorteningAddress( pc_AddrA );

		c_Data.ss_AddressNo = ( short )pc_AddrA->getIgcRecodeId();


		// ボタンの選択状態取得
		Bool b_ret = getOnOffIGC( pc_AddrA, c_Data.b_isSelected );
		if( !b_ret ) {
			plst_ShortAddress->UnLock();
			return;
		}
		// 短縮宛先をワンタッチキーに設定する
		PLBC_OneTouchKeyDisp::setButtonData( c_Data, uc_index );
		uc_index++;
		// 次の短縮宛先へ
		pc_AddrA = plst_ShortAddress->findNext();
	}
	plst_ShortAddress->UnLock();
	uc_maxPage = getMaxPageIGC();
	if( uc_maxPage == 0 ) {
		uc_maxPage = 1;
	}
	// 現在の表示ページを設定
	if( uc_maxPage < uc_nowPage ) {
		uc_nowPage = uc_maxPage;
	} else if( uc_nowPage < 1 ) {
		uc_nowPage = 1;
	}
	// ワンタッチキーを表示する
	PLBC_OneTouchKeyDisp::showOneTouch();
}
/*================================================================================================
//概要    ：表示対象となるデータ数を取得する
================================================================================================*/
short PLBC_OneTouchKeyGroupMemberAddress::getEnableDataNum()
{
	// クラスの初期化処理を行う
	initClass();
	short ss_addrDataNum;					// アドレス帳のデータ数
	ss_addrDataNum = getDataNum();
	short ss_dataCnt = 0;					// アドレス帳データのカウンタ
	short ss_enableCnt = 0;					// アドレス帳で表示対象となるデータのカウンタ
	PLBC_OneTouchButton onetouchButton;		// １ボタンのデータ
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78634 [UNINIT.STACK.MUST] initialized b_isSingle.
//	Bool b_isSingle;
	Bool b_isSingle = True;
	for( ; ss_dataCnt < ss_addrDataNum; ss_dataCnt++ ) {
		// データ取得
		getData( ss_dataCnt, onetouchButton, b_isSingle, False );
		// 表示対象となるデータかを判断
		if( ( onetouchButton.b_isDataValid == False ) && ( !b_isNullDataDisp ) ) {
			// 表示しないデータ
			;
		} else if( ( BTNID_DOCUMENTUSEBINDSEND == BOXC_DocumentSelectUseCom::getSelectKey() )  && ( True == onlyPanel.b_nowBoxMode )
		           && ( PLBD_ATS_Addr == onetouchButton.addressType || PLBD_ATS_IPFax == onetouchButton.addressType || PLBD_ATS_IFax == onetouchButton.addressType ) ) {
			// 表示しないデータ
			;
		} else {
			// 表示するデータ
			ss_enableCnt++;
		}
	}
	return ss_enableCnt;
}
/*================================================================================================
//概要    ：現在ページのデータを取得し、表示用ボタンデータにセットする
================================================================================================*/
void PLBC_OneTouchKeyGroupMemberAddress::setPageData()
{
	// クラスの初期化処理を行う
	initClass();
	// ボタン表示用データを初期化する
	initOneTouchButton();
	// 現在ページのデータを取得し、ボタン表示用データにセットする
	short ss_dataCnt = 0;			// アドレス帳データのカウンタ
	short ss_enableCnt = 0;			// 表示対象データのカウンタ
	uchar uc_getDataPage = 0;		// 取得したデータが表示されるページ
	uchar uc_buttonIndex = 0;		// 取得したデータが表示されるボタンのインデックス
	PLBC_OneTouchButton c_Data;		// ワンタッチキー１ボタンのデータ
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78635 [UNINIT.STACK.MUST] initialized b_isSingle.
//	Bool b_isSingle;
	Bool b_isSingle = True;
	for( ss_enableCnt = 0; ss_enableCnt < ss_enableDataNum; ) {
		// データ取得
		getData( ss_dataCnt, c_Data, b_isSingle );
		// 表示対象となるデータかを判断
		if( ( c_Data.b_isDataValid == False ) && ( !b_isNullDataDisp ) ) {
			// 表示しないデータ
			;
		} else if( ( BTNID_DOCUMENTUSEBINDSEND == BOXC_DocumentSelectUseCom::getSelectKey() ) && ( True == onlyPanel.b_nowBoxMode )
		           && ( PLBD_ATS_Addr == c_Data.addressType || PLBD_ATS_IPFax == c_Data.addressType || PLBD_ATS_IFax == c_Data.addressType ) ) {
			// 表示しないデータ
			;
		} else {
			// 取得したデータが表示されるページを算出
			uc_getDataPage = ( uchar )( ( ss_enableCnt + 1 ) / ( uc_maxIndex + 1 ) );
			if( ( ss_enableCnt + 1 ) % ( uc_maxIndex + 1 ) ) {
				uc_getDataPage++;
			}
			// 指定されたページか？
			if( uc_getDataPage == uc_nowPage ) {
				// ボタン表示用データにセット
				PLBC_OneTouchKeyDisp::setButtonData( c_Data, uc_buttonIndex );
				uc_buttonIndex++;
			}
			ss_enableCnt++;
			// 現在表示中のページの処理を完了したらループを抜ける
			if( uc_nowPage < uc_getDataPage ) {
				break;
			}
		}
		ss_dataCnt++;
	}
}
/*================================================================================================
//概要    ：指定位置のデータの選択状態を更新する
//戻り値  ：True:成功 False:失敗
//備考    ：ページに 0 が指定された場合は、表示対象となる全データの選択状態を更新する
//          単一選択のチェックを行いデータをセットする
================================================================================================*/
Bool PLBC_OneTouchKeyGroupMemberAddress::updateData(
    Bool b_isSelected,	// 選択状態
    uchar uc_Page,		// ページ
    uchar uc_Index )	// インデックス
{
	// クラスの初期化処理を行う
	initClass();
	Bool 			b_ret = True;
	uchar 			uc_nowIndex = 0;		// ボタン位置（0～...）.
	TYPC_ShorteningAddress* pc_ShorteningAddress = NULL;	// 短縮情報ポインタ.
	// インデックスの範囲チェック.
	if( uc_maxIndex < uc_Index ) {
		return False;
	}
	// ポインタのチェック.
	if( plst_ShortAddress == NULL ) {
		return False;
	}
	plst_ShortAddress->Lock();
	// 全解除もしくは全選択の場合.
	if( 0 == uc_Page ) {
		Bool b_BoxAdrCheck = True;
		// リストに格納されている短縮宛先番号.
		pc_ShorteningAddress = plst_ShortAddress->findFirst();
		// 全選択 or 全解除処理.
		while( NULL != pc_ShorteningAddress ) {
			// データが参照可能か？ True:参照可能 False:参照不可.
			b_BoxAdrCheck = PnlComIsReferenceBoxInfoInShorteningAddress( pc_ShorteningAddress );
			if( False == b_BoxAdrCheck ) {
				// 次の検索結果を取得.
				pc_ShorteningAddress = plst_ShortAddress->findNext();
				// Jobへの更新は行わない.
				continue;
			}
			// list内、宛先の選択/解除設定.
			b_ret = setDataIGC( pc_ShorteningAddress, b_isSelected, True );
			// 次の検索結果を取得.
			pc_ShorteningAddress = plst_ShortAddress->findNext();
		}
	} else {
		// 単一の選択もしくは解除.
		// リストに格納されている短縮宛先番号.
		pc_ShorteningAddress = plst_ShortAddress->findFirst();
		while( NULL != pc_ShorteningAddress ) {
			// 指定されたボタン位置の判定.
			if( uc_nowIndex == uc_Index ) {
				break;
			}
			// ワンタッチキーのボタン位置更新.
			++uc_nowIndex;
			// 次の検索結果を取得.
			pc_ShorteningAddress = plst_ShortAddress->findNext();
		}
		// 宛先データNullチェック
		if( NULL != pc_ShorteningAddress ) {
			b_ret = setDataIGC( pc_ShorteningAddress, b_isSelected );
		} else {
			plst_ShortAddress->UnLock();
			return False;
		}
	}
	plst_ShortAddress->UnLock();
	return b_ret;
}
/*============================================================================================
//概要    ：データを全選択/全解除する
//戻り値  ：True:正常 False:異常
============================================================================================*/
Bool PLBC_OneTouchKeyGroupMemberAddress::setSelectALL(
    Bool b_isSelectALL		// True:全選択する False:全解除する
    ,Bool option			 	// True:関数呼び分け特別 False:関数呼び分けデフォルト
)
{
	// クラスの初期化処理を行う
	initClass();
	if( True == b_isSelectALL ) {
		if( NULL == pc_GroupAddress ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		if( NULL == PnlComGetJobScanFax() ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		short ss_AddressCnt = 0;
		short ss_EnableCnt = 0;
		short ss_SelectCnt = 0;
		TYPC_ShorteningAddress* pc_ShorteningAdr;
		plst_ShortAddress->Lock();
		pc_ShorteningAdr = plst_ShortAddress->findFirst();
		Bool b_BoxAdrCheck = True;
		// list内データ参照処理.
		while( NULL != pc_ShorteningAdr ) {
			// データが参照可能か？ True:参照可能 False:参照不可.
			b_BoxAdrCheck = PnlComIsReferenceBoxInfoInShorteningAddress( pc_ShorteningAdr );
			if( False == b_BoxAdrCheck ) {
				pc_ShorteningAdr = plst_ShortAddress->findNext();
				// 短縮宛先数のカウントしない.
				continue;
			}
			// 宛先種別を取得.
			TYPE_SendMode e_SendMode = pc_ShorteningAdr->getSendMode();
			if( TYPE_SendModeEmail == e_SendMode
			    && True == PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_MailSend.getSmimeEnableCrypt() ) {
				// 該当する宛先のメールアドレスを取得.
				TYPS_MailAddress s_MailAddress = pc_ShorteningAdr->getMailAddress();
				// 証明書レコードNoが０なら未登録.
				if( s_MailAddress.b_isSmimeExist == False ) {
					// グループに登録されている短縮宛先数をインクリメント.
					++ss_AddressCnt;
					pc_ShorteningAdr = plst_ShortAddress->findNext();
					continue;
				}
			}
			// 送信可否判定 見直し要.
			Bool b_IsNecessaryDataSet = False;
			if( True == isEnableSetAddressIGC( pc_ComSend, pc_ShorteningAdr->getSendMode(), True, True, False, False, pc_ShorteningAdr, &b_IsNecessaryDataSet,b_isFAX ) ) {
				const EP_Combination e_Combination = getCombinationType( pc_ShorteningAdr->getSendMode(), b_isFAX );
				if( False == combinationCheck( e_Combination, PnlComGetJobScanFax(), False, True ) ) {
					plst_ShortAddress->UnLock();
					return False;
				}
				// 送信可能な宛先数をインクリメント.
				++ss_EnableCnt;
				if( True == b_IsNecessaryDataSet ) {
					++ss_SelectCnt;
				}
			}
			pc_ShorteningAdr = plst_ShortAddress->findNext();
		}
		plst_ShortAddress->UnLock();
		// 送信可能な宛先が1件も無い場合.
		if( 0 == ss_EnableCnt ) {
			return False;
		}
		// TYPC_ComSendのコピー.
		TYPC_ComSend c_ComSend;
		memcpy( &c_ComSend, pc_ComSend, sizeof( TYPC_ComSend ) );
		// 解除される一時配信またはプログラムキーにリンクしている宛先を解除する.
		cancelSelectProgramAddress( &c_ComSend );
		const short ss_SelecShorteningAddressCount = c_ComSend.getSelecShorteningAddressCount();
		if( ( TYPD_MaxShorteningAddressInGroupAddress < ( ss_SelecShorteningAddressCount + ss_SelectCnt ) )
		    ||( onlyPanel.checkBroadcastOver( ss_SelectCnt, &c_ComSend ) == True ) )	 {
			// 同報件数オーバー.
			onlyPanel.setPanelWarning( PNL_ERROR_BroadcastOver );
		}
		// 同報件数オーバーの場合は設定不可.
		if( True == onlyPanel.isWarningOn( comPanelJob, PNL_ERROR_BroadcastOver ) ) {
			return False;
		}
	}
	const Bool b_ret = PLBC_OneTouchKey::setSelectALL( b_isSelectALL,option );
	return b_ret;
}
/*================================================================================================
//概要    ：指定位置のデータを取得する
================================================================================================*/
void PLBC_OneTouchKeyGroupMemberAddress::getData(
    short ss_dataCnt,				// 取得するデータのインデックス
    PLBC_OneTouchButton& rc_Data,	// ワンタッチキーのボタンデータ
    Bool& rb_isSingle,				// 単一選択種別
    Bool b_ShowParam )				// 表示用のデータ取得か判定
{
	// クラスの初期化処理を行う
	initClass();
	// ボタンデータを初期化
	rc_Data.b_isSelected = False;
	rc_Data.sc_buttonText[0] = NULL;
	rc_Data.buttonType = PLBD_BTS_Normal;
	rc_Data.b_isDataValid = False;
	rc_Data.addressType = PLBD_ATS_None;
	// 短縮宛先の番号
	rc_Data.ss_AddressNo = (short)( ss_dataCnt + 1 );
	// ポインタの確認
	if( pc_GroupAddress == NULL ) {
		return;
	}
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return;
	}
	// ボタンの選択状態取得
	rc_Data.b_isSelected = pc_ComSend->getShorteningAddress( rc_Data.ss_AddressNo );
	AddressTypeStatus addressType;
	// インスタンス取得
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//	APIC_ShorteningAddress* pc_AddrA = APIC_ShorteningAddress::newInstance( rc_Data.ss_AddressNo );
	APIC_ShorteningAddress* pc_AddrA = APIC_ShorteningAddress::newInstance( rc_Data.ss_AddressNo , PNLC_NetworkLan::getInstance()->getLine() );
	if( NULL == pc_AddrA ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;				// 静的解析 2012/09/04 第一OPS 酒井(健).
	}
	// 取得したデータが有効か？
	if( pc_AddrA->getRegistration() == False ) {
		return;
	}
	// 送信可否判定.
	if( False == isEnableSetAddress( pc_ComSend, pc_AddrA->getSendMode(), False,False, False, True, short( -1 ),NULL,b_isFAX ) ) {
		return;
	}
	// アドレス有効.
	rc_Data.b_isDataValid = True;
	// 表示用のデータ取得か判定(不要な文字コード変換処理をやめ、選択速度低下を抑制)
	if( b_ShowParam == True ) {
		// 表示用のデータ取得の場合はボタンに表示する文字列取得
		if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
			pc_AddrA->getAddressNameUTF8( rc_Data.sc_buttonText, TYPE_CharSetUTF8 );
		} else {
			pc_AddrA->getAddressNameUTF8( rc_Data.sc_buttonText, getCharSetForCAPI() );
		} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
	} else {
		// 表示用データ取得時以外はテキストデータは生成しない
		rc_Data.sc_buttonText[0] = '\0';
	}
	// ボタンに表示する文字列のフォントセット
	rc_Data.ep_charSet = ::getCharSetForPanel();
	// 表示するボタンの種類(グループメンバーの場合は固定)
	rc_Data.buttonType = PLBD_BTS_Normal;
	// 左上に表示する宛先種類
	TYPE_SendMode s_mode;
	s_mode = pc_AddrA->getSendMode();
	switch( s_mode ) {
		case TYPE_SendModeEmail:		addressType = PLBD_ATS_Mail;	break;
		case TYPE_SendModeIfax:			addressType = PLBD_ATS_IFax;	break;
		case TYPE_SendModeFtp:			addressType = PLBD_ATS_FTP;		break;
		case TYPE_SendModeSmb:			addressType = PLBD_ATS_SMB;		break;
		case TYPE_SendModeBox:			addressType = PLBD_ATS_Box;		break;
		case TYPE_SendModeFax:			addressType = PLBD_ATS_Addr;	break;
				
		case TYPE_SendModeIPAddressFax:	addressType = PLBD_ATS_IPFax;	break;
		case TYPE_SendModeWebDav:		addressType = PLBD_ATS_WebDAV;	break;
		default:						addressType = PLBD_ATS_None;	break;
	}
	rc_Data.addressType = addressType;
	// ユーティリティで設定されている宛先種類表示する/しないを判断
	// 単一選択種別(短縮宛先の場合は固定)
	rb_isSingle = False;
}
/*================================================================================================
//概要    ：指定位置のデータをセットする
//戻り値  ：True:成功 False:失敗
================================================================================================*/
Bool PLBC_OneTouchKeyGroupMemberAddress::setData(
    short ss_dataCnt,				// セットするデータのインデックス
    PLBC_OneTouchButton c_Data )	// ワンタッチキーのボタンデータ
{
	// クラスの初期化処理を行う
	initClass();
	Bool b_ret = True;
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return False;
	}
	// 現在のON/OFF情報を取得
	Bool b_now = pc_ComSend->getShorteningAddress( (short)( ss_dataCnt + 1 ) );
	if( b_now != c_Data.b_isSelected ) {
		b_ret = setShorteningAddressOneTouchKey( (short)( ss_dataCnt + 1 ), c_Data.b_isSelected, pc_ComSend, pc_Job, b_isFAX );
	}
	return b_ret;
}
// ===============================================================================================
/**
@name	PLBC_OneTouchKeyGroupMemberAddress::getOnOffIGC;
@brief	グループメンバ内の短縮宛先のON/OFF情報を取得する.
@param	TYPC_ShorteningAddress		pc_Address (I)		: ON/OFFを取得する短縮宛先データ.
@return	Bool:True:成功 False:失敗(共通配信設定が未設定).
@note	[レビュ－]	未実施.
@note	[備考]	【IGC機能対応】.
@author	2007/01/26		13川崎		新規作成.
*/
// ===============================================================================================
Bool PLBC_OneTouchKeyGroupMemberAddress::getOnOffIGC(
    TYPC_ShorteningAddress* pc_Address,		// ON/OFFを取得する短縮宛先データ.
    Bool& rb_isOn							// ON/OFF情報 True:ON False:OFF.
)
{
	// クラスの初期化処理を行う.
	initClass();

	// ポインタの確認.
	if( pc_ComSend == NULL ) {
		return False;
	}

	// IGCDBレコードIDを取得.
	uint32_t ui32_recordID = TYPD_NotSetting;
	ui32_recordID = pc_Address->getIgcRecodeId();

	// ボタンの選択状態取得.
	TYPC_ShorteningAddress* pc_Short = NULL;
	pc_Short = pc_ComSend->searchShorteningAddressByDbRecordNo( ui32_recordID );

	if( pc_Short != NULL )
	{
		// ジョブに登録済み.
		rb_isOn = True;
	}
	else
	{
		// ジョブに未登録.
		rb_isOn = False;
	}

	return True;
}

// ===============================================================================================
/**
@name	PLBC_OneTouchKeyGroupMemberAddress::setDataIGC;
@brief	選択/解除短縮宛先設定（単一）
@param	Bool			b_selectFlg		(I) :キー押下する前の選択状態.
@param	TYPC_ShorteningAddress*	pc_ShorteningAddress	(I) :短縮宛先データ.
@return	void.
@note	[レビュ－]	未実施.
@note	[備考]	【IGC機能対応】
@note	b_selectFlg		: 解除=0 選択=1.
@author	2007/1/25		13川崎		新規作成.
*/
// ===============================================================================================
Bool PLBC_OneTouchKeyGroupMemberAddress::setDataIGC( TYPC_ShorteningAddress* pc_ShorteningAddress, Bool b_selectFlg, Bool bl_IsAllSelect )
{
	uint32_t 				ui32_recordID	= TYPD_NotSetting;	// IGCレコードID
	TYPC_ShorteningAddress* pc_Short	= NULL;				// 選択or解除状態にある短縮宛先データ
	Bool					b_ret		= True;				// 戻り値
	Bool					b_now;

	// クラスの初期化処理を行う.
	initClass();

	// ポインタの確認.
	if( pc_ComSend == NULL ) {
		return False;
	}

	// IGCDBレコードIDを取得.
	ui32_recordID = pc_ShorteningAddress->getIgcRecodeId();

	// 短縮宛先データ取得.
	pc_Short = pc_ComSend->searchShorteningAddressByDbRecordNo( ui32_recordID );

	if( pc_Short != NULL )
	{
		// ジョブに登録済み.
		b_now = True;
	}
	else
	{
		// ジョブに未登録.
		b_now = False;
	}

	// ジョブに登録済みで解除状態 or ジョブに未登録で選択状態にある場合は更新を行う.
	if( b_now != b_selectFlg )
	{
		b_ret = setShorteningAddressOneTouchKeyIGC( pc_ShorteningAddress, b_selectFlg, pc_ComSend, pc_Job, b_isFAX, bl_IsAllSelect );
	}

	return b_ret;
}

