/*================================================================================================
//概要    ：ワンタッチキーを表示する.
//備考    ：一時配信(通常ワンタッチの1ページ目・幅広ワンタッチの1,2ページ目)のページ数を0ページから始める.
================================================================================================*/
void PLBC_FaxOneTouchKeyProgramKey::showOneTouch()
{
	// クラスの初期化処理を行う
	initClass();
	// 表示対象となるデータ数を取得する
	ss_enableDataNum = getEnableDataNum();
	// 総ページを設定
	uc_maxPage = ( uchar )( ss_enableDataNum / ( uc_maxIndex + 1 ) );
	if( ss_enableDataNum % ( uc_maxIndex + 1 ) ) {
		uc_maxPage++;
	}
	if( uc_maxPage == 0 ) {
		uc_maxPage = 1;
	}
	// 現在の表示ページを設定
	if( uc_maxPage < uc_nowPage ) {
		uc_nowPage = uc_maxPage;
	} else if( uc_nowPage < 1 ) {
		uc_nowPage = 1;
	}
	// 現在ページのデータを取得し、表示用ボタンデータにをセットする
	setPageData();
	ushort	us_nowPage_bk = uc_nowPage;
	ushort	us_maxPage_bk = uc_maxPage;
	Bool	bl_isWide = False;	// 幅広表示用のワンタッチキーか否か.
	bl_isWide = isWideOneTouchKey();
	if( True == bl_isWide ) {	// 幅広表示.
		// 一時配信(1,2ページ目)のページ数を0ページと表示させたいため現在ページ・最大ページを2減らす.
		if( 2 <= uc_nowPage ) {	// マイナスにならないようガード.
			uc_nowPage = (ushort)(uc_nowPage - 2);
		} else {
			uc_nowPage = 0;
		}
		if( 2 <= uc_maxPage ) {	// マイナスにならないようガード.
			uc_maxPage = (ushort)( uc_maxPage - 2 );
		} else {
			uc_maxPage = 0;
		}
	} else {	// 通常表示.
		// 一時配信(1ページ目)のページ数を0ページと表示させたいため現在ページ・最大ページを1減らす.
		if( 1 <= uc_nowPage ) {	// マイナスにならないようガード.
			uc_nowPage = (ushort)( uc_nowPage - 1 );
		} else {
			uc_nowPage = 0;
		}
		if( 1 <= uc_maxPage ) {	// マイナスにならないようガード.
			uc_maxPage = (ushort)( uc_maxPage - 1 );
		} else {
			uc_maxPage = 0;
		}
	}
	// ワンタッチキーを表示する
	PLBC_OneTouchKeyDisp::showOneTouch();
	// 現在ページ・最大ページを元に戻す.
	uc_nowPage = us_nowPage_bk;
	uc_maxPage = us_maxPage_bk;
}
/*================================================================================================
//概要    ：ワンタッチキーの押下によりボタンの選択状態を設定する
//          ↑↓キーの押下によりワンタッチキーのページを切り替える
//備考    ：画面クラスでワンタッチキーイベントが発生したときに、本関数をコールする
================================================================================================*/
void PLBC_FaxOneTouchKeyProgramKey::procOneTouchKey( uchar uc_Option )
{
	// クラスの初期化処理を行う
	initClass();
	// キー↑.
	if( uc_Option == PLBD_OneTouchUp ) {
		// ページが不正の場合は、何もしない.
		if( ( uc_nowPage < 1 ) || ( uc_maxPage < uc_nowPage ) ) {
			return;
		}
		// 手動入力禁止であるか確認
		if( True == isDisableAddressManualInput() ) {
			// 手動入力禁止の場合
			// 幅広ワンタッチキー表示であるか確認
			if( PnlComGetFaxPanelSetting()->getAddressDispLength() == TYPE_AddressDispLength14 ) {
				// 通常ワンタッチキー表示の場合
				// 前ページに切り替える.
				if( uc_nowPage == 2 ) {
					uc_nowPage = uc_maxPage;
				} else {
					uc_nowPage--;
				}
			} else {
				// 幅広ワンタッチキーの場合
				// 前ページに切り替える.
				if( uc_nowPage == 3 ) {
					uc_nowPage = uc_maxPage;
				} else {
					uc_nowPage--;
				}
			}
		} else {
			// 前ページに切り替える.
			if( uc_nowPage == 1 ) {
				uc_nowPage = uc_maxPage;
			} else {
				uc_nowPage--;
			}
		}
		showOneTouch();
	}
	// キー↓.
	else if( uc_Option == PLBD_OneTouchDown ) {
		// ページが不正の場合は、何もしない.
		if( ( uc_nowPage < 1 ) || ( uc_maxPage < uc_nowPage ) ) {
			return;
		}
		// 手動入力禁止であるか確認
		if( True == isDisableAddressManualInput() ) {
			// 手動入力禁止の場合
			// 幅広ワンタッチキー表示であるか確認
			if( PnlComGetFaxPanelSetting()->getAddressDispLength() == TYPE_AddressDispLength14 ) {
				// 通常ワンタッチキー表示の場合
				// 前ページに切り替える.
				if( uc_nowPage == uc_maxPage ) {
					uc_nowPage = 2;
				} else {
					uc_nowPage++;
				}
			} else {
				// 幅広ワンタッチキーの場合
				// 前ページに切り替える.
				if( uc_nowPage == uc_maxPage ) {
					uc_nowPage = 3;
				} else {
					uc_nowPage++;
				}
			}
		} else {
			// 次ページに切り替える
			if( uc_nowPage == uc_maxPage ) {
				uc_nowPage = 1;
			} else  {
				uc_nowPage++;
			}
		}
		showOneTouch();
	}
	else if( ( PLBD_ButtonNumMax > uc_Option ) && ( PLBD_OneTouch23 >= uc_Option ) ) {
		// ボタンが押された場合は、現在の選択状態を反転させる
		changeSelectStatus( !c_OneTouchButton[uc_Option].b_isSelected, uc_Option );
	}
}
/*================================================================================================
//概要    ：ワンタッチキーを表示する
//備考    ：データ無しではワンタッチキーは表示しない
================================================================================================*/
void PLBC_FaxOneTouchKeyShorteningAddress::showOneTouch()
{
	// クラスの初期化処理を行う
	initClass();
	// ボタン表示用データを初期化する
	initOneTouchButton();
	// 検索リストを参照し、短縮宛先番号を取得する
	// 検索リストを参照し、短縮宛先データを取得する.
	TYPC_ShorteningAddress* pc_AddrA;				// 短縮宛先.
	PLBC_OneTouchButton c_Data;						// ワンタッチキーのボタンデータ
	uchar uc_index = 0;								// ワンタッチキーのボタン位置(0-
	// ポインタのチェック
	if( plst_ShortAddress != NULL ) {
		plst_ShortAddress->Lock();
		pc_AddrA = plst_ShortAddress->findFirst();
		while( pc_AddrA != NULL ) {
			// index の範囲チェック
			if( uc_maxIndex < uc_index ) {
				break;
			}
			// ボタンに表示する文字列取得
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				pc_AddrA->getAddressNameUTF8( c_Data.sc_buttonText, TYPE_CharSetUTF8 );
			} else {
				pc_AddrA->getAddressNameUTF8( c_Data.sc_buttonText, getCharSetForCAPI() );
			} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			// ボタンに表示する文字列のフォントセット
			c_Data.ep_charSet = ::getCharSetForPanel();
			// 短縮宛先番号
			// 表示用IDを取得.
			uint32_t ui32_DispNo = 0;
			ui32_DispNo = pc_AddrA->getDisplayNo();
			c_Data.ss_AddressNo = ( short )ui32_DispNo;
			// 表示するボタンの種類(短縮宛先の場合は固定)
			c_Data.buttonType = PLBD_BTS_Normal;
			// 左上に表示する宛先種類
			AddressTypeStatus addressType;
			TYPE_SendMode s_mode;
			s_mode = pc_AddrA->getSendMode();
			switch( s_mode ) {
				case TYPE_SendModeEmail:		addressType = PLBD_ATS_Mail;	break;
				case TYPE_SendModeFtp:			addressType = PLBD_ATS_FTP;		break;
				case TYPE_SendModeSmb:			addressType = PLBD_ATS_SMB;		break;
				case TYPE_SendModeBox:			addressType = PLBD_ATS_Box;		break;
				case TYPE_SendModeFax:
						addressType = PLBD_ATS_Addr;	break;
				case TYPE_SendModeIPAddressFax:	addressType = PLBD_ATS_IPFax;	break;
				case TYPE_SendModeIfax:			addressType = PLBD_ATS_IFax;	break;
				case TYPE_SendModeWebDav:		addressType = PLBD_ATS_WebDAV;	break;
				default:						addressType = PLBD_ATS_None;	break;
			}
			c_Data.addressType = addressType;
			// データが参照可能か？ True:参照可能 False:参照不可.
			c_Data.b_isActivated = PnlComIsReferenceBoxInfoInShorteningAddress( pc_AddrA );
			// ボタンの選択状態取得
			Bool b_ret = False;
			if( onlyPanel.isSearchDigitalID() == True ) {
				b_ret = getOnOffDigitalID( pc_AddrA->getIgcRecodeId(), c_Data.b_isSelected );
			} else {
				b_ret = getOnOffIGC( pc_AddrA, c_Data.b_isSelected );
			}
			if( !b_ret ) {
				plst_ShortAddress->UnLock();
				return;
			}
			// 短縮宛先の内容をワンタッチキーにセット
			setButtonData( c_Data, uc_index );
			// ワンタッチキーのボタン位置更新
			uc_index++;
			// 次の検索結果を取得
			pc_AddrA = plst_ShortAddress->findNext();
		}
		plst_ShortAddress->UnLock();
	}		// if (plst_Index != NULL)
	// １文字検索ボタンの選択状態を設定する
	for( uc_index = 0; uc_index < PLBD_OneTouchSearchKeyNum; uc_index++ ) {
		Key_OneTouchSearch[uc_index].select( b_SearchKeySelected[uc_index] );
	}
	// ワンタッチキーを表示する
	PLBC_OneTouchKeyDisp::showOneTouch();
	// 切替ボタンの表示非表示を設定する
	if( ( searchKeyType == PLBD_OTSK_A ) || ( searchKeyType == PLBD_OTSK_B ) ) {
		if( searchKeyType == PLBD_OTSK_A ) {		// ひらがな
			Key_OneTouchSearch[11].changeText( s_KEYBoxConversionEng );				// 英字に切替
		} else {									// 英字
			Key_OneTouchSearch[11].changeText( s_KEYBoxConversionKana );				// かなに切替
		}
		Key_OneTouchSearch[11].showEnable( True );
	} else {
		Key_OneTouchSearch[11].showEnable( False );
	}
}
