// ===============================================================================================
/**
@name	PLBC_OneTouchKeyDispShorteningAddressSearch::getOnOffIGC;
@brief	短縮宛先のON/OFF情報を取得する.
@param	TYPC_ShorteningAddress		pc_Address (I)		: ON/OFFを取得する短縮宛先データ.
@return	Bool:True:成功 False:失敗(共通配信設定が未設定).
@note	[レビュ－]	未実施.
@note	[備考]	【IGC機能対応】.
@author	2007/1/22		13開発鶴見		新規作成.
*/
// ===============================================================================================
Bool PLBC_OneTouchKeyDispShorteningAddressSearch::getOnOffIGC(
    TYPC_ShorteningAddress* pc_Address,		// ON/OFFを取得する短縮宛先データ.
    Bool& rb_isOn							// ON/OFF情報 True:ON False:OFF
)
{
	// クラスの初期化処理を行う
	initClass();

	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return False;
	}

	uint32_t ui32_DispNo = pc_Address->getDisplayNo();
// comment 2015/10/23 OP1-Sky森山 [MinervaSBK][MZV-48] ScanToURLとScanToE-Mailの機能拡張対応.
//	if( ui32_DispNo == PCGD_ScanToMeIndex || ui32_DispNo == PCGD_ScanToHomeIndex ) {
	if( ui32_DispNo == PCGD_ScanToMeIndex || ui32_DispNo == PCGD_ScanToHomeIndex || ui32_DispNo == PCGD_ScanToURLIndex ) {
		// 直接の宛先から登録済みかをチェックする処理を入れる.
		char sc_Index;
		rb_isOn = isSetDirectAddress( pc_Address ,&sc_Index );
		return True;
	}

	// IGCDBレコードIDを取得.
	uint32_t ui32_recordID = TYPD_NotSetting;
	ui32_recordID = pc_Address->getIgcRecodeId();

	// ボタンの選択状態取得
	TYPC_ShorteningAddress* pc_Short = NULL;
	pc_Short = pc_ComSend->searchShorteningAddressByDbRecordNo( ui32_recordID );

	if( pc_Short != NULL )
	{
		// ジョブに登録済み.
		rb_isOn = True;
	}
	else
	{
		// ジョブに未登録.
		rb_isOn = False;
	}

	return True;
}

// ===============================================================================================
/**
@name	PLBC_OneTouchKeyDispShorteningAddressSearch::setOnOffIGC;
@brief	短縮宛先のON/OFF情報をセットする.
@param	TYPC_ShorteningAddress		pc_Address (I)		: ON/OFFを取得する短縮宛先データ.
@return	Bool:True:成功 False:失敗(共通配信設定が未設定).
@note	[レビュ－]	未実施.
@note	[備考]	【IGC機能対応】.
@author	2007/1/22		13開発鶴見		新規作成.
*/
// ===============================================================================================
Bool PLBC_OneTouchKeyDispShorteningAddressSearch::setOnOffIGC(
    TYPC_ShorteningAddress* pc_Address,		// ON/OFFをセットする短縮宛先データ.
    Bool b_isOn								// ON/OFF情報 True:ON False:OFF
)
{
	// 現在のジョブへの宛先登録状態.
	Bool b_now = False;

	// クラスの初期化処理を行う
	initClass();

	Bool b_ret = True;
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return False;
	}

	uint32_t ui32_DispNo = pc_Address->getDisplayNo();
// comment 2015/10/23 OP1-Sky森山 [MinervaSBK][MZV-48] ScanToURLとScanToE-Mailの機能拡張対応.
//	if( ui32_DispNo == PCGD_ScanToMeIndex || ui32_DispNo == PCGD_ScanToHomeIndex ) {
	if( ui32_DispNo == PCGD_ScanToMeIndex || ui32_DispNo == PCGD_ScanToHomeIndex || ui32_DispNo == PCGD_ScanToURLIndex ) {
		char sc_Index;
		// 直接の宛先から登録済みかをチェックし、宛先登録もしくはキャンセルする処理を入れる.
		if( isSetDirectAddress( pc_Address,&sc_Index ) == False && b_isOn == True ) {
			// 宛先登録処理.
			b_ret = addDirectAddress( pc_Address );
			if( b_ret == False ) {
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return False;
			}
		} else if( isSetDirectAddress( pc_Address,&sc_Index ) == True && b_isOn == False ) {
			// 宛先削除処理.
			b_ret = delDirectAddress( pc_Address,sc_Index );
			if( b_ret == False ) {
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return False;
			}
			while( isSetDirectAddress( pc_Address,&sc_Index ) == True ) {
				b_ret = delDirectAddress( pc_Address,sc_Index );
				if( b_ret == False ) {
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					return False;
				}
			}
		}
		if( b_now != b_isOn && b_isOn == True ) {
			setDefaultFileNameOneTouchKey( pc_Job );
		}
		return b_ret;
	}

	// 現在のON/OFF情報を取得.
	// IGCDBレコードIDを取得.
	uint32_t ui32_recordID = TYPD_NotSetting;
	ui32_recordID = pc_Address->getIgcRecodeId();

	// ボタンの選択状態取得
	TYPC_ShorteningAddress* pc_Short = NULL;
	pc_Short = pc_ComSend->searchShorteningAddressByDbRecordNo( ui32_recordID );

	if( pc_Short != NULL )
	{
		// ジョブに登録済み.
		b_now = True;
	}
	else
	{
		// ジョブに未登録.
		b_now = False;
	}

	if( b_now != b_isOn ) {
		b_ret = setShorteningAddressOneTouchKeyIGC( pc_Address, b_isOn, pc_ComSend, pc_Job, b_isFAX );
	}

	return b_ret;
}

