/*================================================================================================
//概要    ：短縮宛先のON/OFF情報をセットする
//戻り値  ：True:成功 False:失敗(共通配信設定が未設定)
================================================================================================*/
Bool PLBC_OneTouchKeyDispEmailNotificationSearch::setOnOff(
    short ss_AddressNo,				// ON/OFFをセットする短縮宛先番号
    Bool b_isOn )					// ON/OFF情報 True:ON False:OFF
{
	char c_initTxt[PCGD_MaxKeybordInfoBuffer];		// 宛先情報初期化用
	memset( c_initTxt, '\0', sizeof( c_initTxt ) );
	// クラスの初期化処理を行う
	initClass();
	// ポインタの確認
	if( pc_ComSend == NULL ) {
		return False;
	}
	// 宛先選択情報の初期化
	pc_ComSend->c_EmailNotification.setShorteningAddress( TYPD_NotSetting );
	pc_ComSend->c_EmailNotification.setEmailNotificationOn( False );
	pc_ComSend->c_EmailNotification.setEmailNotificationMailAddress( c_initTxt );
	if( b_isOn ) {
		// 選択状態になった場合、短縮宛先内データをEメール通知側にコピーする
		APIC_ShorteningAddress* pc_AddrA;				// 短縮宛先
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//		pc_AddrA = APIC_ShorteningAddress::newInstance( ss_AddressNo );
		pc_AddrA = APIC_ShorteningAddress::newInstance( ss_AddressNo , PNLC_NetworkLan::getInstance()->getLine() );
		if( NULL == pc_AddrA ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;				// 静的解析 2012/09/04 第一OPS 酒井(健).
		}
		// 取得したデータが有効か？
		if( pc_AddrA->getRegistration() == False ) {
			return False;
		}
		// 種別取得
		if( TYPE_SendModeEmail == pc_AddrA->getSendMode() ) {
			// 種別がE-Mailなのでコピー開始
			pc_ComSend->c_EmailNotification.setShorteningAddress( ss_AddressNo );
			pc_ComSend->c_EmailNotification.setEmailNotificationOn( True );
			pc_ComSend->c_EmailNotification.setEmailNotificationMailAddress( pc_AddrA->getMailAddress().sc_MailToAddress );
		} else {
			// 種別がE-Mail以外はエラー
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		}
	}
	return True;
}


