//================================================================================================.
void PNLC_IMEManager::reqSetState( const Bool bl_State )
{
	if( ( NULL != m_pc_IMEControl ) && ( NULL != m_pst_IMETxtInfo ) ) {
		APIE_IMEState e_State = APIE_IMEStateOff;
		if( True == bl_State ) {
			e_State = APIE_IMEStateOn;
		}
		m_pc_IMEControl->setState( e_State, m_pst_IMETxtInfo );
		m_bl_State = bl_State;
	}
}


