//============================================================================================
//概要    ：入力禁止文字キー非表示.
//============================================================================================
void PLBC_GeneralKeybord::setDisableKeyCharCode(
    short		ss_Pattern )			// パターン.
{
	static const Sc_SetDisableKeyCodeType*		p_SetKey;
	short		ss_NowIndex = 0;
	short		uc_cnt = 0;
	ss_DisableKeyPattern = ss_Pattern;									// 入力禁止文字パターンを保存.
	PDPC_KeyMapManager* pc_KeyMapManager = PDPC_KeyMapManager::newInstance();	//【UV-00783】Sky_hosokawa 無効文字フィルタリング.
	Bool bl_AltGrKeyDisplay = isAltGrKeyDisplay();
	Bool bl_isDisableKey = False;	// Check for characters hiding True:Hide,False:Don't hide.
	short ss_UseKeyCntNum = 1;		// In case of KC_DisableKeyPatternNon, default is 1.
	if( ss_Pattern != KC_DisableKeyPatternNon ) {
		p_SetKey = &sc_SetDisableKeyCode[ss_Pattern];
		ss_UseKeyCntNum = p_SetKey->ss_UseKeyCnt; // The count of input disabled character keys.
		bl_isDisableKey = True;                   // Hide input disable character keys.
	} else {
// Non ASCII keys should be hidden in standard keyboards for English(marketing area EU) or for other European country languages.
		if( True == bl_AltGrKeyDisplay ) {
			bl_isDisableKey = True;
		}
	}
	if( True == bl_isDisableKey ) {  // Hide the input disable keys.
		for( ss_NowIndex = 0; ss_NowIndex < ss_UseKeyCntNum && ss_NowIndex < KC_MAX_KeyCount; ss_NowIndex++ ) {
			for( uc_cnt = 0; uc_cnt < PLBD_KeyNumMaxEnl; uc_cnt++ ) {
				char sc_TempChar[TYPD_CharCode] = {0,0,0};
// comment 2021/02/18 Sky Kawanishi [LocalUI特ROM][TAS000000005888]OP_BTS-23394で追加したPLBD_KBT_NumberOnlyがカスタマイズ対象外になっていない問題対応.
// comment 2022/11/03 FPT-LINHNV46 [IT6_2.2MR3][OP_BTS-40427] check NULL for tbl_MSbinKeyTbl.
				if( True == PLBC_FuncVersionCheck::isOK_Type3()
				    &&  True == pc_KeyMapManager->isSoftKeyBoardKeyMapFromMSbin( PnlComGetSoftwareKeyboardLanguage() )
				    &&  PLBD_KBT_CharacterCodeInputWide != keybordType && PLBD_KBT_CharacterCodeInput != keybordType
				    &&  PLBD_KBT_Alphabet_L != keybordType && PLBD_KBT_Alphabet_S != keybordType
				    &&  PLBD_KBT_Alphabet_S_Custom != keybordType && PLBD_KBT_Alphabet_L_Custom != keybordType
				    &&  PLBD_ENL_KBT_Alphabet_S_Custom != keybordType && PLBD_ENL_KBT_Alphabet_L_Custom != keybordType
				    &&  PLBD_ENL_KBT_CharacterCodeInputWide != keybordType && PLBD_ENL_KBT_CharacterCodeInput != keybordType
				    &&  PLBD_KBT_NumberOnly != keybordType
					&&	NULL != tbl_MSbinKeyTbl ) {
					memcpy( sc_TempChar, tbl_MSbinKeyTbl->keyInfo[uc_cnt].sc_KeyTopChar, sizeof( sc_TempChar ) );
					PnlComkeyBoardInputCharUnicodeToNativecode( sc_TempChar );		// Unicodeから各国文字集合に変換.
				} else {
					strcpy( sc_TempChar, keyTbl[keybordType].keyInfo[uc_cnt].sc_CharCode );
				}
// Character Code comparision is being done only if there is any pattern.
				Bool bl_disablekey = False; // Check for characters hiding True:Hide,False:Don't hide.
				if( ss_Pattern != KC_DisableKeyPatternNon ) {
// Character Code comparision is being done for the characters that has to be hidden for specific disable key pattern.
					if( sc_TempChar[0] == p_SetKey->sc_CharCode[ss_NowIndex] ) {
						bl_disablekey = True;
					}
				}
// Non ASCII keys (character code more than 0x80)should be hidden in standard keyboards for English(marketing area EU) or for other European country languages.
				if( True == bl_AltGrKeyDisplay ) {
					if( 0x80 & sc_TempChar[0] ) {
						bl_disablekey = True;
					}
				}
				if( True == bl_disablekey ) {
// Key that has to be hidden.
					if( PLBD_Enl_KBD_Enlarge == getChangeEnlKeybord() ) {	// 拡大キーボード.
						Tfd_EnlKeybord[uc_cnt].showEnable( False );
						Kty_EnlKeybord[uc_cnt].showEnable( False );
					} else {							// 標準キーボード.
						Tfd_Keybord[uc_cnt].showEnable( False );
						Kty_Keybord[uc_cnt].showEnable( False );
					}
				}
			}
		}
	}
}

//============================================================================================
//概要    ：入力禁止文字キー非表示.
//        ：PLBC_GeneralKeybord::setDisableKeyCharCode()処理流用.
//============================================================================================
void PLBC_GeneralKeybord::setDisableKeyCharCode_COM(
    short		ss_Pattern )			// パターン.
{
	static const Sc_SetDisableKeyCodeType*		p_SetKey;
	short		ss_NowIndex = 0;
	short		ss_cnt = 0;
	ss_DisableKeyPattern = ss_Pattern;									// 入力禁止文字パターンを保存.

	Bool bl_AltGrKeyDisplay = isAltGrKeyDisplay();
	PDPC_KeyMapManager* pc_KeyMapManager = PDPC_KeyMapManager::newInstance();
	Bool bl_isDisableKey = False;	// Check for characters hiding True:Hide,False:Don't hide.
	short ss_UseKeyCntNum = 1;		// In case of KC_DisableKeyPatternNon, default is 1.
	if( ss_Pattern != KC_DisableKeyPatternNon )
	{
		p_SetKey = &sc_SetDisableKeyCode[ss_Pattern];
		ss_UseKeyCntNum = p_SetKey->ss_UseKeyCnt;	// The count of input disabled character keys.
		bl_isDisableKey = True;                     // Hide input disable character keys.
	} else {
// Non ASCII keys should be hidden in standard keyboards for English(marketing area EU) or for other European country languages.
		if( True == bl_AltGrKeyDisplay ) {
			bl_isDisableKey = True;
		}
	}

// comment 2015/12/21 OPS1-Sky飯田 [ZeusS_ZX0][反応総点検][CQ523533].
	memset( m_bl_EnableKeyArray, True, sizeof( m_bl_EnableKeyArray ) );

	if( True == bl_isDisableKey ) { // Hide the input disable keys.
		for( ss_NowIndex = 0; ( ( ss_NowIndex < ss_UseKeyCntNum ) && ( ss_NowIndex < KC_MAX_KeyCount ) ); ss_NowIndex++ )
		{
			for( ss_cnt = 0; ss_cnt < PLBD_KeyNumMaxEnl; ss_cnt++ )
			{
				char sc_TempChar[TYPD_CharCode] = {0};
				// メッセージバイナリからキーマップを読み込む場合、Unicode からローカルの文字コードに変換.
// comment 2021/02/18 Sky Kawanishi [LocalUI特ROM][TAS000000005888]OP_BTS-23394で追加したPLBD_KBT_NumberOnlyがカスタマイズ対象外になっていない問題対応.
// comment 2022/11/03 FPT-LINHNV46 [IT6_2.2MR3][OP_BTS-40427] check NULL for tbl_MSbinKeyTbl.
				if( ( True == PLBC_FuncVersionCheck::isOK_Type3() )
				    && ( True == pc_KeyMapManager->isSoftKeyBoardKeyMapFromMSbin( PnlComGetSoftwareKeyboardLanguage() ) )
				    && ( PLBD_KBT_CharacterCodeInputWide != keybordType )
				    && ( PLBD_KBT_CharacterCodeInput != keybordType )
				    && ( PLBD_ENL_KBT_CharacterCodeInputWide != keybordType )
				    && ( PLBD_KBT_Alphabet_L != keybordType )
				    && ( PLBD_KBT_Alphabet_S != keybordType )
				    && ( PLBD_KBT_Alphabet_S_Custom != keybordType )
				    && ( PLBD_KBT_Alphabet_L_Custom != keybordType )
				    && ( PLBD_ENL_KBT_Alphabet_S_Custom != keybordType )
				    && ( PLBD_ENL_KBT_Alphabet_L_Custom != keybordType )
				    && ( PLBD_ENL_KBT_CharacterCodeInput != keybordType )
					&& ( PLBD_KBT_NumberOnly != keybordType )
					&&	NULL != tbl_MSbinKeyTbl ) {
					memcpy( sc_TempChar, tbl_MSbinKeyTbl->keyInfo[ss_cnt].sc_KeyTopChar, sizeof( sc_TempChar ) );
					PnlComkeyBoardInputCharUnicodeToNativecode( sc_TempChar );		// Unicodeから各国文字集合に変換.
				}
				else {
					strcpy( sc_TempChar, keyTbl[keybordType].keyInfo[ss_cnt].sc_CharCode );
				}
				Bool bl_disablekey = False; // Check for characters hiding True:Hide,False:Don't hide.
				if( ss_Pattern != KC_DisableKeyPatternNon ) {
// Character Code comparision is being done for the characters that has to be hidden for specific disable key pattern.
					if( sc_TempChar[0] == p_SetKey->sc_CharCode[ss_NowIndex] ) {
						bl_disablekey = True;
					}
				}
// Non ASCII keys (character code more than 0x80)should be hidden in standard keyboards for English(marketing area EU) or for other European country languages.
				if( True == bl_AltGrKeyDisplay ) {
					if( 0x80 & sc_TempChar[0] ) {
						bl_disablekey = True;
					}
				}
				if( True == bl_disablekey ) {
// Key that has to be hidden.
					Tfd_Keybord_COM[ss_cnt].showEnable( False );
					Kty_Keybord_COM[ss_cnt].showEnable( False );
					if( PNLE_KEYTOPTYPE_Small == uc_KeyTopType ) {
						Tfd_Keybord_COM_HL[ss_cnt].showEnable( False );
						Kty_Keybord_COM_HL[ss_cnt].showEnable( False );
					}
// comment 2015/12/21 OPS1-Sky飯田 [ZeusS_ZX0][反応総点検][CQ523533].
					m_bl_EnableKeyArray[ss_cnt] = False;
				}
			}
		}
	}
}

//============================================================================================
//概要    ：入力禁止文字判定.
//戻り値  ：True	入力禁止文字, False		入力許可文字.
//============================================================================================
Bool PLBC_GeneralKeybord::isDisableKeyCharCode(
    char*		sc_CharCode )			// 文字.
{
	static const Sc_SetDisableKeyCodeType*		p_SetKey;
	short		ss_NowIndex = 0;
	if( ss_DisableKeyPattern == KC_DisableKeyPatternNon ) { return False; }		// 入力禁止文字なし.

	p_SetKey = &sc_SetDisableKeyCode[ss_DisableKeyPattern];
	if( 0x20 == sc_CharCode[0] )	{
		for( uchar i = 0; i < TYPD_USBKeyInvalidControlCodeMAX; i++ )	{
			if( TYPE_USBkey_Space == e_USBKeyInvalidControlCode[i] )	{ return True; }
		}
	}
	for( ss_NowIndex = 0; ss_NowIndex < p_SetKey->ss_UseKeyCnt && ss_NowIndex < KC_MAX_KeyCount; ss_NowIndex++ ) {
		PDPC_KeyMapManager* pc_KeyMapManager = PDPC_KeyMapManager::newInstance();
		char sc_TempChar[TYPD_CharCode] = {0,0,0};
		memcpy( sc_TempChar, sc_CharCode, sizeof( sc_TempChar ) );
		if( True == PLBC_FuncVersionCheck::isOK_Type3() )	{
			if( True == isUSBKeyBoardMode() )	{
				if( True == pc_KeyMapManager->isUSBKeyBoardKeyMapFromMSbin( PnlComGetUSBKeyboardLanguage() ) )	{
					PnlComkeyBoardInputCharUnicodeToNativecode( sc_TempChar );		// Unicodeから各国文字集合に変換.
				}
			} else {
// comment 2021/02/18 Sky Kawanishi [LocalUI特ROM][TAS000000005888]OP_BTS-23394で追加したPLBD_KBT_NumberOnlyがカスタマイズ対象外になっていない問題対応.
				if( True == pc_KeyMapManager->isSoftKeyBoardKeyMapFromMSbin( PnlComGetSoftwareKeyboardLanguage() )
				    &&  PLBD_KBT_CharacterCodeInputWide != keybordType && PLBD_KBT_CharacterCodeInput != keybordType
				    &&  PLBD_KBT_Alphabet_L != keybordType && PLBD_KBT_Alphabet_S != keybordType
				    &&  PLBD_KBT_Alphabet_S_Custom != keybordType && PLBD_KBT_Alphabet_L_Custom != keybordType
				    &&  PLBD_ENL_KBT_Alphabet_S_Custom != keybordType && PLBD_ENL_KBT_Alphabet_L_Custom != keybordType
				    &&  PLBD_ENL_KBT_CharacterCodeInputWide != keybordType && PLBD_ENL_KBT_CharacterCodeInput != keybordType
				    &&  PLBD_KBT_NumberOnly != keybordType)	{
					PnlComkeyBoardInputCharUnicodeToNativecode( sc_TempChar );		// Unicodeから各国文字集合に変換.
				}
			}
		}
		if( sc_TempChar[0] == p_SetKey->sc_CharCode[ss_NowIndex] )	{ return True; }
	}
	return False;
}
//============================================================================================
//概要    ：初期キーボード状態設定１.
//戻り値  ：キーボード切換え初期状態設定フラグ		True:設定した		False:設定していない.
//============================================================================================
Bool PLBC_GeneralKeybord::setInitKeybordStatus1()
{
	Bool	b_RetCode = False;		// 設定していない.
	if( False == onlyPanel.b_InitKeybord ) {	// キーボード切換え初期状態であれば設定する.
		setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
		b_RetCode = True;
	}
	return( b_RetCode );
}
//============================================================================================
//概要    ：初期キーボード状態設定２.
//備考　　：キーボード表示状態（標準、拡大）によって初期キーボード状態を設定.
//戻り値  ：キーボード表示状態		PLBD_Enl_KBD_Normal:標準	以外:拡大.
//============================================================================================
EnlKeybordState PLBC_GeneralKeybord::setInitKeybordStatus2()
{
	EnlKeybordState		e_EnlKeybordState = PLBD_Enl_KBD_Enlarge;		// 切換えキーボード状態.
	if( PLBD_Enl_KBD_Normal == getChangeEnlKeybord() ) {	// 標準⇒拡大への切換えの場合.
		setChangeEnlKeybord( PLBD_Enl_KBD_Enlarge );	// 状態を拡大に変更.
		e_EnlKeybordState = PLBD_Enl_KBD_Normal;
	} else {	// 拡大⇒標準への切換えの場合.
		setChangeEnlKeybord( PLBD_Enl_KBD_Normal );		// 状態を標準に変更.
	}

	StartUSBKeyBordOn();	// OP1-Sky田村 [特ROM対応][MZV-28] ユーザログイン画面の文字入力タイプと表示言語連動対応 Add.

	return( e_EnlKeybordState );
}
// KeyBordClass 共通化.

//================================================================================================
//概要    ：USBキーボードキー押下時の文字コードもしくは制御コードを格納する.
//戻り値  ：なし
//備考    ：なし
//作成者  ：13細川
//レビュー：未実施
//変更履歴：
//================================================================================================
void PLBC_GeneralKeybord::setUSBKeyCharCode( int32_t sl_USBKeyData ) {
	// 文字・制御コードデータを格納する.
	int32_t i32_TmpBuff = 0;

	sc_MmbUsbKeyCharCode[0] = (char)(sl_USBKeyData >> 24);

	i32_TmpBuff = sl_USBKeyData << 8;
	sc_MmbUsbKeyCharCode[1] = (char)(i32_TmpBuff >> 24);

	i32_TmpBuff = sl_USBKeyData << 16;
	sc_MmbUsbKeyCharCode[2] = (char)(i32_TmpBuff >> 24);
}


//================================================================================================
//概要    ：USBキーボードキー押下時の文字コードもしくは制御コードを取得する.
//戻り値  ：なし
//備考    ：なし
//作成者  ：13細川
//レビュー：未実施
//変更履歴：
//================================================================================================
void PLBC_GeneralKeybord::getUSBKeyCharCode( char* sc_USBKeyCharCode ) {
	memcpy( sc_USBKeyCharCode, sc_MmbUsbKeyCharCode, sizeof( sc_MmbUsbKeyCharCode ) );
}

//================================================================================================
//概要    ：引数で渡された文字コードが、有効か無効か判定する関数（USBキーボードキー押下時）.
//戻り値  ：True	有効文字コード, False		無効文字コード.
//備考    ：なし
//作成者  ：13細川
//レビュー：未実施
//変更履歴：
//================================================================================================
Bool PLBC_GeneralKeybord::isUSBKeyCharCode( char* sc_CharCode ) {

	if( TYPE_USBKeyIPvGamen_Non != e_USBKeyIPvGamen )
	{
		return True;
	}
	if( True == isDisableKeyCharCode( sc_CharCode ) )
	{
		return False;
	}

	for( int i = 0; i < TYPD_USBKeyEnableCCodeMAX; i++ ) {
		if( 0 == memcmp( sc_CharCode, sc_USBKeyEnableCharCode[i], TYPD_CharCode ) ) {
			return True;
		}
	}
	return False;
}

//================================================================================================
//概要    ：引数で渡された制御コードが、有効か無効か判定する関数（USBキーボードキー押下時）.
//戻り値  ：True	有効制御コード, False		無効制御コード.
//備考    ：なし
//作成者  ：13細川
//レビュー：未実施
//変更履歴：
//================================================================================================
Bool PLBC_GeneralKeybord::isUSBKeyControlCode( char* sc_CharCode ) {

	if( True == PLBC_FuncVersionCheck::isOK_Type3() ) { return True; }	//【UV-00783】Sky_hosokawa.

	for( int i = 0; i < TYPD_USBKeyInvalidControlCodeMAX; i++ ) {
		if( 0 == memcmp( &sc_CharCode[2], ( const void* )&e_USBKeyInvalidControlCode[i], 1 ) ) {
			return False;
		}
	}
	return True;
}

