//================================================================================================
//概要    ：画面クラスで非表示にされているキーボードキー(Kty_ Keybord[*])の配列要素番号を格納する.
//戻り値  ：なし.
//備考    ：bit単位のフラグでキー番号を保持する.
//作成者  ：13細川
//レビュー：未実施
//変更履歴：
//================================================================================================
void PLBC_GeneralKeybord::registUSBKeyInvalidKey( uchar uc_KeyNum, KeybordType e_KeybordType ) {

	switch( e_KeybordType ) {
		case PLBD_KBT_EMail:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_EmailNormalInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_EmailNormalInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_EmailNormalInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_EmailNormalInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		case PLBD_KBT_EMailShift:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_EmailShiftInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_EmailShiftInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_EmailShiftInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_EmailShiftInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		case PLBD_KBT_Japan:
		case PLBD_KBT_German:
		case PLBD_KBT_France:
		case PLBD_KBT_Italy:
		case PLBD_KBT_Spain:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_CountryInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_CountryInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_CountryInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_CountryInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		case PLBD_KBT_JapanAnother:
		case PLBD_KBT_GermanShift:
		case PLBD_KBT_FranceShift:
		case PLBD_KBT_ItalyShift:
		case PLBD_KBT_SpainShift:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_CountryShiftInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_CountryShiftInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_CountryShiftInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_CountryShiftInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		case PLBD_KBT_GermanAltGr:
		case PLBD_KBT_FranceAltGr:
		case PLBD_KBT_ItalyAltGr:
		case PLBD_KBT_SpainAltGr:
		case PLBD_KBT_Katakana:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_AltInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_AltInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_AltInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_AltInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		case PLBD_KBT_KatakanaAnother:
		case PLBD_KBT_Euro_L:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_Another1InvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_Another1InvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_Another1InvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_Another1InvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;
		case PLBD_KBT_Euro_S:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_Another2InvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_Another2InvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_Another2InvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_Another2InvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;
		case PLBD_KBD_AllCharUSBKey:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_AllTypeInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_AllTypeInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_AllTypeInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_AllTypeInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;
		case PLBD_KBD_AllCharUSBKeyShift:
			if( 32 > uc_KeyNum ) {
				if( 0 == ( s_InvalidKey.ul_AllTypeShiftInvalidKey[0] & ( 0x01 << uc_KeyNum ) ) ) {
					s_InvalidKey.ul_AllTypeShiftInvalidKey[0] |= ( 0x01 << uc_KeyNum );
				}
			} else {
				if( 0 == ( s_InvalidKey.ul_AllTypeShiftInvalidKey[1] & ( 0x01 << ( uc_KeyNum-32 ) ) ) ) {
					s_InvalidKey.ul_AllTypeShiftInvalidKey[1] |= ( 0x01 << ( uc_KeyNum-32 ) );
				}
			}
			break;

		default:
			break;
	}
}

