	// USBキーボード無効キー判定用、画面保持キーボードパーツフラグを初期化.
	Bool bl_Have_Key_KeybordcomShift = False;		// Shiftキー.
	Bool bl_Have_Key_KeybordcomElseKana = False;	// 他かなキー.
