	Bool bl_Have_Key_KeybordcomNoConvert = False;	// 無変換キー.
	Bool bl_Have_Key_KeybordcomHalfKana = False;	// 半角キー(カタカナ入力中).
	Bool bl_Have_Key_ConvertPageUp = False;			// ページめくり上キー.
	Bool bl_Have_Key_ConvertPageDown = False;		// ページめくり下キー.
