//============================================================================================
//概要    ：画面毎の有効文字コードを配列へ格納する.
//戻り値  ：なし
//備考    ：なし
//作成者  ：13細川
//レビュー：未実施
//============================================================================================
void PLBC_GeneralKeybord::registCharCode( KeybordType e_KeyBordType ) {


	// 有効文字コードを取得する.
	for( uchar uc_KeyTblCnt = 0; uc_KeyTblCnt < PLBD_KeyNumMax; uc_KeyTblCnt++ )
	{
		// キーのテキストが""の場合は、文字コードを取得しない.
		if( keyTbl[ e_KeyBordType ].keyInfo[ uc_KeyTblCnt ].sc_KeyTopChar[0] != NULL )
		{
			strncpy( sc_USBKeyEnableCharCode[us_GetCount], ( const char* ) keyTbl[ e_KeyBordType ].keyInfo[ uc_KeyTblCnt ].sc_KeyTopChar, sizeof( sc_USBKeyEnableCharCode[us_GetCount] ) );
			us_GetCount++;
		}
	}
	if( ( TYPE_LanguageJapanese == PnlComGetLanguage() )	// ひらがな・カタカナで、他かな入力可能の場合.
	    && ( TYPE_USBKeyInput_Kana == pc_PanelManager->getUSBKeyBoardRomaKana() )
	    && ( True == bl_Key_KeybordcomElseKana ) ) {
		if( TYPE_USBKeyInput_Country == pc_PanelManager->getUSBKeyBoardCountry() ) {
			strncpy( sc_USBKeyEnableCharCode[us_GetCount], ( const char* )"゛", sizeof( sc_USBKeyEnableCharCode[us_GetCount] ) );	// comment ZeusMLK <- 平松 2012/9/5 静的解析対応 [CID29181].
			us_GetCount++;
			strncpy( sc_USBKeyEnableCharCode[us_GetCount], ( const char* )"゜", sizeof( sc_USBKeyEnableCharCode[us_GetCount] ) );	// comment ZeusMLK <- 平松 2012/9/5 静的解析対応 [CID29181].
			us_GetCount++;
		} else if( TYPE_USBKeyInput_Katakana == pc_PanelManager->getUSBKeyBoardCountry() ) {
			if( TYPE_USBKeyInput_Zenkaku == pc_PanelManager->getUSBKeyBoardZenkakuHankaku() ) {
				strncpy( sc_USBKeyEnableCharCode[us_GetCount], ( const char* )"゛", sizeof( sc_USBKeyEnableCharCode[us_GetCount] ) );	// comment ZeusMLK <- 平松 2012/9/5 静的解析対応 [CID29181].
				us_GetCount++;
				strncpy( sc_USBKeyEnableCharCode[us_GetCount], ( const char* )"゜", sizeof( sc_USBKeyEnableCharCode[us_GetCount] ) );	// comment ZeusMLK <- 平松 2012/9/5 静的解析対応 [CID29181].
				us_GetCount++;
			}
		}
	}
}

