typedef uchar PCGD_CapsLock;
#define PCGD_CapsLock_OFF		0
#define PCGD_CapsLock_ON		1
#define PCGD_CapsLock_SIZE		2

static const TYPE_USBKeyBoardMode	tbl_USBKeyBoardMode[][PCGD_CapsLock_SIZE] = {
	{	TYPE_USBKeyBoardMode_FrenchSmall,		TYPE_USBKeyBoardMode_FrenchBig		},
	{	TYPE_USBKeyBoardMode_ItalianSmall,		TYPE_USBKeyBoardMode_ItalianBig		},
	{	TYPE_USBKeyBoardMode_GermanSmall,		TYPE_USBKeyBoardMode_GermanBig		},
	{	TYPE_USBKeyBoardMode_SpanishSmall,		TYPE_USBKeyBoardMode_SpanishBig		},
	{	TYPE_USBKeyBoardMode_EnglishUKSmall,	TYPE_USBKeyBoardMode_EnglishUKBig	},
	{	TYPE_USBKeyBoardMode_DanishSmall,		TYPE_USBKeyBoardMode_DanishBig		},
	{	TYPE_USBKeyBoardMode_DutchSmall,		TYPE_USBKeyBoardMode_DutchBig		},
	{	TYPE_USBKeyBoardMode_PortugueseSmall,	TYPE_USBKeyBoardMode_PortugueseBig	},
	{	TYPE_USBKeyBoardMode_SwedishSmall,		TYPE_USBKeyBoardMode_SwedishBig		},
	{	TYPE_USBKeyBoardMode_NorwegianSmall,	TYPE_USBKeyBoardMode_NorwegianBig	},
	{	TYPE_USBKeyBoardMode_FinnishSmall,		TYPE_USBKeyBoardMode_FinnishBig		},
	{	TYPE_USBKeyBoardMode_CzechSmall,		TYPE_USBKeyBoardMode_CzechBig		},
	{	TYPE_USBKeyBoardMode_HangarianSmall,	TYPE_USBKeyBoardMode_HangarianBig	},
	{	TYPE_USBKeyBoardMode_GreekSmall,		TYPE_USBKeyBoardMode_GreekBig		},
	{	TYPE_USBKeyBoardMode_TurkishSmall,		TYPE_USBKeyBoardMode_TurkishBig		},
	{	TYPE_USBKeyBoardMode_RussianSmall,		TYPE_USBKeyBoardMode_RussianBig		},
	{	TYPE_USBKeyBoardMode_CroatianSmall,		TYPE_USBKeyBoardMode_CroatianBig	},
	{	TYPE_USBKeyBoardMode_UkrainianSmall,	TYPE_USBKeyBoardMode_UkrainianBig	},
	{	TYPE_USBKeyBoardMode_RomanianSmall,		TYPE_USBKeyBoardMode_RomanianBig	},
	{	TYPE_USBKeyBoardMode_SlovakSmall,		TYPE_USBKeyBoardMode_SlovakBig		},
	{	TYPE_USBKeyBoardMode_ArabicSmall,		TYPE_USBKeyBoardMode_ArabicBig		},
	{	TYPE_USBKeyBoardMode_ThaiSmall,			TYPE_USBKeyBoardMode_ThaiBig		},
	{	TYPE_USBKeyBoardMode_MalaysiaSmall,		TYPE_USBKeyBoardMode_MalaysiaBig	},
	{	TYPE_USBKeyBoardMode_PolishSmall,		TYPE_USBKeyBoardMode_PolishBig		},
	{	TYPE_USBKeyBoardMode_LithuaniaSmall,	TYPE_USBKeyBoardMode_LithuaniaBig	},
	{	TYPE_USBKeyBoardMode_CatalanSmall,		TYPE_USBKeyBoardMode_CatalanBig		},
	{	TYPE_USBKeyBoardMode_SloveneSmall,		TYPE_USBKeyBoardMode_SloveneBig		},
	{	TYPE_USBKeyBoardMode_BulgarianSmall,	TYPE_USBKeyBoardMode_BulgarianBig	},	// ブルガリア語.
	{	TYPE_USBKeyBoardMode_BasqueSmall,		TYPE_USBKeyBoardMode_BasqueBig		},	// バスク語.
// comment 2015/06/15 OPS1-Sky入江 [ZeusS_ZX0][RQ-405] パネルUIのヘブライ語対応.
	{	TYPE_USBKeyBoardMode_HebrewSmall,		TYPE_USBKeyBoardMode_HebrewBig		},	// ヘブライ語.
};
static const uchar tbl_USBKeyBoardMode_MAXSIZE = ( sizeof( tbl_USBKeyBoardMode ) / sizeof( tbl_USBKeyBoardMode[0] ) );

void PLBC_GeneralKeybord::registUSBKeyEnableCharCodeFromMSbin()	{

	PDPC_KeyMapManager* pc_KeyMapManager = PDPC_KeyMapManager::newInstance();
	if( False == pc_KeyMapManager->isUSBKeyBoardKeyMapFromMSbin( PnlComGetUSBKeyboardLanguage() ) )	{
		return;
	}

	PMGC_PanelManager* pc_PanelManager = PMGC_PanelManager::newInstance();
	TYPE_USBKeyBoardMode e_USBKeyBoardMode = pc_PanelManager->getUSBKeyBoardMode();
	PMGS_PnlMgrChangeCharCode* tbl_PnlMgrChangeCharCode = NULL;
	int32_t i32_PnlMgrChangeCharCodeSize = 0;

	for( uchar uc_TblPoint = 0; tbl_USBKeyBoardMode_MAXSIZE > uc_TblPoint; uc_TblPoint++ )	{
		if( ( e_USBKeyBoardMode == tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_OFF] )
		    || ( e_USBKeyBoardMode == tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_ON] ) )	{
			break;
		}
	}
	// 有効文字コード格納配列へ文字コードを格納する.
	switch( e_USBKeyBoardMode ) {
		case TYPE_USBKeyBoardMode_EnglishHalfSmall:				//	英数記（半）小文字.
		case TYPE_USBKeyBoardMode_FrenchSmall_OnlyASCII:		// フランス小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_ItalianSmall_OnlyASCII:		// イタリア小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_GermanSmall_OnlyASCII:		// ドイツ小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_SpanishSmall_OnlyASCII:		// スペイン小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_EnglishUKSmall_OnlyASCII:		// イギリス英語小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_DanishSmall_OnlyASCII:		// デンマーク小文字.
		case TYPE_USBKeyBoardMode_DutchSmall_OnlyASCII:			// オランダ小文字.
		case TYPE_USBKeyBoardMode_PortugueseSmall_OnlyASCII:	// ポルトガル小文字.
		case TYPE_USBKeyBoardMode_SwedishSmall_OnlyASCII:		// スウェーデン小文字.
		case TYPE_USBKeyBoardMode_NorwegianSmall_OnlyASCII:		// ノルウェー小文字.
		case TYPE_USBKeyBoardMode_FinnishSmall_OnlyASCII:		// フィンランド小文字.
		case TYPE_USBKeyBoardMode_CzechSmall_OnlyASCII:			// チェコ小文字.
		case TYPE_USBKeyBoardMode_HangarianSmall_OnlyASCII:		// ハンガリー小文字.
		case TYPE_USBKeyBoardMode_GreekSmall_OnlyASCII:			// ギリシア小文字.
		case TYPE_USBKeyBoardMode_TurkishSmall_OnlyASCII:		// トルコ小文字.
		case TYPE_USBKeyBoardMode_RussianSmall_OnlyASCII:		// ロシア小文字.
		case TYPE_USBKeyBoardMode_CroatianSmall_OnlyASCII:		// クロアチア小文字.
		case TYPE_USBKeyBoardMode_UkrainianSmall_OnlyASCII:		// ウクライナ小文字.
		case TYPE_USBKeyBoardMode_RomanianSmall_OnlyASCII:		// ルーマニア小文字.
		case TYPE_USBKeyBoardMode_SlovakSmall_OnlyASCII:		// スロベキア小文字.
		case TYPE_USBKeyBoardMode_ArabicSmall_OnlyASCII:		// アラビア小文字.
		case TYPE_USBKeyBoardMode_ThaiSmall_OnlyASCII:			// タイ小文字.
		case TYPE_USBKeyBoardMode_MalaysiaSmall_OnlyASCII:		// マレーシア小文字.
		case TYPE_USBKeyBoardMode_PolishSmall_OnlyASCII:		// ポーランド小文字.
		case TYPE_USBKeyBoardMode_LithuaniaSmall_OnlyASCII:		// リトアニア小文字.
		case TYPE_USBKeyBoardMode_CatalanSmall_OnlyASCII:		// カタロニア小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_SloveneSmall_OnlyASCII:		// スロベニア小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_BulgarianSmall_OnlyASCII:		// ブルガリア小文字_英数記のみ.
		case TYPE_USBKeyBoardMode_BasqueSmall_OnlyASCII:		// バスク小文字_英数記のみ.
			// 英数記(半角)入力キーMAP取得.
			if( True == pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, TYPE_USBKeyBoardMode_EnglishHalfSmall ) ) {
				// 英数記(半角)入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, TYPE_USBKeyBoardMode_EnglishHalfSmall );
			}
			else {	// キーマップなしの場合、デフォルトキーMAP から取得.
				registCharCodeMsgBinEnglish( False );					// 英数(半)小文字.
				if( True == bl_Key_KeybordcomShift ) {
					registCharCodeMsgBinEnglish( True );				// 英数(半)大文字.
				}
			}
			break;
		case TYPE_USBKeyBoardMode_EnglishHalfBig:	//	英数記（半）大文字.
		case TYPE_USBKeyBoardMode_FrenchBig_OnlyASCII:		// フランス大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_ItalianBig_OnlyASCII:		// イタリア大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_GermanBig_OnlyASCII:		// ドイツ大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_SpanishBig_OnlyASCII:		// スペイン大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_EnglishUKBig_OnlyASCII:	// イギリス英語大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_DanishBig_OnlyASCII:		// デンマーク大文字.
		case TYPE_USBKeyBoardMode_DutchBig_OnlyASCII:		// オランダ大文字.
		case TYPE_USBKeyBoardMode_PortugueseBig_OnlyASCII:	// ポルトガル大文字.
		case TYPE_USBKeyBoardMode_SwedishBig_OnlyASCII:		// スウェーデン大文字.
		case TYPE_USBKeyBoardMode_NorwegianBig_OnlyASCII:	// ノルウェー大文字.
		case TYPE_USBKeyBoardMode_FinnishBig_OnlyASCII:		// フィンランド大文字.
		case TYPE_USBKeyBoardMode_CzechBig_OnlyASCII:		// チェコ大文字.
		case TYPE_USBKeyBoardMode_HangarianBig_OnlyASCII:	// ハンガリー大文字.
		case TYPE_USBKeyBoardMode_GreekBig_OnlyASCII:		// ギリシア大文字.
		case TYPE_USBKeyBoardMode_TurkishBig_OnlyASCII:		// トルコ大文字.
		case TYPE_USBKeyBoardMode_RussianBig_OnlyASCII:		// ロシア大文字.
		case TYPE_USBKeyBoardMode_CroatianBig_OnlyASCII:	// クロアチア大文字.
		case TYPE_USBKeyBoardMode_UkrainianBig_OnlyASCII:	// ウクライナ大文字.
		case TYPE_USBKeyBoardMode_RomanianBig_OnlyASCII:	// ルーマニア大文字.
		case TYPE_USBKeyBoardMode_SlovakBig_OnlyASCII:		// スロベキア大文字.
		case TYPE_USBKeyBoardMode_ArabicBig_OnlyASCII:		// アラビア大文字.
		case TYPE_USBKeyBoardMode_ThaiBig_OnlyASCII:		// タイ大文字.
		case TYPE_USBKeyBoardMode_MalaysiaBig_OnlyASCII:	// マレーシア大文字.
		case TYPE_USBKeyBoardMode_PolishBig_OnlyASCII:		// ポーランド大文字.
		case TYPE_USBKeyBoardMode_LithuaniaBig_OnlyASCII:	// リトアニア大文字.
		case TYPE_USBKeyBoardMode_CatalanBig_OnlyASCII:		// カタロニア大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_SloveneBig_OnlyASCII:		// スロベニア大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_BulgarianBig_OnlyASCII:	// ブルガリア大文字_英数記のみ.
		case TYPE_USBKeyBoardMode_BasqueBig_OnlyASCII:		// バスク大文字_英数記のみ.
			// 英数記(半角)入力キーMAP取得.
			if( True == pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, TYPE_USBKeyBoardMode_EnglishHalfBig ) ) {
				// 英数記(半角)入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, TYPE_USBKeyBoardMode_EnglishHalfBig );
			}
			else {	// キーマップなしの場合、デフォルトキーMAP から取得.
				registCharCodeMsgBinEnglish( True );					// 英数(半)大文字.
				if( True == bl_Key_KeybordcomShift ) {
					registCharCodeMsgBinEnglish( False );				// 英数(半)小文字.
				}
			}
			break;
		case TYPE_USBKeyBoardMode_FrenchSmall:		//	フランス語小文字.
		case TYPE_USBKeyBoardMode_ItalianSmall:		//	イタリア語小文字.
		case TYPE_USBKeyBoardMode_GermanSmall:		//	ドイツ語小文字.
		case TYPE_USBKeyBoardMode_SpanishSmall:		//	スペイン語小文字.
		case TYPE_USBKeyBoardMode_EnglishUKSmall:	// イギリス英語小文字.
		case TYPE_USBKeyBoardMode_DanishSmall:		// デンマーク小文字.
		case TYPE_USBKeyBoardMode_DutchSmall:		// オランダ小文字.
		case TYPE_USBKeyBoardMode_PortugueseSmall:	// ポルトガル小文字.
		case TYPE_USBKeyBoardMode_SwedishSmall:		// スウェーデン小文字.
		case TYPE_USBKeyBoardMode_NorwegianSmall:	// ノルウェー小文字.
		case TYPE_USBKeyBoardMode_FinnishSmall:		// フィンランド小文字.
		case TYPE_USBKeyBoardMode_CzechSmall:		// チェコ小文字.
		case TYPE_USBKeyBoardMode_HangarianSmall:	// ハンガリー小文字.
		case TYPE_USBKeyBoardMode_GreekSmall:		// ギリシア小文字.
		case TYPE_USBKeyBoardMode_TurkishSmall:		// トルコ小文字.
		case TYPE_USBKeyBoardMode_RussianSmall:		// ロシア小文字.
		case TYPE_USBKeyBoardMode_CroatianSmall:	// クロアチア小文字.
		case TYPE_USBKeyBoardMode_UkrainianSmall:	// ウクライナ小文字.
		case TYPE_USBKeyBoardMode_RomanianSmall:	// ルーマニア小文字.
		case TYPE_USBKeyBoardMode_SlovakSmall:		// スロベキア小文字.
		case TYPE_USBKeyBoardMode_ArabicSmall:		// アラビア小文字.
		case TYPE_USBKeyBoardMode_ThaiSmall:		// タイ小文字.
		case TYPE_USBKeyBoardMode_MalaysiaSmall:	// マレーシア小文字.
		case TYPE_USBKeyBoardMode_PolishSmall:		// ポーランド小文字.
		case TYPE_USBKeyBoardMode_LithuaniaSmall:	// リトアニア小文字.
		case TYPE_USBKeyBoardMode_CatalanSmall:		// カタロニア小文字.
		case TYPE_USBKeyBoardMode_SloveneSmall:		// スロベニア小文字.
		case TYPE_USBKeyBoardMode_BulgarianSmall:	// ブルガリア小文字.
		case TYPE_USBKeyBoardMode_BasqueSmall:		// バスク小文字.
			if( tbl_USBKeyBoardMode_MAXSIZE > uc_TblPoint ) {
				// ○○語キーMAP取得.
				pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_OFF] );
				// ○○語入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_OFF] );
				// ○○語CapsLockキーMAP取得.
				pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_ON] );
				// ○○語CapsLock入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_ON] );
			}
			break;
		case TYPE_USBKeyBoardMode_FrenchBig:		//	フランス語大文字.
		case TYPE_USBKeyBoardMode_ItalianBig:		//	イタリア語大文字.
		case TYPE_USBKeyBoardMode_GermanBig:		//	ドイツ語大文字.
		case TYPE_USBKeyBoardMode_SpanishBig:		//	スペイン語大文字.
		case TYPE_USBKeyBoardMode_EnglishUKBig:		// イギリス英語大文字.
		case TYPE_USBKeyBoardMode_DanishBig:		// デンマーク大文字.
		case TYPE_USBKeyBoardMode_DutchBig:			// オランダ大文字.
		case TYPE_USBKeyBoardMode_PortugueseBig:	// ポルトガル大文字.
		case TYPE_USBKeyBoardMode_SwedishBig:		// スウェーデン大文字.
		case TYPE_USBKeyBoardMode_NorwegianBig:		// ノルウェー大文字.
		case TYPE_USBKeyBoardMode_FinnishBig:		// フィンランド大文字.
		case TYPE_USBKeyBoardMode_CzechBig:			// チェコ大文字.
		case TYPE_USBKeyBoardMode_HangarianBig:		// ハンガリー大文字.
		case TYPE_USBKeyBoardMode_GreekBig:			// ギリシア大文字.
		case TYPE_USBKeyBoardMode_TurkishBig:		// トルコ大文字.
		case TYPE_USBKeyBoardMode_RussianBig:		// ロシア大文字.
		case TYPE_USBKeyBoardMode_CroatianBig:		// クロアチア大文字.
		case TYPE_USBKeyBoardMode_UkrainianBig:		// ウクライナ大文字.
		case TYPE_USBKeyBoardMode_RomanianBig:		// ルーマニア大文字.
		case TYPE_USBKeyBoardMode_SlovakBig:		// スロベキア大文字.
		case TYPE_USBKeyBoardMode_ArabicBig:		// アラビア大文字.
		case TYPE_USBKeyBoardMode_ThaiBig:			// タイ大文字.
		case TYPE_USBKeyBoardMode_MalaysiaBig:		// マレーシア大文字.
		case TYPE_USBKeyBoardMode_PolishBig:		// ポーランド大文字.
		case TYPE_USBKeyBoardMode_LithuaniaBig:		// リトアニア大文字.
		case TYPE_USBKeyBoardMode_CatalanBig:		// カタロニア大文字.
		case TYPE_USBKeyBoardMode_SloveneBig:		// スロベニア大文字.
		case TYPE_USBKeyBoardMode_BulgarianBig:		// ブルガリア大文字.
		case TYPE_USBKeyBoardMode_BasqueBig:		// バスク大文字.
			if( tbl_USBKeyBoardMode_MAXSIZE > uc_TblPoint ) {
				// ○○語CapsLockキーMAP取得.
				pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_ON] );
				// ○○語CapsLock入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_ON] );
				// ○○語キーMAP取得.
				pc_KeyMapManager->getUSBKeyMapBinary( &tbl_PnlMgrChangeCharCode, &i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_OFF] );
				// ○○語入力有効文字を登録.
				registCharCodeFromMSbin( &tbl_PnlMgrChangeCharCode, i32_PnlMgrChangeCharCodeSize, tbl_USBKeyBoardMode[uc_TblPoint][PCGD_CapsLock_OFF] );
			}
			break;
		case TYPE_USBKeyBoardMode_EnglishAllSmall:
		case TYPE_USBKeyBoardMode_EnglishAllBig:
		case TYPE_USBKeyBoardMode_Chinese:
		case TYPE_USBKeyBoardMode_Taiwanese:
		case TYPE_USBKeyBoardMode_Korean:
		case TYPE_USBKeyBoardMode_KoreanShift:
		case TYPE_USBKeyBoardMode_Korean_ConsonantVowel:
		case TYPE_USBKeyBoardMode_Hiragana:
		case TYPE_USBKeyBoardMode_KatakanaHalf:
		case TYPE_USBKeyBoardMode_KatakanaAll:
			// これらがカスタマイズされる事は無い.
			break;
		default: break;
	}
}

//============================================================================================
//概要    ：画面毎の有効文字コードを配列へ格納する(カスタマイズキーボード用).
//戻り値  ：なし
//備考    ：tbl_KeyMAPCharCodeFromMSbin で取得する文字コードはUCS2（2byte固定文字）.
//作成者  ：12細川
//レビュー：未実施
//============================================================================================
void PLBC_GeneralKeybord::registCharCodeFromMSbin( PMGS_PnlMgrChangeCharCode** tbl_KeyMAPCharCodeFromMSbin, int32_t sl_KeyMAPCharCodeFromMSbinSize, TYPE_USBKeyBoardMode e_USBKeyBoardMode )	{

	Bool b_Hit = False;
	uchar uc_KeyTblCnt = 0;
	ushort us_i = 0;

	// 英数記の入力有効文字登録.
	if( TYPE_USBKeyBoardMode_EnglishHalfSmall == e_USBKeyBoardMode || TYPE_USBKeyBoardMode_EnglishHalfBig == e_USBKeyBoardMode )	{
		// 有効文字コードを取得する.
		for( uc_KeyTblCnt = 0; uc_KeyTblCnt < sl_KeyMAPCharCodeFromMSbinSize; uc_KeyTblCnt++ )		{
			// 通常入力.
			if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode[0] )
			    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode[1] ) )	{
				b_Hit = False;
				// すでに登録済みか判断する.
				for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
					if( us_GetCount <= us_i )	{
						break;	// 登録文字格納数まで達した場合（未登録の場合）.
					}
					if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode, TYPD_CharCode ) )	{
						b_Hit = True;	// 登録済み.
						break;
					}
				}
				if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
					return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
				}
				if( False == b_Hit )	{
					// 登録する.
					memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode, TYPD_CharCode );
					us_GetCount++;
				}
			}
			if( True == bl_Key_KeybordcomShift )	{
				// 通常入力（Shift同時押し）.
				if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift[0] )
				    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift[1] ) )	{
					b_Hit = False;
					// すでに登録済みか判断する.
					for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
						if( us_GetCount <= us_i )	{
							break;	// 登録文字格納数まで達した場合（未登録の場合）.
						}
						if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift, TYPD_CharCode ) )	{
							b_Hit = True;	// 登録済み.
							break;
						}
					}
					if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
						return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
					}
					// 未登録の場合.
					if( False == b_Hit )	{
						memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift, TYPD_CharCode );
						us_GetCount++;
					}
				}
			}
		}
		// ○○語の入力有効文字登録.
	} else {
		for( uc_KeyTblCnt = 0; uc_KeyTblCnt < sl_KeyMAPCharCodeFromMSbinSize; uc_KeyTblCnt++ )		{
			// ○○語通常.
			if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode[0] )
			    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode[1] ) )	{
				b_Hit = False;
				// すでに登録済みか判断する.
				for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
					if( us_GetCount <= us_i )	{
						break;	// 登録文字格納数まで達した場合（未登録の場合）.
					}
					if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode, TYPD_CharCode ) )	{
						b_Hit = True;	// 登録済み.
						break;
					}
				}
				if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
					return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
				}
				// 未登録の場合.
				if( False == b_Hit )	{
					// 登録する.
					memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCode, TYPD_CharCode );
					us_GetCount++;
				}
			}
			if( True == bl_Key_KeybordcomShift )	{
				// ○○語（Shift同時押し）.
				if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift[0] )
				    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift[1] ) )	{
					b_Hit = False;
					// すでに登録済みか判断する.
					for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
						if( us_GetCount <= us_i )	{
							break;	// 登録文字格納数まで達した場合（未登録の場合）.
						}
						if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift, TYPD_CharCode ) )	{
							b_Hit = True;	// 登録済み.
							break;
						}
					}
					if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
						return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
					}
					// 未登録の場合.
					if( False == b_Hit )	{
						memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeShift, TYPD_CharCode );
						us_GetCount++;
					}
				}
			}
			if( True == bl_Key_KeybordcomAltGr )	{
				// ○○語（Alt同時押し）.
				if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAlt[0] )
				    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAlt[1] ) )	{
					b_Hit = False;
					// すでに登録済みか判断する.
					for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
						if( us_GetCount <= us_i )	{
							break;	// 登録文字格納数まで達した場合（未登録の場合）.
						}
						if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAlt, TYPD_CharCode ) )	{
							b_Hit = True;	// 登録済み.
							break;
						}
					}
					if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
						return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
					}
					// 未登録の場合.
					if( False == b_Hit )	{
						memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAlt, TYPD_CharCode );
						us_GetCount++;
					}
				}
			}
			if( True == bl_Key_KeybordcomShift && True == bl_Key_KeybordcomAltGr )	{
				// ○○語（Shift + Alt同時押し）.
				if( ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAltShift[0] )
				    || ( 0x00 != ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAltShift[1] ) )	{
					b_Hit = False;
					// すでに登録済みか判断する.
					for( us_i = 0; TYPD_USBKeyEnableCCodeMAX > us_i ; us_i++ )	{
						if( us_GetCount <= us_i )	{
							break;	// 登録文字格納数まで達した場合（未登録の場合）.
						}
						if( 0 == memcmp( sc_USBKeyEnableCharCode[us_i], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAltShift, TYPD_CharCode ) )	{
							b_Hit = True;	// 登録済み.
							break;
						}
					}
					if( TYPD_USBKeyEnableCCodeMAX <= us_i )	{
						return;	// 格納領域全てに文字コードが登録されている場合(本来ありえない).
					}
					// 未登録の場合.
					if( False == b_Hit )	{
						memcpy( sc_USBKeyEnableCharCode[us_GetCount], ( ( *tbl_KeyMAPCharCodeFromMSbin ) + uc_KeyTblCnt )->sc_CharCodeAltShift, TYPD_CharCode );
						us_GetCount++;
					}
				}
			}
		}
	}
}

//============================================================================================
//概要    ：画面毎の有効文字コードを配列へ格納する(カスタマイズキーボード英数用).
//戻り値  ：なし
//備考    ：デフォルトキーマップの英数をカスタマイズキーマップのタイプに合わせる.
//作成者  ：
//レビュー：
//============================================================================================
void PLBC_GeneralKeybord::registCharCodeMsgBinEnglish( Bool bl_Captal )
{

	KeybordType e_KeyBordType = PLBD_KBT_USAscii;				// 英数 小文字.

	if( True == bl_Captal ) {
		e_KeyBordType = PLBD_KBT_USAsciiShift;
	}

	//有効文字コードを取得する.
	for( uchar uc_KeyTblCnt=0; uc_KeyTblCnt < PLBD_KeyNumMax; uc_KeyTblCnt++ ) {
		//キーのテキストが""の場合は、文字コードを取得しない.
		if( NULL != keyTbl[e_KeyBordType].keyInfo[uc_KeyTblCnt].sc_KeyTopChar[0] ) {
			memcpy( &sc_USBKeyEnableCharCode[us_GetCount][1], ( const char* )keyTbl[e_KeyBordType].keyInfo[uc_KeyTblCnt].sc_KeyTopChar, TYPD_CharCode - 1 );
			us_GetCount++;
		}
	}
}

