//================================================================================================.
//概要	 ：IME文字列を表示用バッファへのコピー.
//引数	 ：char*	文字列データ.
//		 ：char*	文字列データのコピー先.
//戻り値 ：なし.
//備考	 ：最大入力バイト数が取れない場合は、最大入力文字サイズでチェック処理を行う.
//		 ：※既存でコールしている、procFilteringCommittedTxt() / procFilteringComposingTxt()以外からはコールしないでください！！.
//作成者 ：OPS1川手.
//================================================================================================.
void PLBC_GeneralKeybord::copyIMEStringToDisplayBuffer( char* psc_SrcStr, char* psc_DstStr )
{
	PCGC_SlideTextMgr* pc_Mgr = m_pc_SlideTxtMgr;
	if( ( NULL == psc_SrcStr ) || ( NULL == psc_DstStr ) || ( NULL == pc_Mgr ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	PLBC_CUtf8	c_Utf8( psc_SrcStr );					// UTF8の文字列操作用クラスインスタンス.
	char		sc_OneBuf[8] = {0};						// UTF8の1文字分のバッファ.
	ushort		us_OneByteNum = 0;						// UTF8の1文字分のバイト数.
	char*		psc_TempAdd = psc_DstStr;
	PNLS_TextCnt st_TextCnt;							// 文字列のサイズカウンタ.

	memset( &st_TextCnt, 0, sizeof( PNLS_TextCnt ) );

	// 全実データサイズをチェック.
	c_Utf8.GetFirst( sc_OneBuf, &us_OneByteNum );		// 最初の1文字分のUTF8文字取得.
	while( 0 != us_OneByteNum ) {						// 高速化のため、必須な処理以外極力省略すること.
		// コピー処理開始.
		memcpy( psc_TempAdd, sc_OneBuf, us_OneByteNum );
		psc_TempAdd += us_OneByteNum;					// データサイズ分移動.

		// 次のチェック用前処理.
		c_Utf8.GetNext( sc_OneBuf, &us_OneByteNum );	// 1文字分のUTF8文字取得.
		sc_OneBuf[us_OneByteNum] = '\0';
	}
	*psc_TempAdd = '\0';								// 終端を0埋め.
}

//================================================================================================.
//概要	 ：確定文字列のフィルタリング処理.
//引数	 ：char*	バッファアドレス.
//		 ：short	最大文字数.
//		 ：short	最大バッファサイズ.
//戻り値 ：Bool		成否.
//備考	 ：バッファに対する文字列チェック処理の結果、NGだった場合は何も処理しない.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::procFilteringCommittedTxt( char* psc_Buf, const short ss_MaxCnt, const short ss_MaxSize )
{
	// エラーチェック処理.
	Bool bl_Error = False;
	if( NULL == psc_Buf ) {
		bl_Error = True;
	} else {
		if( 0 < ss_MaxCnt ) {								// UTF8の文字数が0より大きい数値で指定されていれば.
			if( PNLD_IME_CHARSIZE_MAX < ss_MaxCnt ) {		// 文字数チェック.
				bl_Error = True;
			}
		} else {											// UTF8の文字数が指定されていない場合.
			if( APID_IMETxtBufSize - 1 < ss_MaxSize ) {	// バッファサイズチェック.
				bl_Error = True;
			}
		}
	}
	if( True == bl_Error ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	// 更新処理 .
	Bool bl_Filtered = filterCommittedTxt( m_st_IMETxtInfo.m_sc_CommittedTxt, &( m_st_IMETxtInfo.m_sl_CursorPos ) );

	if( True == bl_Filtered ) {
		if( NULL != m_pc_IMEMgr ) {
			m_pc_IMEMgr->reqSendTxt();							// IME文字列の更新要求.
		}
	}
	copyIMEStringToDisplayBuffer( m_st_IMETxtInfo.m_sc_CommittedTxt, psc_Buf );
	return True;
}

//================================================================================================.
//概要	 ：未確定文字列のフィルタリング処理.
//引数	 ：char*	バッファアドレス.
//		 ：short	最大文字数.
//		 ：short	最大バッファサイズ.
//戻り値 ：Bool		成否.
//備考	 ：バッファに対する文字列チェック処理の結果、NGだった場合は何も処理しない.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::procFilteringComposingTxt( char* psc_Buf, const short ss_MaxCnt, const short ss_MaxSize )
{
	// チェック処理.
	Bool bl_Error = False;
	if( NULL == psc_Buf ) {
		bl_Error = True;
	} else {
		if( 0 < ss_MaxCnt ) {								// UTF8の文字数が0より大きい数値で指定されていれば.
			if( PNLD_IME_CHARSIZE_MAX < ss_MaxCnt ) {		// 文字数チェック.
				bl_Error = True;
			}
		} else {											// UTF8の文字数が指定されていない場合.
			if( APID_IMETxtBufSize - 1 < ss_MaxSize ) {	// バッファサイズチェック.
				bl_Error = True;
			}
		}
	}
	if( True == bl_Error ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	filterComposingTxt( m_st_IMETxtInfo.m_sc_ComposingTxt, ss_MaxCnt, ss_MaxSize );
	copyIMEStringToDisplayBuffer( m_st_IMETxtInfo.m_sc_ComposingTxt, psc_Buf );
	return True;
}

