//================================================================================================.
//概要	 ：使用禁止文字列の有無.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//		 ：ss_Ptn	パターン.
//戻り値 ：Bool	使用禁止文字列があるかどうか.
//備考	 ：.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::isDisableKeyCode( const uchar* puc_Str, const ushort us_Size, const short ss_Ptn )
{
	char sc_DisableChar[4] = {0};		// 3バイトコードのチェックが最大のため、バッファサイズは4に指定.
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return True;					// 不要な文字コードとして、禁止文字列検出させる.
	}
	Bool bl_Ret = False;
	if( KC_DisableKeyPatternNon != ss_Ptn ) {
		const Sc_SetDisableKeyCodeType* p_SetKey = &sc_SetDisableKeyCode[ss_Ptn];
		short ss_Count = 0;
		for( ss_Count = 0; ss_Count < p_SetKey->ss_UseKeyCnt; ss_Count++ ) {
			if( 0x7F < p_SetKey->sc_CharCode[ss_Count] ) {			// 文字コードが0x7Fを越える場合は特殊文字のため変換が必要.
				if( 0x80 == p_SetKey->sc_CharCode[ss_Count] ) {	// ユーロ記号の場合.
					sc_DisableChar[0] = (char)0xE2;
					sc_DisableChar[1] = (char)0x82;
					sc_DisableChar[2] = (char)0xAC;
					sc_DisableChar[3] = '\0';
				}
			} else {
				sc_DisableChar[0] = p_SetKey->sc_CharCode[ss_Count];
				sc_DisableChar[1] = '\0';
			}

			if( 0 == strncmp( ( char* )puc_Str, sc_DisableChar, us_Size ) ) {
				bl_Ret = True;
				break;
			}
		}
	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：ユーロ記号の文字コードかどうかを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool ユーロ記号かどうか.
//備考	 ：UTF-8のユーロ記号かどうかをチェックする.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::isEuroCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}
	if( 3 == us_Size ) {
		// UTF8のユーロ記号チェック(0xE2,0x82,0xAC).
		if( ( 0xE2 == puc_Str[0] ) && ( 0x82 == puc_Str[1] ) && ( 0xAC == puc_Str[2] ) ) {
			bl_Ret = True;
		}
	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：5ヶ国語コードかどうかを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool	5ヶ国語コードかどうか.
//備考	 ：キーボード種別からUTF-8の5ヶ国語コードかどうかをチェックする.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::is5CountryCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}
	if( True == is5Country() ) {		// ５ヵ国語キーボード.
		// バイト数に応じてフィルタリングを判定する.
		if( 1 == us_Size ) {
			if( 0 != isascii( puc_Str[0] ) ) {
				bl_Ret = True;			// 0でなければASCIIコード.
			}
		} else if( 2 == us_Size ) {
			// UTF8の5ヶ国語コードチェック( 2byte:0xC2A1～0xC2BF/0xC380～0xC3BF ).
			if( 0xC2 == puc_Str[0] ) {
				if( ( 0xA1 <= puc_Str[1] ) && ( 0xBF >= puc_Str[1] ) ) {
					bl_Ret = True;
				}
			} else if( 0xC3 == puc_Str[0] ) {
				if( ( 0x80 <= puc_Str[1] ) && ( 0xBF >= puc_Str[1] ) ) {
					bl_Ret = True;
				}
			}
		} else if( 3 == us_Size ) {
			if( True == isEuroCode( puc_Str, us_Size ) ) {
				bl_Ret = True;
			}
		}
	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：9ヶ国語コードかどうかを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool	9ヶ国語コードかどうか.
//備考	 ：キーボード種別からUTF-8の9ヶ国語コードかどうかをチェックする.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::is9CountryCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}
	if( True == is9Country() ) {
		bl_Ret = True;
	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：アルファベットの文字コードかどうかを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool	アルファベットの文字コードかどうか.
//備考	 ：アルファベットの文字コードかどうかをチェックする.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::isAlphabetCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}
	// 下記記載の文字コード以外はフィルタリングする.
	// 1byte:0x00～0x7F.
	if( 1 == us_Size ) {
		if( 0 != isascii( puc_Str[0] ) ) {
			bl_Ret = True;			// 0でなければASCIIコード.
		}
	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：振り仮名入力状態で入力可能な文字かを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool	振り仮名入力状態での受付け可否.
//備考	 ：.
//作成者 ：OPS1本橋.
//================================================================================================.
Bool PLBC_GeneralKeybord::isKanaModeCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}

	// 下記記載の文字コード以外はフィルタリングする.
	// 1byte:0x00～0x7F.
	if( 1 == us_Size ) {
		if( 0 != isascii( puc_Str[0] ) ) {
			bl_Ret = True;			// 0でなければASCIIコード.
		}
		// 3byte:0xE38180～0xE381BF、0xE38280～0xE3829F(ひらがな).
	} else if( 3 == us_Size ) {
		if( 0xE3 == puc_Str[0] ) {
			if( 0x81 == puc_Str[1] ) {
				if( ( 0x80 <= puc_Str[2] ) && ( 0xBF >= puc_Str[2] ) ) {
					bl_Ret = True;
				}
			} else if( 0x82 == puc_Str[1] ) {
				if( ( 0x80 <= puc_Str[2] ) && ( 0x9F >= puc_Str[2] ) ) {
					bl_Ret = True;
				}
			}
		}
	}

	return bl_Ret;
}

// comment [ZeusS_ZX0] 2016/1/29 Sky西場 CQ523706 Keyboard Linkで入力すると「■■」が表示される.
//================================================================================================.
//概要	 ：異体字セレクタの文字コードかどうかを判別.
//引数	 ：puc_Str	文字.
//		 ：us_Size	文字サイズ.
//戻り値 ：Bool	異体字セレクタの文字コードかどうか.
//備考	 ：異体字セレクタの文字コードかどうかをチェックする.
//備考	 ：.
//作成者 ：OPS2西場.
//================================================================================================.
Bool PLBC_GeneralKeybord::isVariationSelectorCode( const uchar* puc_Str, const ushort us_Size )
{
	Bool bl_Ret = False;
	if( NULL == puc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_Ret;
	}

	// 下記記載の文字コード以外はフィルタリングする.
	// 3byte:0xE1A08B～0xE1A08D、0xEFB880～0xEFB88F.
	if( 3 == us_Size ) {
		if( ( 0xE1 == puc_Str[0] ) && ( 0xA0 == puc_Str[1] ) ) {
			if( ( 0x8B <= puc_Str[2] ) && ( 0x8D >= puc_Str[2] ) ) {
				bl_Ret = True;
			}
		} else if( ( 0xEF == puc_Str[0] ) && ( 0xB8 == puc_Str[1] ) ) {
			if( ( 0x80 <= puc_Str[2] ) && ( 0x8F >= puc_Str[2] ) ) {
				bl_Ret = True;
			}
		}
		// 4byte:0xF3A08480～0xF3A084BF、0xF3A08580～0xF3A085BF、0xF3A08680～0xF3A086BF、0xF3A08780～0xF3A087AF.
	} else if( 4 == us_Size ) {
		if( ( 0xF3 == puc_Str[0] ) && ( 0xA0 == puc_Str[1] ) ) {
			if( ( 0x84 <= puc_Str[2] ) && ( 0x86 >= puc_Str[2] ) ) {
				if( ( 0x80 <= puc_Str[3] ) && ( 0xBF >= puc_Str[3] ) ) {
					bl_Ret = True;
				}
			}else if( 0x87 == puc_Str[2] ) {
				if( ( 0x80 <= puc_Str[3] ) && ( 0xAF >= puc_Str[3] ) ) {
					bl_Ret = True;
				}
			}
		}
	}

	return bl_Ret;
}

