//================================================================================================.
//概要	 ：確定文字列のフィルター処理(確定文字列).
//引数	 ：char*	文字列.
//		 ：int32_t*	カーソル位置.
//戻り値 ：True：フィルタ処理実行 False：フィルタ処理無し.
//備考	 ：最大文字列サイズ、または文字数でのチェックが必要.
//作成者 ：OPS1川手.
//		   フィルタする文字列がカーソル位置の前後に依存するため、カーソル位置の制御を本関数に追加.
//================================================================================================.
Bool PLBC_GeneralKeybord::filterCommittedTxt( char* psc_SrcStr, int32_t* psl_Pos )
{
	PCGC_SlideTextMgr* pc_Mgr = m_pc_SlideTxtMgr;
	if( ( NULL == psc_SrcStr ) || ( NULL == psl_Pos ) || ( NULL == pc_Mgr ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	Bool		bl_Ret = False;							// フィルタの有無.
	int32_t		i32_CurrentPos = *psl_Pos;				// 現在のカーソル位置.
	PLBC_CUtf8	c_Utf8( psc_SrcStr );					// UTF8の文字列操作用クラスインスタンス.
	uchar		uc_OneBuf[8] = {0};						// UTF8の1文字分のバッファ.
	ushort		us_OneByteNum = 0;						// UTF8の1文字分のバイト数.
	char*		psc_TempAdd = psc_SrcStr;
	PNLS_TextCnt st_TextCnt;							// 文字列のサイズカウンタ.

	memset( &st_TextCnt, 0, sizeof( PNLS_TextCnt ) );

	// 全実データサイズをチェック.
	c_Utf8.GetFirst( ( char* )uc_OneBuf, &us_OneByteNum );		// 最初の1文字分のUTF8文字取得.
	while( 0 != us_OneByteNum ) {						// 高速化のため、必須な処理以外極力省略すること.
		// comment [ZeusS_ZX0] 2016/1/29 Sky西場 CQ523706 Keyboard Linkで入力すると「■■」が表示される.
		uchar	uc_OneBufTemp[8] = {0};		// UTF8の1文字分のバッファ(変換前のデータ).
		ushort	us_OneByteNumTemp = 0;		// UTF8の1文字分のバイト数(変換前のデータ).
		// 異体字セレクタ判定のため、変換前のデータを保存する.
		memcpy( uc_OneBufTemp, uc_OneBuf, sizeof( uc_OneBufTemp ) );
		us_OneByteNumTemp = us_OneByteNum;

// comment 2015/11/20 OPS1-Sky石賀 [MinervaSBK][CQ521916] bizhubRA KeyboardLinkから送信された確定文字列に3バイトを越える文字が含まれる場合に対応.
// comment 2023/09/26 Sky東島 [IT6_2.3][OP_BTS-44893].
//		if ( 3 < us_OneByteNum ) {			// 3バイトを越える文字は現在使用不可のため"■"に置き換える.
		if ( PNLD_Keybord_MaxBytesOneChara_UTF8 < us_OneByteNum ) {			// サポート対象のバイトを越える文字は"■"に置き換える.
			uc_OneBuf[0] = 0xE2;
			uc_OneBuf[1] = 0x96;
			uc_OneBuf[2] = 0xA0;
			uc_OneBuf[3] = '\0';
			us_OneByteNum = 3;
			bl_Ret = True;
		}
		// フィルタチェック(キーボード種別に該当する文字コードであればフィルタしない).
		Bool	bl_Filter = True;
		if( True == is9Country() ) {									// ９ヵ国語キーボード.
			if( True == is9CountryCode( uc_OneBuf, us_OneByteNum ) ) {
				bl_Filter = False;
			}
		} else if( True == is5Country() ) {							// ５ヵ国語キーボード.
			if( True == is5CountryCode( uc_OneBuf, us_OneByteNum ) ) {
				bl_Filter = False;
			}
		} else {														// アルファベットキーボード.
			if( True == isAlphabetCode( uc_OneBuf, us_OneByteNum ) ) {
				bl_Filter = False;
			}
		}

		// 振り仮名入力状態であればフィルタするかを判断.
		if( True == getIMEKanaMode() ) {
			if( False == isKanaModeCode( uc_OneBuf, us_OneByteNum ) ) {
				bl_Filter = True;
			}
		}

		// 画面指定の受付禁止文字であればフィルタする.
		if( True == isDisableKeyCode( uc_OneBuf, us_OneByteNum, ss_DisableKeyPattern ) ) {
			bl_Filter = True;
		}

		// comment [ZeusS_ZX0] 2016/1/29 Sky西場 CQ523706 Keyboard Linkで入力すると「■■」が表示される.
		// 異体字セレクタであればフィルタする(変換前のデータで判定する).
		if( True == isVariationSelectorCode( uc_OneBufTemp, us_OneByteNumTemp ) ) {
			bl_Filter = True;
		}

		if( False == bl_Filter ) {
			if( False == pc_Mgr->insertCharInTextCnt( ( char* )uc_OneBuf, &st_TextCnt ) ) {		// サイズの挿入処理に失敗した場合は.
				bl_Ret = True;															// フィルタ発生.
				if( st_TextCnt.us_Num < i32_CurrentPos ) {								// サイズオーバーするので、最大値となるカーソル位置より大きい場合.
					i32_CurrentPos = st_TextCnt.us_Num;									// はみ出す場合は終端を指すようにする.
				}
				break;																	// 終了.
			}
			// コピー処理開始.
			if( True == bl_Ret ) {													// フィルタ発生済みの場合は
				memcpy( psc_TempAdd, uc_OneBuf, us_OneByteNum );					// 文字列のコピーをしていく.
			}
			psc_TempAdd += us_OneByteNum;
		} else {
			bl_Ret = True;								// フィルタ発生.
			if( st_TextCnt.us_Num <= i32_CurrentPos ) {	// 現在のカーソル位置以下の場所をフィルタする場合.
				i32_CurrentPos--;						// カーソル位置をひとつずらす
			}
		}

		// 次のチェック用前処理.
		c_Utf8.GetNext( ( char* )uc_OneBuf, &us_OneByteNum );	// 1文字分のUTF8文字取得.
		uc_OneBuf[us_OneByteNum] = '\0';
	}
	if( True == bl_Ret ) {								// フィルタの有無.
		*psc_TempAdd = '\0';							// 終端コードをセットする.
		*psl_Pos = i32_CurrentPos;						// カーソル位置をセットする.

	}
	return bl_Ret;
}

//================================================================================================.
//概要	 ：未確定文字列のフィルター処理(未確定文字列).
//引数	 ：char*	文字列.
//戻り値 ：True：フィルタ処理実行 False：フィルタ処理無し.
//備考	 ：未確定文字列でフィルター処理するのは３バイト以上の文字列のみ.
//作成者 ：OPS1川手.
//================================================================================================.
Bool PLBC_GeneralKeybord::filterComposingTxt( char* psc_Src, const short ss_MaxCnt, const short ss_MaxSize )
{
	PCGC_SlideTextMgr* pc_Mgr = m_pc_SlideTxtMgr;
	if( ( NULL == psc_Src ) || ( NULL == pc_Mgr ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	Bool		bl_Ret = False;
	PLBC_CUtf8	c_Utf8( psc_Src );						// UTF8の文字列操作用クラスインスタンス.
	uchar		uc_OneBuf[8] = {0};						// UTF8の1文字分のバッファ.
	ushort		us_OneByteNum = 0;						// UTF8の1文字分のバイト数.
	char*		psc_TempAdd = psc_Src;
	short		ss_StrCnt = 0;							// 文字数のカウンタ.
	short		ss_StrSize = 0;							// 文字列バッファのカウンタ.

	// 全実データサイズをチェック.
	c_Utf8.GetFirst( ( char* )uc_OneBuf, &us_OneByteNum );		// 最初の1文字分のUTF8文字取得.
	while( 0 != us_OneByteNum ) {
// comment 2023/09/26 Sky東島 [IT6_2.3][OP_BTS-44893].
//		if( 3 < us_OneByteNum ) {								// 3バイトを越える文字は現在使用不可のため"■"に置き換える.
		if( PNLD_Keybord_MaxBytesOneChara_UTF8 < us_OneByteNum ) {								// サポート対象のバイトを越える文字は"■"に置き換える.
			uc_OneBuf[0] = 0xE2;
			uc_OneBuf[1] = 0x96;
			uc_OneBuf[2] = 0xA0;
			uc_OneBuf[3] = '\0';
			us_OneByteNum = 3;
			bl_Ret = True;
		}

		// サイズチェック処理.
		if( ( ( ss_StrCnt + 1 ) > ss_MaxCnt ) || ( ( ss_StrSize + ( short )us_OneByteNum ) >= ss_MaxSize ) ) {
			bl_Ret = True;
			break;
		}

		// コピー処理開始.
		if( True == bl_Ret ) {									// フィルターが発生した場合のみ.
			memcpy( psc_TempAdd, uc_OneBuf, us_OneByteNum );
		}
		psc_TempAdd += us_OneByteNum;

		ss_StrCnt++;											// 文字数のカウント.
		ss_StrSize = (short)( ss_StrSize + ( short )us_OneByteNum );						// 文字列バッファサイズのカウント.

		// 次のチェック用前処理.
		c_Utf8.GetNext( ( char* )uc_OneBuf, &us_OneByteNum );		// 1文字分のUTF8文字取得.
		uc_OneBuf[us_OneByteNum] = '\0';
	}

	if( True == bl_Ret ) {										// フィルターが発生した場合のみ.
		*psc_TempAdd = '\0';
	}

	return bl_Ret;
}

//================================================================================================.
//概要	 ：背景指定テキスト表示フィールドパーツ取得関数.
//引数	 ：なし.
//戻り値 ：PTextFieldBackground 背景指定テキスト表示フィールドのポインタ.
//備考	 ：未確定文字列の描画に必要なポインタを返す（IME用に対応）.
//作成者 ：OPS1川手.
//================================================================================================.
PTextFieldBackground* PLBC_GeneralKeybord::getTextFieldBackground( void )
{
	PTextFieldBackground* pc_Ret = NULL;
	if( PLBD_Enl_KBD_Enlarge == getChangeEnlKeybord() ) {
		pc_Ret = &Btx_EnlPreString_IME;			// 拡大用.
	} else if( True == getComKeyBordFlg() ) {
		pc_Ret = &Btx_PreString_COM_IME;		// 新UI用.
	} else {
		pc_Ret = &Btx_PreString_IME;			// 旧UI用.
	}
	return pc_Ret;
}

//================================================================================================.
//概要	 ：カーソル位置補正関数.
//引数	 ：PCGC_SlideTextMgr*	スライドテキストマネージャのポインタ.
//戻り値 ：なし.
//備考	 ：IMEのカーソル情報から、Panelのカーソル制御を行う.
//作成者 ：OPS1川手.
//================================================================================================.
void PLBC_GeneralKeybord::adjustCursor( PCGC_SlideTextMgr* pc_SlideTextMgr )
{
	if( NULL != pc_SlideTextMgr ) {
// comment 2016/05/27 OPS1-MSE荒川 [ZeusS_ZX0][CQ_530095] カーソル調整にキーボード種別の情報を追加.
//		pc_SlideTextMgr->adjustCursorPosition( m_st_IMETxtInfo.m_sc_CommittedTxt, ( ushort )m_st_IMETxtInfo.m_sl_CursorPos, getChangeEnlKeybord() );
		pc_SlideTextMgr->adjustCursorPosition( m_st_IMETxtInfo.m_sc_CommittedTxt, ( ushort )m_st_IMETxtInfo.m_sl_CursorPos, getChangeEnlKeybord(), getKeybordType() );
		PTextFieldBackground* pc_Parts = getTextFieldBackground();
		char* psc_Prestring = getPreString();													// 未確定文字列の取得.
		PNLS_TextCnt st_TextCnt;																// 文字列のサイズカウンタ.
		memset( &st_TextCnt, 0, sizeof( PNLS_TextCnt ) );
		ushort us_DispCharCnt = 0;																// 表示文字数（全角2文字、半角1文字）.
		if( True == pc_SlideTextMgr->getTextOffsetByCnt( psc_Prestring, PLBD_KBD_PreStringMaxCharCnt, &st_TextCnt ) ) {
			us_DispCharCnt = st_TextCnt.us_Range;												// 幅を指定.
		}
		if ( NULL != pc_Parts ) {
// comment 2014/11/21 OPS1-Sky石賀 [Poseidon][CQ507071] パス入力時、未確定文字も「*」表示させる.
			Bool bl_Password = False;
			PCGC_SelectTextMgr *pc_SelectTxtMgr = dynamic_cast<PCGC_SelectTextMgr*>( pc_SlideTextMgr );
			if ( NULL != pc_SelectTxtMgr ) {
				bl_Password = pc_SelectTxtMgr->getSelectProc();
			}
			if ( False == bl_Password ) {
				pc_Parts->changeExternalText( (uchar*)psc_Prestring, us_DispCharCnt, ep_charSet );	// 未確定文字列の更新.
			} else {
				// 未確定文字列を「*」に変換.
				uchar uc_PreStringPass[ PLBD_ENL_KBD_PreStringMaxByte ] = {'\0'};
				short ss_PreStringBytes = (short)strlen( psc_Prestring );
				short ss_PreStringCharCnt = 0;
				for ( short ss_cnt = 0; (ss_cnt < ss_PreStringBytes) && (ss_PreStringCharCnt < (PLBD_ENL_KBD_PreStringMaxByte - 1)); ) {
					ss_cnt = (short)( ss_cnt + LIBF_getUTF8ByteCount( psc_Prestring + ss_cnt ) );
					uc_PreStringPass[ ss_PreStringCharCnt ] = '*';
					ss_PreStringCharCnt++;
				}
				pc_Parts->changeExternalText( uc_PreStringPass, ss_PreStringCharCnt, ep_charSet );	// 未確定文字列の更新.
			}
			if ( NULL != p_Btx_InpArea ) {														// 未確定文字列の表示後、背景の再描画が必要.
				p_Btx_InpArea->showEnableShow( True );											// 入力文字表示領域を再表示.
			}
			pc_Parts->showEnableShow( True );													// 未確定文字列の表示.
		}
	}
}

