//作成者 ：OPS1本橋.
//================================================================================================.
void PLBC_GeneralKeybord::startGamenIMEKeyboard( void )
{
	// IMEサービスの有効無効設定.
	APIC_SystemStatus* pc_SystemStatus = PnlComGetSystemStatus();
	Bool bl_Enable = True;
	if( NULL != pc_SystemStatus ) {
		m_bl_ServiceModeOn = pc_SystemStatus->getServiceModeOn();	// IME用にサービスモードかどうかを保持しておく.
		bl_Enable = ( True == m_bl_ServiceModeOn ) ? False : True;	// サービスモードではIMEを使用できない.
	}
	if( NULL != m_pc_IMEMgr ) {
		m_pc_IMEMgr->setEnable( bl_Enable );
	}
}

