// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
// ----------------------------------------------------------------------------------.
/**
 *	@brief	濁点・半濁点・小文字キーの描画更新.
 *	@param[in]		スライドマネージャ.
 *	@retval			なし.
 */
// ----------------------------------------------------------------------------------.
void PLBC_GeneralKeybord::setupGamenReplaceKeybord( PCGC_SlideTextMgr* pc_SlideTextMgr )
{
	PNLD_CharType uc_CharType		= PNLD_CharType_None;
	char* psc_PreString				= getPreString();			// 未確定入力文字.
	short ss_BytePos				= 0;						// 変換対象の文字位置.

	if( NULL == psc_PreString ) {
		return;
	}

	// 変換対象チェック(c_PreString) SJIS.
	// 未確定入力文字が存在しない.
	if( 0 != strlen( psc_PreString ) ){
		// 最終文字のバイト数算出（全体のバイト数 - 1文字のByte数）
		ss_BytePos = (short)( strlen( psc_PreString ) - 2 );
		uc_CharType = getEnableReplaceChar( &psc_PreString[ss_BytePos] );
	} else {
		if( NULL == pc_SlideTextMgr ) {
			return;
		}
		
		uc_CharType = pc_SlideTextMgr->getEnableCharType();
	}
	
	// キー非活性状態設定.
	Bool bl_Dakuten		= False;
	Bool bl_HanDakuten	= False;
	Bool bl_Small		= False;

	if ( PNLD_CharType_Dakuten		== ( uc_CharType & PNLD_CharType_Dakuten ) ) {
		bl_Dakuten = True;
	}
	if ( PNLD_CharType_HanDakuten	== ( uc_CharType & PNLD_CharType_HanDakuten ) ) {
		bl_HanDakuten = True;
	}
	if ( PNLD_CharType_Small			== ( uc_CharType & PNLD_CharType_Small ) ) {
		bl_Small = True;
	}
	
	if ( True == getComKeyBordFlg() ) {
		Key_KeybordcomDakuten_COM.activate( bl_Dakuten );
		Key_KeybordcomHanDakuten_COM.activate( bl_HanDakuten );
		Key_KeybordcomSmallChar_COM.activate( bl_Small );

		if( PNLE_KEYTOPTYPE_Small == uc_KeyTopType ){
			Key_KeybordcomDakuten_COM_HL.activate( bl_Dakuten );
			Key_KeybordcomHanDakuten_COM_HL.activate( bl_HanDakuten );
			Key_KeybordcomSmallChar_COM_HL.activate( bl_Small );
		}

	} else {
		Key_KeybordcomDakuten.activate( bl_Dakuten );
		Key_KeybordcomHanDakuten.activate( bl_HanDakuten );
		Key_KeybordcomSmallChar.activate( bl_Small );
	}

	if ( PLBD_Enl_KBD_Enlarge == e_EnlKeybordState ) {
		Key_EnlKeybordcomDakuten.activate( bl_Dakuten );
		Key_EnlKeybordcomHanDakuten.activate( bl_HanDakuten );
		Key_EnlKeybordcomSmallChar.activate( bl_Small );
	}
}

/*================================================================================================
//概要    ：キーボードクラス : コンストラクタ
================================================================================================*/
PLBC_GeneralKeybord::PLBC_GeneralKeybord(
    KeybordType keybordType,				// キーボードの種類
    short ss_Tx,							// 表示位置Ｘ座標(バイト単位)
    short ss_Gy,							// 表示位置Ｙ座標(ドット単位)
    Bool b_isDispLR,						// ←→キーを表示するか True:表示する
    Bool b_isDispDel,						// 削除キーを表示するか True:表示する
    COLOR _bkColor,							// 背景色
    PNL_ENLARGE pnl_enlarge,				// 拡大表示対応.
    PActivatable* p_Btx_InpArea,			// 入力文字表示領域.
    EnlKeybordState e_EnlKeybordState,		// 標準・拡大状態.
    short ss_TxEnl,							// 切換え拡大表示位置Ｘ座標(バイト単位)
    short ss_GyEnl,							// 切換え拡大表示位置Ｙ座標(ドット単位)
    ushort	us_KeyboardDispLenMax,			// 標準⇔拡大切り替え用キーボード入力MAX値.
    ushort	us_EnlKeyboardDispLenMax )		// 標準⇔拡大切り替え用キーボード入力MAX値（拡大）.
	: m_pc_SlideTxtMgr( NULL )				// スライドテキストマネージャ // 2013/04/17 OPS1川手 [操作性改善FUM4] CQ378997対応.
// Comment 2015/10/08【HCLT-Meera】【CQ519679】【ID: 30313】UNINIT.CTOR.MUST
    , mb_StartUSBKeyBord( False )
	, sc_Tx( 0 )
	, uc_Gy( 0 )
	, p_Btx_InpArea( NULL )
	, pc_MmbNowPopup( NULL )
	, pc_MmbNowBrwPopup( NULL )
	, us_GetCount( 0 )
	, m_bl_ServiceModeOn( False )			// サービスモードかどうか 2013/01/28 OPS1川手 [操作性改善FUM4] CT不具合対応(IME文字入力).
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33778 [UNINIT.CTOR.MUST] Initialisation of voice/semi-voice souns sensitive active key state.		
	, m_uc_EnableCharType(PNLD_CharType_None)
	, uc_PreStringCount( 0 )
	, m_bl_USBConnectionPermissionFlag( True ) 			//Comment 2015/08/07 HCLT-Rengaraaj RQ-163[WP 1344] .
{
	// 通常表示.
	PLBC_GeneralKeybord::pnl_enlarge = pnl_enlarge;
	if( pnl_enlarge == PNL_ENLARGE_X1xY1 ) {
		// 表示位置を設定(範囲外の場合、 最大値)
		if( ( 0 <= ss_Tx ) && ( ss_Tx <= PLBD_GeneralKeybordMaxTx ) ) {
			PLBC_GeneralKeybord::ss_Tx = ss_Tx;
		} else {
			PLBC_GeneralKeybord::ss_Tx = PLBD_GeneralKeybordMaxTx;
		}
		if( ss_Gy <= PLBD_GeneralKeybordMaxGy ) {
			PLBC_GeneralKeybord::ss_Gy = ss_Gy;
		} else {
			PLBC_GeneralKeybord::ss_Gy = PLBD_GeneralKeybordMaxGy;
		}
	} else {
		// 拡大表示.
		// 拡大表示キーボードはスペースがないため、動かさないとしておく.
		PLBC_GeneralKeybord::ss_Tx = 8;
		PLBC_GeneralKeybord::ss_Gy = 76;
	}
	// キーボードの種類を設定(範囲外の場合、デフォルト値)
	if( keybordType <= PLBD_KBT_Hiragana ) {
		PLBC_GeneralKeybord::keybordType = keybordType;
	} else {
		PLBC_GeneralKeybord::keybordType = PLBD_KBT_Default;
	}
	// フォントセット(キャラクタセット)初期化
	ep_charSet = EP_CharSet_Non;
	// ←→キーを表示するか
	PLBC_GeneralKeybord::b_isDispLR = b_isDispLR;
	// 削除キーを表示するか
	PLBC_GeneralKeybord::b_isDispDel = b_isDispDel;
	// キーボードの表示/非表示 True:表示する
	b_isShow = True;
	// 背景色
	PLBC_GeneralKeybord::bkColor = _bkColor;
	// 初期化未実行
	PLBC_GeneralKeybord::b_isInitialized = False;
	// 切換えキーボード表示位置
	if( ( 0 <= ss_TxEnl ) && ( ss_TxEnl <= PLBD_GeneralKeybordEnlMaxTx ) ) {
		PLBC_GeneralKeybord::ss_TxEnl = ss_TxEnl;
	} else {
		PLBC_GeneralKeybord::ss_TxEnl = PLBD_GeneralKeybordEnlMaxTx;
	}
	if( ss_GyEnl <= PLBD_GeneralKeybordEnlMaxGy ) {
		PLBC_GeneralKeybord::ss_GyEnl = ss_GyEnl;
	} else {
		PLBC_GeneralKeybord::ss_GyEnl = PLBD_GeneralKeybordEnlMaxGy;
	}
	// 標準⇔拡大切り替え用キーボード入力MAX値.
	PLBC_GeneralKeybord::us_KeyboardDispLenMax = PCGD_KeyboardDispLenMax;
	// 標準⇔拡大切り替え用キーボード入力MAX値（拡大）.
	PLBC_GeneralKeybord::us_EnlKeyboardDispLenMax = PCGD_EnlKeyboardDispLenMax;
	b_ComKeyBordFlg = False;									// TRUE:コンポーネント False 通常
	p_Btx_PreString = &Btx_PreString_COM;						// キーボード画面の未確定文字列パーツ.
	if( NULL == m_pc_IMEMgr ) {								// 2012/12/04 OPS1川手 操作性改善FUMVer4(WBS No.62-64).
		m_pc_IMEMgr = PNLC_IMEManager::getInstance();
		if( NULL != m_pc_IMEMgr ) {
			m_pc_IMEMgr->registIMETxtInfo( &m_st_IMETxtInfo );
		}
	}
	
// comment 2015/12/21 OPS1-Sky飯田 [ZeusS_ZX0][反応総点検][CQ523533].
	memset( m_bl_EnableKeyArray, True, sizeof( m_bl_EnableKeyArray ) );
}
