	Key_KeybordcomCharacterCode.changeSize( 128, 32 );
	Key_KeybordcomCharacterCode.setShowPush(True);
#endif //#ifdef DEF_RES_WSVGA.
// comment 2016/06/10 Sky溝部 [ZeusSBK][キーボード改善_プロポーショナルフォント化対応].
	Key_KeybordcomCharacterCode.changeFontsize( PNLE_SELECT_FONT_A );
	
	Key_KeybordcomSpaceZenkaku.changePosition( 532,384 );	// 空白キー.
// comment 2016/04/01 OPS1-Sky渡邉 [Icarus][キーボード改善].
#ifdef DEF_RES_WSVGA
	Key_KeybordcomSpaceZenkaku.changeSize( 138, 55 );
#else //#ifdef DEF_RES_WSVGA.
	Key_KeybordcomSpaceZenkaku.changeParts( tbl_m30_002_000_n_X160_Y32 );
	Key_KeybordcomSpaceZenkaku.changeSize( 108, 44 );
#endif //#ifdef DEF_RES_WSVGA.
	Key_KeybordcomSpaceZenkaku.setShowPush(True);
	Key_KeybordcomSpaceZenkaku.changeShadow(PNLE_Shadow_Parts_2);
// comment 2016/06/10 Sky溝部 [ZeusSBK][キーボード改善_プロポーショナルフォント化対応].
	Key_KeybordcomSpaceZenkaku.changeFontsize( PNLE_SELECT_FONT_D );

	Key_KeybordcomHalfKana.changePosition( 688,176 );	// 半角キー.
#ifdef DEF_RES_WSVGA
	Key_KeybordcomHalfKana.changeSize( 115, 40 );
#else //ifdef DEF_RES_WSVGA.
	Key_KeybordcomHalfKana.changeSize( 96, 32 );
#endif //ifdef DEF_RES_WSVGA.
	Key_KeybordcomHalfKana.setShowPush(True);
// comment 2016/06/10 Sky溝部 [ZeusSBK][キーボード改善_プロポーショナルフォント化対応].
