#else //ifdef DEF_RES_WSVGA.
	Key_KeybordcomSmallChar.changeParts( tbl_m30_002_000_n_X160_Y32 );
	Key_KeybordcomSmallChar.changeSize( 96, 32 );
#endif //ifdef DEF_RES_WSVGA.
	Key_KeybordcomSmallChar.setShowPush(True);
	Key_KeybordcomSmallChar.changeShadow(PNLE_Shadow_Parts_2);
// comment 2016/06/10 Sky溝部 [ZeusSBK][キーボード改善_プロポーショナルフォント化対応].
	Key_KeybordcomSmallChar.changeFontsize( PNLE_SELECT_FONT_A );

