//	Key_KeybordcomNoConvert.changePosition( 688, 228 );	// 無変換キー.
	if( EP_CharSet_GB2312 != _ep_charSet ) {
		Key_KeybordcomNoConvert.changePosition( 688, 228 );	// 無変換キー.
	} else {
		Key_KeybordcomNoConvert.changePosition( 688, 360 );	// 無変換キー.
	}
#ifdef DEF_RES_WSVGA
	Key_KeybordcomNoConvert.changeSize( 115, 40 );
#else //ifdef DEF_RES_WSVGA.
	Key_KeybordcomNoConvert.changeParts( tbl_m30_002_000_n_X160_Y32 );
	Key_KeybordcomNoConvert.changeSize( 96, 32 );
#endif //ifdef DEF_RES_WSVGA.
