//================================================================================================
//概要    ：キーボードの標準・拡大状態を取得する（カラーUI用）.
//================================================================================================
EnlKeybordState PLBC_GeneralKeybord::getChangeEnlKeybord()
{
	return( PLBC_GeneralKeybord::e_EnlKeybordState );
}
//================================================================================================
//概要    ：キーボードの標準・拡大状態を設定する（カラーUI用）.
//================================================================================================
void PLBC_GeneralKeybord::setChangeEnlKeybord( EnlKeybordState e_EnlKeybordState )
{
	PLBC_GeneralKeybord::e_EnlKeybordState = e_EnlKeybordState;
	// 変換候補表示数MAX値の設定.
	if( PLBD_Enl_KBD_Enlarge != PLBC_GeneralKeybord::e_EnlKeybordState ) {
		c_CChg.VjeData.cLBItemNumMax = PLBD_KBD_KohoMax;
	}
}
//================================================================================================
//概要    ：キーボードの標準・MAX領域を設定する（カラーUI用）.
//================================================================================================
void PLBC_GeneralKeybord::setKeyboardDispLenMax( ushort	us_KeyboardDispLenMax, ushort	us_EnlKeyboardDispLenMax )
{
	// MAX表示領域の設定.
	PLBC_GeneralKeybord::us_KeyboardDispLenMax = us_KeyboardDispLenMax;
	PLBC_GeneralKeybord::us_EnlKeyboardDispLenMax = us_EnlKeyboardDispLenMax;
}
//================================================================================================
//概要    ：キーボードの標準・MAX領域を取得する（カラーUI用）.
//================================================================================================
ushort PLBC_GeneralKeybord::getKeyboardDispLenMax()
{
	// 標準・拡大のMAX領域を返す.
	if( PLBD_Enl_KBD_Enlarge == PLBC_GeneralKeybord::e_EnlKeybordState ) {
		if( &Btx_EnlPasswordReInput == p_Btx_InpArea
		    || &Btx_EnlPasswordReInputCheck == p_Btx_InpArea ) {
			return (ushort)( PLBC_GeneralKeybord::us_EnlKeyboardDispLenMax - 8 );
		} else {
			return ( PLBC_GeneralKeybord::us_EnlKeyboardDispLenMax );
		}
	} else {
		return ( PLBC_GeneralKeybord::us_KeyboardDispLenMax );
	}
}

//================================================================================================
//概要    ：キーボードの標準・表示X,Y位置設定(ドット単位).
//戻り値  ：なし.
//備考    ：
//作成者  ：表.
//================================================================================================
void PLBC_GeneralKeybord::setTxGy( short ss_TempTx, short ss_TempGy )
{
	Bool b_PosChangeFlg = False;
	if( getComKeyBordFlg() && ( ss_Tx!=ss_TempTx || ss_Gy!=ss_TempGy ) ) {		// 位置が変更された場合.
		b_PosChangeFlg = True;
	}
	ss_Tx = ss_TempTx;	// 表示X位置(ドット単位).
	ss_Gy = ss_TempGy;	// 表示Y座標(ドット単位).
	if( b_PosChangeFlg ) {			// 位置が変更された場合.
		setKeybordLayout();			// キーボードの位置が変更されたのでパーツの位置も更新する.
	}
}
//================================================================================================
//概要    ：カスタムキーボード使用判定.
//戻り値  ：True:使用する　False:使用しない.
//================================================================================================
Bool PLBC_GeneralKeybord::isCustomKeybord()
{
	Bool bl_ret = False;

	TYPE_Language e_KeybordLanguage = PnlComGetSoftwareKeyboardLanguage();
	switch( e_KeybordLanguage ) {
		case TYPE_LanguageFrench:     // フランス語キーボード.
			if( ( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW203, 6 ) )
			    && ( False == ppc_SystemStatus->getServiceModeOn() ) ) {	// DipSW203 bit6がON、かつサービスモードでない場合.
				bl_ret = True;
			}
			break;
		default:	break;
	}
	return bl_ret;
}

//================================================================================================.
//概要    ：IME起動キー表示開始処理.
//戻り値  ：なし.
//備考    ：
//        ：                      引数追加、IME起動状態変数の型変更.
//================================================================================================.
void PLBC_GeneralKeybord::startKbdIMESetting( PNLD_IMERUNMODE e_IMEMode )
{
	m_e_IMEMode = PNLD_IMERUNMODE_NONE;

	APIC_TabletIF* pcTabletIF = APIC_TabletIF::newInstance();
	if( NULL == pcTabletIF ) {
		return;
	}
	if( False == onlyPanel.bl_ServiceMode ) {
		if( APIE_TabletOptionEnable == pcTabletIF->getOptionEnable( APIE_TabletIMEInput )
		    || APIE_TabletOptionEnable == pcTabletIF->getOptionEnable( APIE_TabletIMEMode ) ) {
			m_e_IMEMode = e_IMEMode;
		}
	} else {
		if( APIE_TabletOptionEnable == pcTabletIF->getOptionEnable( APIE_TabletIMEMode ) )  {
			m_e_IMEMode = e_IMEMode;
		}
	}
}

