//				Key_KeybordcomEuro_COM_HL.showEnable( False );			// Euro記号キーを非表示.
				bl_ShowEnable_Key_KeybordcomZenkaku_COM_HL = False;				// 全角切り替えキー非表示.
				bl_ShowEnable_Key_KeybordcomConvert_COM_HL = False;				// 変換キーを非表示.
				bl_ShowEnable_Key_KeybordcomNoConvert_COM_HL = False;				// 無変換キーを非表示.
				bl_ShowEnable_Key_KeybordcomLanguage_COM_HL = False;				// ○○語キーを非表示.
				bl_ShowEnable_Key_KeybordcomCharacterCode_COM_HL = False;			// 文字コード入力キーを非表示.
				bl_ShowEnable_Key_KeybordcomStd_COM_HL = False;					// 英/数キーを非表示.
				bl_ShowEnable_Key_KeybordcomEuro_COM_HL = False;					// Euro記号キーを非表示.
