			// 変換モード画面時に使うパーツを出す
			Rbt_KeySigletap_COM.showEnable( True );							// キーボード変換候補12個のボタン.
// comment 2015/09/11 OPS1 Sky東島 [Poseidon2.0c][CQ518664].
//			Key_KeybordcomStd_COM.showEnable( b_isShow );				// 英/数キー.
//			Key_KeybordcomLanguage_COM.showEnable( b_isShow );			// ○○語キー.
