				case TYPE_LanguageDanish		: Key_KeybordcomLanguage_COM.changeText( s_pKEYDanish_W080H028A );	break;	// 「デンマーク語」.
				case TYPE_LanguageItalian		: Key_KeybordcomLanguage_COM.changeText( s_pKEYItalian_W080H028A );	break;	// 「イタリア語」.
				case TYPE_LanguageSpanish		: Key_KeybordcomLanguage_COM.changeText( s_pKEYSpanish_W080H028A );	break;	// 「スペイン語」.
