				case TYPE_LanguagePortuguese	: Key_KeybordcomLanguage_COM.changeText( s_pKEYPortuguese_W080H028A ); break;	// ポルトガル語.
				case TYPE_LanguageSwedish		: Key_KeybordcomLanguage_COM.changeText( s_pKEYSwedish_W080H028A );	break;	// スウェーデン語.
