			case TYPE_LanguageCzech			: Key_KeybordcomLanguage.changeText( s_KEYChangeoverCzech );		break;	// 「チェコ語」 .
			case TYPE_LanguageJapanese		: Key_KeybordcomLanguage.changeText( s_KEYChangeoverJapanese ); Key_KeybordcomAltGr.changeText( s_KeyboadKatakana );											break;	// 「カタカナ」
			case TYPE_LanguageChinese1		: Key_KeybordcomLanguage.changeText( s_KEYTaiwaneseA );			break;
			case TYPE_LanguageChinese2		: Key_KeybordcomLanguage.changeText( s_KEYChineseA );				break;
			case TYPE_LanguageHangul		: Key_KeybordcomLanguage.changeText( s_KEYKoreanA );				break;	// 「hangul語」 //so_jo 2nd Hangul対応.
			case TYPE_LanguagePortuguese	: Key_KeybordcomLanguage.changeText( s_KEYChangeoverPortuguese );	break; // ポルトガル語
			case TYPE_LanguageSwedish		: Key_KeybordcomLanguage.changeText( s_KEYChangeoverSwedish );	break; // スウェーデン語.
			case TYPE_LanguageNorwegian		: Key_KeybordcomLanguage.changeText( s_KEYChangeoverNorwegian );	break; // ノルウェー語.
			case TYPE_LanguageFinnish		: Key_KeybordcomLanguage.changeText( s_KEYChangeoverFinnish );	break; // フィンランド語.
