/*================================================================================================
//概要    ：キーボードクラス : KeybordTypeの標準⇔拡大切換え（カラーUI用）
================================================================================================*/
void PLBC_ConvertKeybord::ChangeEnlKeybordType( KeybordType keybordType )
{
	unsigned char cnt = 0;
	// KeybordTypeの切換え処理
	while( NULL != s_KeybordTable[ cnt ].e_KeybordType ) {
		if( s_KeybordTable[ cnt ].e_KeybordType == keybordType ) {
			if( True == PLBC_FuncVersionCheck::isOK_Type1() ) {
				if( ( PLBD_ENL_KBT_CharacterCodeInput == keybordType )
				    ||( PLBD_ENL_KBT_CharacterCodeInputWide == keybordType ) ) {
					// 文字コードONの場合、ポジションをE-mail用にチェンジしておく.
					changePositionKeybord_CLCD( PLBD_ENL_KBT_EMail1 );
				}
			} else {
				if( PLBD_ENL_KBT_CharacterCodeInput == keybordType ) {
					// 文字コードONの場合、ポジションをE-mail用にチェンジしておく.
					changePositionKeybord_CLCD( PLBD_ENL_KBT_EMail1 );
				}
			}
			if( True == PLBC_FuncVersionCheck::isOK_Type1() ) {
				if( ( PLBD_KBT_CharacterCodeInput == keybordType )
				    ||( PLBD_KBT_CharacterCodeInputWide == keybordType ) ) {
					// 文字コードONの場合、ポジションをE-mail用にチェンジしておく.
					changePositionKeybordChangeEnl( PLBD_KBT_EMail );
				}
			} else {
				if( PLBD_KBT_CharacterCodeInput == keybordType ) {
					// 文字コードONの場合、ポジションをE-mail用にチェンジしておく.
					changePositionKeybordChangeEnl( PLBD_KBT_EMail );
				}
			}
			// 切換え処理
			procButtonOn( s_KeybordTable[ cnt ].uc_ChangeKeybordOption );
			// 標準への切換え
			if( PLBD_Enl_KBD_Normal == e_EnlKeybordState ) {
				// AltGr押下状態の処理
				if( 0 != s_KeybordTable[ cnt ].uc_ChangeKeybordAltGr ) {
					procButtonOn( 225 );
				}
			} else {
				// 拡大への切換え
				// AltGr押下状態の処理
				if( 0 != s_KeybordTable[ cnt ].uc_ChangeKeybordAltGr ) {
					procButtonOn( s_KeybordTable[ cnt ].uc_ChangeKeybordAltGr );
				}
			}
			// Shift押下状態の処理
			if( 0 != s_KeybordTable[ cnt ].b_ChangeKeybordShift ) {
				procButtonOn( 223 );
			}
			// 文字コードキー押下状態の処理.
			if( 0 != s_KeybordTable[ cnt ].b_ChangeKeybordCharCode ) {
				procButtonOn( 226 );
			}
			// 全角キー押下状態の処理.
			if( 0 != s_KeybordTable[ cnt ].b_ChangeKeybordZenkaku ) {
				if( PLBD_Enl_KBD_Normal == e_EnlKeybordState ) {
					procButtonOn( 235 );
				} else {
					procButtonOn( 242 );
				}
			}
			// 記号キー押下状態の処理.
			if( 0 != s_KeybordTable[ cnt ].b_ChangeKeybordSymbol ) {
				if( PLBD_Enl_KBD_Normal == e_EnlKeybordState ) {
					procButtonOn( 232 );
				} else {
					procButtonOn( 234 );
				}
			}
			// 半角キー押下状態の処理.
			if( 0 != s_KeybordTable[ cnt ].b_ChangeKeybordHankaku ) {
				if( PLBD_Enl_KBD_Normal == e_EnlKeybordState ) {
					procButtonOn( 234 );
				} else {
					procButtonOn( 241 );
				}
			}
			break;
		}
		cnt++;
	}
	// 変換画面で「切換えキー」を押した場合、ひらがなキーボードへと戻す
	PLBC_ConvertKeybord::b_KeybordConvertMode = False;
	return;
}

