//================================================================================================
void PLBC_ConvertKeybord::changePositionKeybordChangeEnl( KeybordType _ec_KeybordType )
{
	short	ss_nowTx;				// 現在のキー位置取得用.
	short	ss_nowGy;				// 現在のキー位置取得用.
	const short* ptbl_PositionTx;
	const short* ptbl_PositionGy;
	uchar	uc_cnt;					// カウンタ.
	short ss_Count = 0 ; // 座標数 .
	PLBC_WideKeyboard*	pc_WideKeyboard = PLBC_WideKeyboard::getInstance() ;

	// キーを移動させた痕跡が残るので、消した状態で移動させる.
	// なお、消したキーと文字を表示させるのはPLBC_GeneralKeybord::showKeybord()で行う.
	for( uc_cnt=0; uc_cnt < PLBD_KeyNumMaxEnl; uc_cnt++ ) {
		Tfd_EnlKeybord[uc_cnt].showEnable( False );
		Kty_EnlKeybord[uc_cnt].showEnable( False );
	}
	// 移動前のキーボード位置.
	switch( PLBC_GeneralKeybord::_ec_KeyPositionEnl ) {
		case PLBD_KBD_PositionKana:
			ptbl_PositionTx = tbl_KanaPositionTxEnl;
			ptbl_PositionGy = tbl_KanaPositionGyEnl;
			break;
// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
		case PLBD_KBD_PositionKanaHalf:
			ptbl_PositionTx = tbl_KanaHalfPositionTxEnl;
			ptbl_PositionGy = tbl_KanaHalfPositionGyEnl;
		break;
		case PLBD_KBD_PositionASCII:
			ptbl_PositionTx = tbl_USAsciiPositionTxEnl;
			ptbl_PositionGy = tbl_USAsciiPositionGyEnl;
			break;
		case PLBD_KBD_PositionJIS:
		default:
			ptbl_PositionTx = tbl_JisAsciiPositionTxEnl;
			ptbl_PositionGy = tbl_JisAsciiPositionGyEnl;
			break;
	}
	// キーボードの種類に応じて、キーを移動させる.
	// 日本語系のキーボードの場合.
	if( _ec_KeybordType == PLBD_ENL_KBT_Japan1 ||				// 日本語キーボード1.
	    _ec_KeybordType == PLBD_ENL_KBT_Japan2 ||				// 日本語キーボード2.
	    _ec_KeybordType == PLBD_ENL_KBT_JapanAnother1 ||		// 日本語キーボード他かな1.
	    _ec_KeybordType == PLBD_ENL_KBT_JapanAnother2 ||		// 日本語キーボード他かな2.
	    _ec_KeybordType == PLBD_ENL_KBT_Katakana1 ||			// 日本語キーボードカタカナ1.
	    _ec_KeybordType == PLBD_ENL_KBT_Katakana2 ||			// 日本語キーボードカタカナ2.
	    _ec_KeybordType == PLBD_ENL_KBT_KatakanaAnother1 ||		// 日本語キーボードカタカナ他かな1.
		_ec_KeybordType == PLBD_ENL_KBT_KatakanaAnother2 ) {		// 日本語キーボードカタカナ他かな2.
// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
//		_ec_KeybordType == PLBD_ENL_KBT_Katakana1_Half ||			// 拡大表示 日本語半角カタカナキーボード1
//		_ec_KeybordType == PLBD_ENL_KBT_Katakana2_Half ||			// 拡大表示 日本語半角カタカナキーボード2
//		_ec_KeybordType == PLBD_ENL_KBT_KatakanaAnother1_Half ){	// 拡大表示 日本語半角他カナキーボード1，2
		// 未移動のときだけ移動させる
		if( PLBC_GeneralKeybord::_ec_KeyPositionEnl != PLBD_KBD_PositionKana ) {
			// ワイド、通常ともに移動が必要になる為、文字コードを保存 .
			ss_Count = sizeof( tbl_KanaPositionTxEnl ) / sizeof( short ) ;			// 座標数 .
			pc_WideKeyboard->setInputKeyType( PNLE_WideKeyboardCodeKana, tbl_KanaPositionTxEnl, tbl_KanaPositionGyEnl, ss_Count, True ) ;
			if( True == pc_WideKeyboard->isWideKeyboardGamen() ) {
				pc_WideKeyboard->changeInputKeyPosition_ToWideKeyboard( True ) ;
			} else {
				for( uc_cnt=0; uc_cnt<PLBD_KeyNumMax; uc_cnt++ ) {
					Kty_EnlKeybord[uc_cnt].getPosition( ss_nowTx, ss_nowGy );
					Kty_EnlKeybord[uc_cnt].changePosition( (short)( ss_nowTx + tbl_KanaPositionTxEnl[uc_cnt] - ptbl_PositionTx[uc_cnt] ), (short)( ss_nowGy + tbl_KanaPositionGyEnl[uc_cnt] - ptbl_PositionGy[uc_cnt] ) );
				}
			}
			PLBC_GeneralKeybord::_ec_KeyPositionEnl = PLBD_KBD_PositionKana;	// かな用とする
		}
// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
	// 日本語系キーボード（半角カナ）の場合.
	} else if( ( PLBD_ENL_KBT_Katakana1_Half == _ec_KeybordType )
			|| ( PLBD_ENL_KBT_Katakana2_Half == _ec_KeybordType )
			|| ( PLBD_ENL_KBT_KatakanaAnother1_Half == _ec_KeybordType ) ) {

		// 未移動のときだけ移動させる 
		if( PLBC_GeneralKeybord::_ec_KeyPositionEnl != PLBD_KBD_PositionKanaHalf ){
			// ワイド、通常ともに移動が必要になる為、文字コードを保存 .
			ss_Count = sizeof( tbl_KanaHalfPositionTxEnl ) / sizeof( short ) ;			// 座標数 .
			pc_WideKeyboard->setInputKeyType( PNLE_WideKeyboardCodeKanaHalf, tbl_KanaHalfPositionTxEnl, tbl_KanaHalfPositionGyEnl, ss_Count, True ) ;
			if( ( True == pc_WideKeyboard->isWideKeyboardGamen() )					// ワイドキーボード対応画面 . 
			  &&( True == pc_WideKeyboard->getInitKeyPosition_NormalKeyboard() ) ){	// 通常キーボード配置初期化済み .
				pc_WideKeyboard->changeInputKeyPosition_ToWideKeyboard( True ) ;
			} else {
				for( uc_cnt=0; uc_cnt<PLBD_KeyNumMax; uc_cnt++ ){
					Kty_EnlKeybord[uc_cnt].getPosition(ss_nowTx, ss_nowGy);
					Kty_EnlKeybord[uc_cnt].changePosition( (short)( ss_nowTx + tbl_KanaHalfPositionTxEnl[uc_cnt] - ptbl_PositionTx[uc_cnt] ), (short)( ss_nowGy + tbl_KanaHalfPositionGyEnl[uc_cnt] - ptbl_PositionGy[uc_cnt] ));
				}
			}
			PLBC_GeneralKeybord::_ec_KeyPositionEnl = PLBD_KBD_PositionKanaHalf;	// かな用とする 
		}
		
 		// US ASCIIキーボードの場合.
	} else if( _ec_KeybordType == PLBD_ENL_KBT_USAscii
	           || PLBD_ENL_KBT_USAsciiShift == _ec_KeybordType
	           || PLBD_ENL_KBT_USAscii_Custom == _ec_KeybordType
	           || PLBD_ENL_KBT_USAsciiShift_Custom == _ec_KeybordType ) {

		// 未移動のときだけ移動させる
		if( PLBC_GeneralKeybord::_ec_KeyPositionEnl != PLBD_KBD_PositionASCII ) {
			// ワイド、通常ともに移動が必要になる為、文字コードを保存 .
			ss_Count = sizeof( tbl_USAsciiPositionTxEnl ) / sizeof( short ) ;			// 座標数 .
			pc_WideKeyboard->setInputKeyType( PNLE_WideKeyboardCodeASCII, tbl_USAsciiPositionTxEnl, tbl_USAsciiPositionGyEnl, ss_Count, True ) ;
			if( True == pc_WideKeyboard->isWideKeyboardGamen() ) {
				pc_WideKeyboard->changeInputKeyPosition_ToWideKeyboard( True ) ;
			} else {
				for( uc_cnt=0; uc_cnt<PLBD_KeyNumMax; uc_cnt++ ) {
					Kty_EnlKeybord[uc_cnt].getPosition( ss_nowTx, ss_nowGy );
					Kty_EnlKeybord[uc_cnt].changePosition( (short)( ss_nowTx + tbl_USAsciiPositionTxEnl[uc_cnt] - ptbl_PositionTx[uc_cnt] ), (short)( ss_nowGy + tbl_USAsciiPositionGyEnl[uc_cnt] - ptbl_PositionGy[uc_cnt] ) );
				}
			}
			PLBC_GeneralKeybord::_ec_KeyPositionEnl = PLBD_KBD_PositionASCII;	// US ASCII用とする
		}
		// それ以外（英語圏のキーボード）の場合.
	} else {
		// 未移動のときだけ移動させる
		if( PLBC_GeneralKeybord::_ec_KeyPositionEnl != PLBD_KBD_PositionJIS ) {
			// ワイド、通常ともに移動が必要になる為、文字コードを保存 .
			ss_Count = sizeof( tbl_JisAsciiPositionTxEnl ) / sizeof( short ) ;				// 座標数 .
			// 通常キーボードの座標を保存 .
			pc_WideKeyboard->setInputKeyType( PNLE_WideKeyboardCodeJIS, tbl_JisAsciiPositionTxEnl, tbl_JisAsciiPositionGyEnl, ss_Count, True ) ;
			if( True == pc_WideKeyboard->isWideKeyboardGamen() ) {
				pc_WideKeyboard->changeInputKeyPosition_ToWideKeyboard( True ) ;
			} else {
				for( uc_cnt=0; uc_cnt<PLBD_KeyNumMax; uc_cnt++ ) {
					Kty_EnlKeybord[uc_cnt].getPosition( ss_nowTx, ss_nowGy );
					Kty_EnlKeybord[uc_cnt].changePosition( (short)( ss_nowTx + tbl_JisAsciiPositionTxEnl[uc_cnt] - ptbl_PositionTx[uc_cnt] ), (short)( ss_nowGy + tbl_JisAsciiPositionGyEnl[uc_cnt] - ptbl_PositionGy[uc_cnt] ) );
				}
			}
			PLBC_GeneralKeybord::_ec_KeyPositionEnl = PLBD_KBD_PositionJIS;	// JIS配列用とする
		}
	}
}
