				uc_KeybordEUTypeEnl = 1;				// キーボード種別(EU)を解除する.
				b_KeybordLanguageEnl = False;			// 各国語モードを解除する.
				b_KeybordHangulEnl = False;				// キーボード種別(ハングル)を解除する.
