					Key_EnlKeybordcomKatakana.select( b_isShow );				// カタカナキーの反転処理.
					e_Key_EnlKeybordcomKatakana	= ( True == b_isShow ) ? PNLE_PartsDisplay_Show : PNLE_PartsDisplay_Hide;			// カタカナキーを表示.
					Key_EnlKeybordcomHalfChar.select( b_KeybordHalfCharEnl );	// 半角キーの反転処理
