//Comment 2015/08/28 HCLT-Rengaraaj RQ-163[WP 1344] Hide External Keyboard button UT Bug Fix.
//================================================================================================.
//概要	 ：To update and return m_bl_USBConnectionPermissionFlag.
//引数	 ：なし.
//戻り値 ：Bool[True: USB connection permission allow, False:USB connection permission restrict..
//備考	 ：.
//作成者 ：HCL_Renga.
//================================================================================================.
Bool PLBC_GeneralKeybord::isUSBConnectionPermitted()
{
	// m_bl_USBConnectionPermissionFlag value will reflect dynamically based on admin screen change.
	PNLC_USBConnectionPermission c_UsbPermission;
	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
// Comment 2015/10/08【HCLT-Shenbaga】【CQ519679】【ID: 30315】RETVOID.GEN.
	//if ( NULL == pc_SystemSetting ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	if ( NULL == pc_SystemSetting ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return False; }
		PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
 		if( ( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( False == pc_SystemSetting->getEnableUSBConnectForKeyboard() ) ) {
			m_bl_USBConnectionPermissionFlag = False;
		} else {
			m_bl_USBConnectionPermissionFlag = True;
		}
	return m_bl_USBConnectionPermissionFlag;
	
}

//comment 2023/04/27 FPT.ThanhLH11 [IT6_2.3][ALL MACHINE][OP_BTS-42837]Fix non-character keyboard.
//============================================================================================
//概要		：To check key content in key table.
//引数		：void.
//戻り値	：Bool [True: All key content is blank, False: At least one key has content].
//作成者	：FPT.ThanhLH11.
//============================================================================================
Bool PLBC_GeneralKeybord::isBlankMSbinKeyTbl()
{
	if( NULL == tbl_MSbinKeyTbl ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return True;
	}
 
	char sc_Temp[TYPD_CharCode + 1];
	uchar uc_Temp[TYPD_CharCode];

	for( uchar i = 0; i < PLBD_KeyNumMax; i++ ) {

		memset( sc_Temp, 0, sizeof( sc_Temp ) );
		memset( uc_Temp, 0, sizeof( uc_Temp ) );

		memcpy( uc_Temp, tbl_MSbinKeyTbl->keyInfo[i].sc_KeyTopChar, sizeof( uc_Temp ) );
		ushort us_Unicode = 0;
		us_Unicode = ( ushort ) uc_Temp[0];
		us_Unicode = (ushort)( us_Unicode << 8 );
		us_Unicode = (ushort)( us_Unicode + ( ushort )uc_Temp[1] );
		_TransferUnicodeToUTF8( us_Unicode, ( uchar* )sc_Temp );
		
		if( '\0' == sc_Temp[0] && '\0' == sc_Temp[1] && '\0' == sc_Temp[2] ) {
		} else {
			return False;
		}
	}
	return True;
}

