/*================================================================================================
//概要    ：現在値を設定する
//戻り値  ：True:成功  False:失敗
//備考    ：クラスが無効、設定値が最大値を超える場合は失敗する
================================================================================================*/
Bool PLBC_FreeSizeInput::setValue(
    float sf_nowValue,		// 設定値
    Bool b_isFixed )		// 確定未確定フラグ True:確定
{
	// クラスが無効の場合は何もしない
	if( !b_isEnable ) {
		return False;
	}
	// クラスの初期化処理を行う
	initClass();
	// 範囲チェック
	Bool b_Result = True;
	float sf_CollectNow = sf_nowValue;
	procCorrectNow( sf_CollectNow );
	float sf_CollectMin = sf_minValue;
	float sf_CollectMax = sf_maxValue;
	procCorrectMaxMin( sf_CollectMax, sf_CollectMin );
	int32_t i32_nowValue = ( int32_t )( ( sf_CollectNow + 0.0005f ) * 1000 );
	int32_t i32_maxValue = ( int32_t )( ( sf_CollectMax + 0.0005f ) * 1000 );
	if( i32_maxValue < i32_nowValue ) {
		// 補正した最大値に丸め込む.
		PLBC_FreeSizeInput::sf_nowValue = sf_CollectMax;
		b_Result = False;
	} else {
		// 補正した現在値を設定する
		PLBC_FreeSizeInput::sf_nowValue = sf_CollectNow;
		b_Result = True;
	}
	// 確定未確定フラグを設定する
	PLBC_FreeSizeInput::b_isFixed = b_isFixed;
	// 現在値を表示する
	showFreeSizeInput();
	return b_Result;
}
/*================================================================================================
//概要    ：現在値を取得する
================================================================================================*/
void PLBC_FreeSizeInput::getValue(
    float& rsf_nowValue )	// 現在値
{
	// クラスの初期化処理を行う
	initClass();
	// 現在値を取得する
	rsf_nowValue = PLBC_FreeSizeInput::sf_nowValue;
}
/*============================================================================================
//概要    ：現在値を初期値に戻す
//備考    ：クラスが無効の場合は失敗する
============================================================================================*/
Bool PLBC_FreeSizeInput::setInitialValue()
{
	// クラスが無効の場合は何もしない
	if( !b_isEnable ) {
		return False;
	}
	// クラスの初期化処理を行う
	initClass();
	// 現在値を初期値に戻す
	PLBC_FreeSizeInput::sf_nowValue = sf_initValue;
	// 現在値を表示する
	showFreeSizeInput();
	return True;
}
/*============================================================================================
//概要    ：初期値を設定する
//戻り値  ：True:成功  False:失敗
//備考    ：設定値が最小値-最大値の範囲外の場合は失敗する
============================================================================================*/
Bool PLBC_FreeSizeInput::setInitValue(
    float sf_initValue )	// 設定値
{
	// クラスの初期化処理を行う
	initClass();
	// 範囲チェック
	int32_t i32_initValue = ( int32_t )( ( sf_initValue + 0.0005f ) * 1000 );
	int32_t i32_minValue = ( int32_t )( ( sf_minValue + 0.0005f ) * 1000 );
	int32_t i32_maxValue = ( int32_t )( ( sf_maxValue + 0.0005f ) * 1000 );
	if( ( i32_initValue < i32_minValue ) || ( i32_maxValue < i32_initValue ) ) {
		return False;
	}
	// 初期値を設定する
	PLBC_FreeSizeInput::sf_initValue = sf_initValue;
	return True;
}
/*============================================================================================
//概要    ：初期値を取得する
============================================================================================*/
void PLBC_FreeSizeInput::getInitValue(
    float& rsf_initValue )	// 初期値
{
	// クラスの初期化処理を行う
	initClass();
	// 初期値を取得する
	rsf_initValue = PLBC_FreeSizeInput::sf_initValue;
}
/*============================================================================================
//概要    ：最小値を設定する
//戻り値  ：True:成功  False:失敗
//備考    ：設定値が最大値より大きい場合は失敗する
============================================================================================*/
Bool PLBC_FreeSizeInput::setMinValue(
    float sf_minValue )		// 設定値
{
	// クラスの初期化処理を行う
	initClass();
	// 範囲チェック
	int32_t i32_minValue = ( int32_t )( ( sf_minValue + 0.0005f ) * 1000 );
	int32_t i32_maxValue = ( int32_t )( ( sf_maxValue + 0.0005f ) * 1000 );
	if( i32_maxValue < i32_minValue ) {
		return False;
	}
	// 最小値を設定する
	PLBC_FreeSizeInput::sf_minValue = sf_minValue;
	return True;
}
/*============================================================================================
//概要    ：最小値を取得する
============================================================================================*/
void PLBC_FreeSizeInput::getMinValue(
    float& rsf_minValue )	// 最小値
{
	// クラスの初期化処理を行う
	initClass();
	// 最小値を取得する
	rsf_minValue = PLBC_FreeSizeInput::sf_minValue;
}
/*============================================================================================
//概要    ：最大値を設定する
//戻り値  ：True:成功  False:失敗
//備考    ：設定値が最小値より小さい場合は失敗する
============================================================================================*/
Bool PLBC_FreeSizeInput::setMaxValue(
    float sf_maxValue )	// 設定値
{
	// クラスの初期化処理を行う
	initClass();
	// 範囲チェック
	int32_t i32_minValue = ( int32_t )( ( sf_minValue + 0.0005f ) * 1000 );
	int32_t i32_maxValue = ( int32_t )( ( sf_maxValue + 0.0005f ) * 1000 );
	if( i32_maxValue < i32_minValue ) {
		return False;
	}
	// 最小値を設定する
	PLBC_FreeSizeInput::sf_maxValue = sf_maxValue;
	return True;
}
/*============================================================================================
//概要    ：最大値を取得する
============================================================================================*/
void PLBC_FreeSizeInput::getMaxValue(
    float& rsf_maxValue )	// 最大値
{
	// クラスの初期化処理を行う
	initClass();
	// 最小値を取得する
	rsf_maxValue = PLBC_FreeSizeInput::sf_maxValue;
}
/*================================================================================================
//概要    ：クラスの有効/無効を設定する。
//備考    ：無効に設定した場合、procClear,proc10Key,procButtonOnのイベントを受け付けない
================================================================================================*/
void PLBC_FreeSizeInput::setEnable(
    Bool b_isEnable )	// クラスが有効か？ True:有効  False:無効
{
	// クラスの初期化処理を行う
	initClass();
	// クラスの有効/無効を設定する。
	PLBC_FreeSizeInput::b_isEnable = b_isEnable;
}
/*================================================================================================
//概要    ：現在値をクリアーする
//備考    ：画面クラスでクリアーイベントが発生したときに、本関数をコールする
================================================================================================*/
void PLBC_FreeSizeInput::procClear(
    uchar uc_Option )	// クリアーキーイベントのオプション
{
	// クラスが無効の場合は何もしない
	if( !b_isEnable ) {
		return;
	}
	// クラスの初期化処理を行う
	initClass();
	// インチ(分数)の場合は、何もしない
	// クリアキーでは、何もしないが、「消去しない」キーではクリアする
	if( e_UnitSystem == TYPE_UnitSystemInch_Fraction && uc_Option != BTNID_KEY_AUXILERASEFRAMENONERASESET ) {
		return;
	}
	// 未確定にする
	b_isFixed = False;
	// 現在値をクリアする
	sf_nowValue = 0.00f;
	// 正常値
	b_isError = False;
	// 現在値を表示する
	showFreeSizeInput();
}
/*================================================================================================
//概要    ：テンキー入力に基づき現在値を更新する
//備考    ：画面クラスでテンキーイベントが発生したときに、本関数をコールする
================================================================================================*/
Bool PLBC_FreeSizeInput::proc10Key(
    uchar uc_Option		// テンキーイベントのオプション
    ,Bool  b_isDirect )	// ダイレクト入力処理.
{
	// クラスが無効の場合は何もしない
	if( !b_isEnable ) {
		return b_isError;
	}
	// クラスの初期化処理を行う
	initClass();
	// インチ(分数)の場合は、何もしない
	if( e_UnitSystem == TYPE_UnitSystemInch_Fraction ) {
		return b_isError;
	}
	// 0～9以外の場合は、何もしない
	if( 9 < uc_Option ) {
		return b_isError;
	}
	// 入力チェックに使うための最大値を補正する
	float sf_CollectMin = sf_minValue;
	float sf_CollectMax = sf_maxValue;
	procCorrectMaxMin( sf_CollectMax, sf_CollectMin );
	// 現在値を更新する
	sf_nowValue = proc10KeyInputF(
	                  sf_nowValue,		// 現在値
	                  sf_CollectMax,		// 最大値
	                  uc_Option,			// 入力値
	                  b_isDirect,
	                  EP_InputMaxLimitPattern_Refuse,	// 範囲オーバーの場合受け付けない
	                  &b_isError			// エラー発生中か？
	              );
	// 現在値を表示する
	showFreeSizeInput();
	return b_isError;
}
/*================================================================================================
//概要    ：ボタン入力処理を行う
//備考    ：画面クラスでボタンイベントが発生したときに、本関数をコールする
================================================================================================*/
void PLBC_FreeSizeInput::procButtonOn(
    uchar uc_Option )	// ボタンイベントのオプション
{
	// クラスが無効の場合は何もしない
	if( !b_isEnable ) {
		return;
	}
	// クラスの初期化処理を行う
	initClass();
	// 自分のパーツで発生したイベント以外は、処理しない
	switch( uc_GroupPartsNum ) {
		case 2:
			if( ( uc_Option < 110 ) || ( 112 < uc_Option ) ) {
				return;
			}
			break;
		case 3:
			if( ( uc_Option < 120 ) || ( 122 < uc_Option ) ) {
				return;
			}
			break;
		case 1:
		default:
			if( ( uc_Option < 100 ) || ( 102 < uc_Option ) ) {
				return;
			}
			break;
	}
	// ミリがインチかを判断
	Bool b_isInch;
	if( e_UnitSystem == TYPE_UnitSystemMM_Number ) {
		b_isInch = False;
	} else {
		b_isInch = True;
	}
	// 入力チェックに使うための最大値を補正する
	float sf_CollectMin = sf_minValue;
	float sf_CollectMax = sf_maxValue;
	procCorrectMaxMin( sf_CollectMax, sf_CollectMin );
	// 入力チェックに使うための現在値も補正する
	float sf_CollectNow = sf_nowValue;
	procCorrectNow( sf_CollectNow );
	switch( uc_Option ) {
		case 100:	// 整数・分数切替
		case 110:	// 整数・分数切替
		case 120:	// 整数・分数切替
			if( b_isInteger == True ) {
				// 現在が整数部の場合、分数部のパーツを非表示状態にし、整数部のパーツを表示状態にする.
				pBtx_FreeSize->showEnableShowAdd( pGra_FreeSizeUnderBar2, False );
				pBtx_FreeSize->showEnableShowAdd( pGra_FreeSizeUnderBar,  True );
			} else {
				// 現在が分数部の場合、整数部のパーツを非表示状態にし、分数部のパーツを表示状態にする.
				pBtx_FreeSize->showEnableShowAdd( pGra_FreeSizeUnderBar,  False );
				pBtx_FreeSize->showEnableShowAdd( pGra_FreeSizeUnderBar2, True );
			}
			// 整数部入力か？を更新
			b_isInteger = !b_isInteger;
			break;
		case 101:	// ダウン
		case 111:	// ダウン
		case 121:	// ダウン
			// 「なし」のときはダウンキーを受け付けてはいけない
			float sf_chackNashi;			// 「なし」判定用
			getValue( sf_chackNashi );	// 値を取得する
			if( sf_chackNashi != 0 ) {
				// 現在値を更新する
				sf_nowValue = procMmInchUpDown( sf_CollectNow, sf_CollectMax, sf_CollectMin, False, b_isInch, b_isInteger, True );
			} else {
				PBasicMessageProc::setBuzzerType( PCGE_BuzzerType_InputNg ); // 値を受付けないときは、入力無効音を鳴らす.
			}
			// 現在値を表示する
			showFreeSizeInput();
			break;
		case 102:	// アップ
		case 112:	// アップ
		case 122:	// アップ
			// 現在値を更新する
			sf_nowValue = procMmInchUpDown(
			                  sf_CollectNow, sf_CollectMax, sf_CollectMin,
			                  True, b_isInch, b_isInteger, True );
			// 現在値を表示する
			showFreeSizeInput();
			break;
		default : break;
	}
}

