/*============================================================================================
//概要    ：パーツなし画面外部キーボード対応チェック.
//引数    ：bl_chkFlg : True  対象画面のチェックと外部キーボードからの入力を取得できる状態かチェック.
//					  : False 対象画面のチェックのみ
//戻り値  ：Bool : True 対象画面、False 対象外画面.
//備考    ：パーツなしで外部キーボード入力値を取得する画面かチェックする.
============================================================================================*/
Bool PLBC_NoPartsUSBKeybord::chkNoKeybordGamen( Bool bl_chkFlg )
{
	Bool bl_chkGamen = False;
	if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		if( ( NULL == dynamic_cast< PCGC_HelpCom* >( PBasicMessageProc::getNowGamen() ) )	// ヘルプ画面判定.
		    && ( NULL == dynamic_cast< PUtilitycom* >( PBasicMessageProc::getNowGamen() ) )	// ユーティリティ画面及び管理者画面判定.
		    && ( False == ppc_SystemStatus->getServiceModeOn() )								// サービス画面判定.
		    && ( TYPE_USBKeyIPvGamen_v4 != Kbd_ScanFaxKeybordConv.isIPv4v6Gamen() )			// IPv4キーボード画面判定.
		    && ( TYPE_USBKeyIPvGamen_v6 != Kbd_ScanFaxKeybordConv.isIPv4v6Gamen() )			// IPv6キーボード画面判定.
		    && ( False == kbd_NoPartsUSBKeybord.getComKeyBordFlg() )							// キーボード画面判定.
		    && ( ( False == bl_chkFlg )
		         || ( ( True == bl_chkFlg ) && ( True == isEnableUSBKeyboard() ) ) )
		    && ( PLBD_Enl_KBD_Enlarge != kbd_NoPartsUSBKeybord.e_EnlKeybordState ) ) {				// 拡大キーボード画面判定.
			// 外部キーボードの設定が有効.
			bl_chkGamen = True;
		}
	}
	return( bl_chkGamen );
}

/*============================================================================================
//概要    ：USBキーボード文字列変換設定処理.
//戻り値  ：なし.
//備考    ：外部キーボード接続時、押下されたキーに応じて文字列を設定する.
============================================================================================*/
void PLBC_NoPartsUSBKeybord::convKeyCharCode( uint32_t ul_MsgParam, char* sc_KeyCode )
{
	int32_t	i32_TmpBuff = 0;
	char	sc_UsbKeyCharCode[3];

	memset( sc_UsbKeyCharCode, 0x00, sizeof( sc_UsbKeyCharCode ) );

	// メッセージパラメータから文字列を抜き出す.
	sc_UsbKeyCharCode[0] = (char)( ul_MsgParam >> 24 );
	i32_TmpBuff = ul_MsgParam << 8;
	sc_UsbKeyCharCode[1] = (char)(i32_TmpBuff >> 24);
	i32_TmpBuff = ul_MsgParam << 16;
	sc_UsbKeyCharCode[2] = (char)(i32_TmpBuff >> 24);

// 本来ならコピー先の大きさに合わせたコーディングするべきだが、大きさはこの関数からは不明のため.
// sc_UsbKeyCharCodeで行う。pcgcom\pcgcomg\pnlmain.cppで唯一コールしてるが 3 なのでこれで問題なし。.
	memcpy( sc_KeyCode, sc_UsbKeyCharCode, sizeof( sc_UsbKeyCharCode ) );

}
/*============================================================================================
//概要    ：外部キーボード入力メッセージパラメータ設定処理.
//戻り値  ：Bool : True 対象キー入力、False 対象外キー入力.
//備考    ：外部キーボード接続時、キー押下によりメッセージ送信を行う為のパラメータ設定を行う.
============================================================================================*/
Bool PLBC_NoPartsUSBKeybord::setUsbKeyMsgParam( PMGS_PnlMgrParam* p_MsgParam, PCGC_PanelMainMsg* st_msg, char* sc_UsbKeyCharCode )
{
	Bool b_isSetCode = False;
	p_MsgParam->taskID  = PM_TASKID_PANEL;
	p_MsgParam->message = MS_10Key;
	p_MsgParam->type = st_msg->type;

	// テンキーの文字列設定処理.
	if( '*' == sc_UsbKeyCharCode[0] ) {
		p_MsgParam->option = 0x0b;
		b_isSetCode = True;
	} else if( '#' == sc_UsbKeyCharCode[0] ) {
		p_MsgParam->option = 0x0a;
		b_isSetCode = True;
	} else if( ( '0' <= sc_UsbKeyCharCode[0] ) && ( '9' >= sc_UsbKeyCharCode[0] ) ) {
		p_MsgParam->option = (uchar)( ( uchar )sc_UsbKeyCharCode[0]-0x30 );
		b_isSetCode = True;
	} else {
		;
	}

	return b_isSetCode;
}

