// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
// ----------------------------------------------------------------------------------.
/**
 *	@brief	未確定文字の濁点・半濁点・小文字の有効状態判定.
 *	@param[in]		判定文字.
 *	@retval			有効状態.
 */
// ----------------------------------------------------------------------------------.
uchar getEnableReplaceChar( char* psc_SrcChar )
{
	PNLD_CharType e_CharType = PNLD_CharType_None;
	uchar uc_TableIndex = 0;
	
	if( NULL == psc_SrcChar ) {
		return e_CharType;
	}
	
	short ss_CompMax = (sizeof( tbl_ReplaceChar ) / sizeof( PNLS_ReplaceChar_Table ));
	for( uc_TableIndex = 0; uc_TableIndex < ss_CompMax; uc_TableIndex++ ) {
		if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_NoneChar ) ){
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar ) ) {
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar ) ) {
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_SmallChar ) ) {
			break;
		}
	}
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33779 [ABV.GENERAL] When the TableIndex is greater than or equalt to 67,return the PNLD_CharType_None.
//	// 入力文字に変換対象がない.
//	if( uc_TableIndex > ss_CompMax ) {
	if( uc_TableIndex >= ss_CompMax ) {
		return e_CharType;
	}
	
	if( EndOfString != tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar[0] )  {
		e_CharType |= PNLD_CharType_Dakuten;
	}
	
	if( EndOfString != tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar[0] ) {
		e_CharType |= PNLD_CharType_HanDakuten;
	}
	
	if( EndOfString != tbl_ReplaceChar[uc_TableIndex].sc_SmallChar[0] ) {
		e_CharType |= PNLD_CharType_Small;
	}
	
	return e_CharType;
}

// ----------------------------------------------------------------------------------.
/**
 *	@brief	濁点・半濁点・小文字の置き換え.
 *	@param[in]		オプション値.
 *	@param[in]		入力文字列.
 *	@param[out]		置き換え文字.
 *	@param[out]		キーボードタイプ.
 *	@retval			なし.
 */
// ----------------------------------------------------------------------------------.
void getReplaceChar( uchar uc_Option, char* psc_SrcChar, char *psc_DstChar, KeybordType& e_KeyBordType )
{
	PNLD_CharType e_SrcCharType	= PNLD_CharType_None;		// 入力文字種類（濁点、半濁点）.
	PNLD_CharType e_DstCharType	= PNLD_CharType_None;		// 入力文字種類（濁点、半濁点）.
	uchar uc_TableIndex					= 0;						// 変換テーブル位置.
	short ss_CompMax					= 0;

	if( NULL == psc_SrcChar || NULL == psc_DstChar ) {
		return;
	}
	
	// 変換対象文字チェック.
	ss_CompMax = (sizeof( tbl_ReplaceChar ) / sizeof( PNLS_ReplaceChar_Table ));
	for( uc_TableIndex = 0; uc_TableIndex < ss_CompMax; uc_TableIndex++ ) {
		if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_NoneChar ) ){
			e_SrcCharType = PNLD_CharType_None;
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar ) ) {
			e_SrcCharType = PNLD_CharType_Dakuten;
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar ) ) {
			e_SrcCharType = PNLD_CharType_HanDakuten;
			break;
		}
		else if( 0 == strcmp( psc_SrcChar, tbl_ReplaceChar[uc_TableIndex].sc_SmallChar ) ) {
			e_SrcCharType = PNLD_CharType_Small;
			break;
		}
	}

// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33780 [ABV.GENERAL] When the TableIndex is greater than or equalt to 67,return the PNLD_CharType_None.	
//	// 入力文字に変換対象がない.
//	if( uc_TableIndex > ss_CompMax ) {
	if( uc_TableIndex >= ss_CompMax ) {
		return;
	}
	
	// 変換先の文字種類を決定.
	switch( uc_Option ) {
		case 155:			// 濁点入力.
			switch( e_SrcCharType ) {
				case PNLD_CharType_None:			e_DstCharType = PNLD_CharType_Dakuten;			break;
				case PNLD_CharType_Dakuten:			e_DstCharType = PNLD_CharType_None;				break;
				case PNLD_CharType_HanDakuten:		e_DstCharType = PNLD_CharType_Dakuten;			break;
				case PNLD_CharType_Small:			e_DstCharType = PNLD_CharType_Dakuten;			break;
				default:	break;
			}
			break;
		case 156:		// 半濁点入力.
			switch( e_SrcCharType ) {
				case PNLD_CharType_None:			e_DstCharType = PNLD_CharType_HanDakuten;		break;
				case PNLD_CharType_Dakuten:			e_DstCharType = PNLD_CharType_HanDakuten;		break;
				case PNLD_CharType_HanDakuten:		e_DstCharType = PNLD_CharType_None;				break;
				case PNLD_CharType_Small:			e_DstCharType = PNLD_CharType_HanDakuten;		break;
				default:	break;
			}
			break;
		case 157:			// 小文字変換.
			switch( e_SrcCharType ) {
				case PNLD_CharType_None:			e_DstCharType = PNLD_CharType_Small;			break;
				case PNLD_CharType_Dakuten:			e_DstCharType = PNLD_CharType_Small;			break;
				case PNLD_CharType_HanDakuten:		e_DstCharType = PNLD_CharType_Small;			break;
				case PNLD_CharType_Small:			e_DstCharType = PNLD_CharType_None;				break;
				default:	break;
			}
			break;
		default:
			break;
	}

	e_KeyBordType = PLBD_KBT_JapanAnother;
	// 変換処理.
	switch( e_DstCharType ) {
		case PNLD_CharType_None:		// 通常文字へ.
// comment 2022/10/13 FPT.ThanhLH11 [IT6_2.2MR4][ALL MACHINE][Klocwork]ABV.GENERAL.
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33780 [ABV.GENERAL] Strcpy is changed into strncpy to avoid buffer overflow.
//			strcpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_NoneChar );
			// strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_NoneChar, sizeof(psc_DstChar)-1 );
			strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_NoneChar, PCGD_SearchKeyCode - 1 );
			e_KeyBordType = PLBD_KBT_Japan;
			break;
		case PNLD_CharType_Dakuten:		// 濁点文字へ.
// comment 2022/10/13 FPT.ThanhLH11 [IT6_2.2MR4][ALL MACHINE][Klocwork]ABV.GENERAL.
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33780 [ABV.GENERAL] Strcpy is changed into strncpy to avoid buffer overflow.
//			strcpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar );
			// strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar, sizeof(psc_DstChar)-1 );
			strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_DakutenChar, PCGD_SearchKeyCode - 1 );
			break;
		case PNLD_CharType_HanDakuten:	// 半濁点文字へ.
// comment 2022/10/13 FPT.ThanhLH11 [IT6_2.2MR4][ALL MACHINE][Klocwork]ABV.GENERAL.
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33780 [ABV.GENERAL] Strcpy is changed into strncpy to avoid buffer overflow.
//			strcpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar );
			// strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar, sizeof(psc_DstChar)-1 );
			strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_HanDakutenChar, PCGD_SearchKeyCode - 1 );
			break;
		case PNLD_CharType_Small:		// 小文字へ.
// comment 2022/10/13 FPT.ThanhLH11 [IT6_2.2MR4][ALL MACHINE][Klocwork]ABV.GENERAL.
// Comment 2015/10/23 [HCLT_Kalaiyarasi] [CQ_516896] Klocwork Changes ID: 33780 [ABV.GENERAL] Strcpy is changed into strncpy to avoid buffer overflow.
//			strcpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_SmallChar );
			// strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_SmallChar, sizeof(psc_DstChar)-1 );
			strncpy( psc_DstChar, tbl_ReplaceChar[uc_TableIndex].sc_SmallChar, PCGD_SearchKeyCode - 1 );
			break;
		default:
			break;
	}
}
// comment 2023/06/14 Sky中村 [IT6_2.3]バルト三国、ウェールズ語対応 add.
/**
 *	@brief	ASCIIキーボード固定で表示する言語かどうか.
 *	@param[out]		True/False.
 *	@retval			なし.
 */
Bool PnlComIsForceASCIIKeyboard( void )
{
	TYPE_Language e_Lang = PnlComGetLanguage(False);

	// 表示言語に関わらずASCIIキーボード表示.
	if ( TYPE_LanguageArabic == e_Lang			// アラビア語
	  || TYPE_LanguageThai == e_Lang			// タイ語
	  || TYPE_LanguageVietnam == e_Lang			// ベトナム語
	  || TYPE_LanguageHebrew == e_Lang			// ヘブライ語
	  || TYPE_LanguageEstonian == e_Lang		// エストニア語
	  || TYPE_LanguageLatvian == e_Lang			// ラトビア語
	  || TYPE_LanguageLithuanian == e_Lang		// リトアニア語
	  || TYPE_LanguageWelsh == e_Lang			// ウェールズ語
	) {
		return True;
	} else {
		return False;
	}
}

